(function(G){'use strict';const Y=G.YY;Y.STORY_REVISION='sixteen-v3';Y.STORY_SOURCE_HASH="eeb1257adde06f004a9f29b8705c8005714797b669df198b16efdd801b646904";Y.CAMPAIGN=[{"id":"ch0","title":"序章 · 掉磅","date":"6.26","scene":"stringing","blurb":"线穿好之后会慢慢松掉，叫“掉磅”。人也一样。","venue":"homecourt","act":"听见","stages":[{"id":"0-1","title":"掉磅","scene":"stringing","date":"6 月 26 日 清晨 · 丁记穿线铺","desc":"★磅数误差不超过 1 磅 ★全程不断线","knowledge":["v3_01"],"kind":"minigame","steps":[{"t":"cinema","scene":"stringing","title":"掉磅","caption":"6 月 26 日 清晨 · 丁记穿线铺","transition":"feather","intro":true,"uid":"0-1:0"},{"t":"dialog","scene":"stringing","lines":[["nar","黑屏。“嗒。”停一下，又一声“嗒”，是穿线机夹头咬住线、往回拉的声音。字幕浮现：高考出分后第二天。","stage","clamp",{"silent":false,"cue":"clamp","white":false,"black":true}],["nar","画面亮起。老式穿线铺，吊扇慢慢转，墙上挂满待取的球拍，每支拍柄上都夹着小纸条：“刘姨 24 磅”“菜场老张 别穿太紧”。门外整条街晒着白鹅毛，一只鹅从门口走过，看了丁丁一眼。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","丁——！丁！你多少分？！","surprise",null,{"direction":"门外，人还没到声音先到","speaker":"瑞宝"}],["dingding","早上好。","talk",null,{"direction":"不抬头","speaker":"丁丁"}],["ruibao","我问你多少分。","talk",null,{"direction":"叼着包子冲进来","speaker":"瑞宝"}],["dingding","这支拍子二十四磅，主人是菜场卖鱼的刘姨。她扣杀比你狠。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","……你是不是考得特别好，不好意思说？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","够读机械了。省城的。你呢？","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","够读食品工程。南京的。（停顿）都挺好。","think",null,{"direction":"一口咬掉半个包子，眼睛看着门外","speaker":"瑞宝"}],["dingding","那恭喜。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","所以，咱俩这辈子最后一个能一起混的暑假，你打算全拿来穿线？","think",null,{"direction":"","speaker":"瑞宝"}],["dingding","穿线怎么了。帮我扶一下。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","先穿竖线，再穿横线。拖动线头穿过对应的孔，到位后按住“拉线”，指针停在目标磅数时松手，夹头就会咬住。","lesson",null,{"title":"教学·穿线"}],["nar","拉得太松，球打出去发飘；拉得太紧会断。","lesson",null,{"title":"教学·穿线"}]],"when":null,"uid":"0-1:1"},{"t":"minigame","game":"stringing","title":"给刘姨穿一支二十四磅","tension":24,"uid":"0-1:2"},{"t":"dialog","scene":"stringing","lines":[["ruibao","你手指上那道疤，到现在还没消啊。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","小时候穿线被线勒的。","talk",null,{"direction":"看了一眼食指","speaker":"丁丁"}],["ruibao","多小的时候？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","……忘了。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"0-1:3"},{"t":"card","card":"v3_01","uid":"0-1:4"},{"t":"dialog","scene":"stringing","lines":[["ruibao","走，河堤，打一会儿。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","我四年没打了。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","我知道。从你师兄走的那年。（停顿）就一会儿。我请你吃包子。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","包子本来就是你家的。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","那更说明我有诚意。","talk",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"0-1:5"}],"rewards":{"cards":["v3_01"],"chars":[],"gear":[]},"feather":null},{"id":"0-2","title":"河堤","scene":"riverbank","date":"6 月 26 日 上午 · 江堤下的水泥空地，球网是两根竹竿拴一根绳","desc":"★完美击球 3 次 ★一次都不挥空","knowledge":["v3_02","v3_03"],"kind":"drill","steps":[{"t":"cinema","scene":"riverbank","title":"河堤","caption":"6 月 26 日 上午 · 江堤下的水泥空地，球网是两根竹竿拴一根绳","transition":"feather","intro":true,"uid":"0-2:0"},{"t":"dialog","scene":"riverbank","lines":[["nar","江风，芦苇，远处货船鸣笛。瑞宝用拍子挑着一桶旧球走过来，像挑着一扁担包子。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","规则很简单：我喂，你接。接不到你请我吃包子。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","包子是你家的。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","所以你永远欠我的。","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","按住左下 ← / →（键盘 A / D）移动，松开就停。","lesson",null,{"title":"教学·移动"}],["nar","羽毛球是先到位，再挥拍：人不到，拍子再快也没用。","lesson",null,{"title":"教学·移动"}],["dingding","……腿不是我的。","talk",null,{"direction":"跑了两步，差点绊倒","speaker":"丁丁"}],["ruibao","腿是你的，就是四年没上油。","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","地上的黄圈是球的预计落点。站到黄圈稍后一点，按「高远」（J）。","lesson",null,{"title":"教学·高远球"}],["nar","按键后大约 0.17 秒是挥拍窗口，0.11 秒左右最准，拍面闪金光就是完美击球。","lesson",null,{"title":"教学·高远球"}],["nar","球在很低的位置时，「高远」会自动变成挑球。","lesson",null,{"title":"教学·高远球"}]],"when":null,"uid":"0-2:1"},{"t":"drill","as":"dingding","skills":false,"def":{"name":"先到位，再挥拍","judge":"receive","goal":{"need":4,"total":10},"feeds":{"intro":1}},"stars":[],"uid":"0-2:2"},{"t":"dialog","scene":"riverbank","lines":[["ruibao","哟。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","……手还记得。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","你师兄以前说的，打高远球——","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","“要像把球挂到天上。”（停顿）我不记得了。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","你刚刚背出来了。","talk",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"0-2:3"},{"t":"card","card":"v3_02","uid":"0-2:4"},{"t":"dialog","scene":"riverbank","lines":[["nar","按「吊球」（K）把球轻轻送到对方网前。人离网很近时，吊球会变成网前轻放，球贴着网落下。","lesson",null,{"title":"教学·吊球"}],["nar","按「起跳」（W／空格），在空中也能击球。高球起跳击打，出手点更高、更快。","lesson",null,{"title":"教学·起跳"}],["nar","起跳要花体力（头像旁的绿条）。","lesson",null,{"title":"教学·起跳"}]],"when":null,"uid":"0-2:5"},{"t":"drill","as":"dingding","skills":false,"def":{"name":"把轻球放到网前","judge":"drop","goal":{"need":4,"total":10},"feeds":{"drop":1}},"stars":[],"uid":"0-2:6"},{"t":"dialog","scene":"riverbank","lines":[["ruibao","完了，我喂球喂得比你还累。","talk",null,{"direction":"喘着气捡球","speaker":"瑞宝"}],["dingding","因为你在边喂边吃。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"0-2:7"},{"t":"card","card":"v3_03","uid":"0-2:8"}],"rewards":{"cards":["v3_02","v3_03"],"chars":[],"gear":[]},"feather":null},{"id":"0-3","title":"三个人的球","scene":"riverbank","date":"6 月 26 日 中午 · 河堤","desc":"★扣杀得分 1 次 ★让对手得分不超过 4 分","knowledge":["v3_04","v3_05"],"kind":"match","steps":[{"t":"cinema","scene":"riverbank","title":"三个人的球","caption":"6 月 26 日 中午 · 河堤","transition":"feather","intro":true,"uid":"0-3:0"},{"t":"dialog","scene":"riverbank","lines":[["nar","三辆自行车冲下河堤。领头的男生红球衣，车筐里插着一本厚笔记本。后面跟着两个女生，一个背着望远镜包，一个车把上挂了一串彩色蝴蝶结，迎着风一晃一晃。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","丁丁！你终于肯出门了。我算过，你整个高中参加集体活动的概率是 11%。","think",null,{"direction":"","speaker":"小红"}],["dingding","你算这个干嘛。","think",null,{"direction":"","speaker":"丁丁"}],["xiaohong","习惯。","talk",null,{"direction":"","speaker":"小红"}],["xingxing","别理他，他连我们三个骑车谁先到都算了。","think",null,{"direction":"跳下车","speaker":"星星"}],["xiaohong","算对了。","think",null,{"direction":"","speaker":"小红"}],["xingxing","你把自己算成第一了，结果是我。","think",null,{"direction":"","speaker":"星星"}],["xiaohong","……误差。","talk",null,{"direction":"","speaker":"小红"}],["nar","第三个女生最后下车，摘下头盔，头发被风吹乱。她冲丁丁挥了挥手。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","丁丁！你那会儿给我穿的拍子，我还在用呢。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……嗯。","talk",null,{"direction":"","speaker":"丁丁"}],["dingding","二十二磅，BG65，白色。","thought",null,{"title":"心里话"}],["ruibao","你脸红了。","shy",null,{"direction":"压低声音","speaker":"瑞宝"}],["dingding","晒的。","shy",null,{"direction":"压低声音","speaker":"丁丁"}],["ruibao","现在是阴天。","talk",null,{"direction":"","speaker":"瑞宝"}],["xiaohong","来一局？七分制，我让你两分。","talk",null,{"direction":"","speaker":"小红"}],["dingding","不用让。","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","那我让你一分。","talk",null,{"direction":"","speaker":"小红"}],["dingding","……都说了不用让。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","起跳后，在足够高的位置按「扣杀」（L）。扣杀很快很重，但要消耗大量体力。","lesson",null,{"title":"教学·扣杀"}],["nar","体力：起跳消耗 12，扣杀消耗 24。停下高消耗动作 1 秒后开始恢复，每分结束回满。体力不够时只能低跳，扣杀会变成平抽。","lesson",null,{"title":"教学·扣杀"}],["nar","击球瞬间按住“向网”方向：高远变平高、吊球变劈吊、扣杀打近。","lesson",null,{"title":"教学·方向修饰"}],["nar","按住“向后”：扣杀打深。","lesson",null,{"title":"教学·方向修饰"}],["nar","发球时头顶会出现力度条，指针越靠中间，发球越稳。","lesson",null,{"title":"教学·发球"}]],"when":null,"uid":"0-3:1"},{"t":"card","card":"v3_04","uid":"0-3:2"},{"t":"match","as":"dingding","opp":"xiaohong","field":"reality","level":"easy","target":7,"cap":11,"allowLoss":true,"stars":[],"skills":false,"uid":"0-3:3"},{"t":"dialog","scene":"riverbank","lines":[["xiaohong","你……四年没打？","talk",null,{"direction":"","speaker":"小红"}],["dingding","嗯。","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","我要重新拟合一下你。","talk",null,{"direction":"","speaker":"小红"}]],"when":{"outcome":true},"uid":"0-3:4"},{"t":"dialog","scene":"riverbank","lines":[["xiaohong","不错了。四年没打，按我的模型应该是 7 比 1，你拿了不止一分。","talk",null,{"direction":"","speaker":"小红"}],["dingding","你能不能别总算我。","think",null,{"direction":"","speaker":"丁丁"}]],"when":{"outcome":false},"uid":"0-3:5"},{"t":"card","card":"v3_05","uid":"0-3:6"},{"t":"dialog","scene":"riverbank","lines":[["nar","比赛结束，大家坐在台阶上喝汽水。冉冉拿起一只球，冲丁丁扬了扬。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","丁丁，接我一个。","talk",null,{"direction":"","speaker":"冉冉"}]],"when":null,"uid":"0-3:7"},{"t":"drill","as":"dingding","skills":false,"def":{"name":"接住冉冉的网前小球","judge":"receive","goal":{"need":1,"total":99},"feeds":{"intro":1},"gentle":true},"stars":[],"uid":"0-3:8"},{"t":"dialog","scene":"riverbank","lines":[["ranran","接住啦。","smile",null,{"direction":"笑","speaker":"冉冉"}],["nar","冉冉随手把球放在台阶上，转身去和星星说话。丁丁看着那只球。看了很久。趁没人注意，他把球放进了口袋。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","镜头往后拉。瑞宝坐在台阶最上面，嚼着包子，看见了，什么都没说。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xingxing","对了，英仙座流星雨八月十二号极大，你们要不要来天台看？","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","来。","talk",null,{"direction":"马上翻开笔记本，写下“8/12”，画了三个圈","speaker":"小红"}],["xingxing","我还没说几点。","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","几点都来。","talk",null,{"direction":"","speaker":"小红"}]],"when":null,"uid":"0-3:9"}],"rewards":{"cards":["v3_04","v3_05"],"chars":[],"gear":["r_flex"]},"feather":null},{"id":"0-4","title":"蒸笼","scene":"backroom","date":"6 月 26 日 夜 · 穿线铺后屋","desc":"★用技能救起 1 个球 ★用“机械回收”返还能量 1 次","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"backroom","title":"蒸笼","caption":"6 月 26 日 夜 · 穿线铺后屋","transition":"feather","intro":true,"uid":"0-4:0"},{"t":"dialog","scene":"backroom","lines":[["nar","后屋堆满零件。工作台正中立着一个怪东西：下半截是旧发球机，上半截是一口竹蒸笼，两侧伸出穿线机的夹头，蒸笼盖上接了一圈线，连着两个改装头环。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","……这是我家去年扔的那口蒸笼？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","嗯。竹子透气，软木不会受潮。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","你拿我家蒸笼干了什么？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","听球。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","听什么？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","小时候，师兄画过一张图。说球是有记性的：打过的球，羽片会弯一点点，软木会压出一点点印子，就像录音带。我照着做了一个，没响过。（停顿）去年开始，我自己改了一年。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","镜头扫过墙上一张发黄的蜡笔画：一个蒸笼似的机器，旁边一行小孩字“听球”，角上是更歪的一行：“丁丁造”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","那它现在响了吗？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","今天之前，没有。（举起下午和小红打的那只球）今天的球，还没凉。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","球放进蒸笼。蒸汽一样的白光从竹缝里漏出来，丁丁、瑞宝各戴上一个头环，画面像被吹散的鹅毛一样碎开，又重新拼起来。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false}]],"when":null,"uid":"0-4:1"},{"t":"dialog","scene":"memory-river","lines":[["nar","第一次进入羽场。 还是下午的河堤，但江面是银色的，空中飘着发光的羽毛碎片。小红站在对面，周围浮着淡橙色的角度线。丁丁低头，发现自己的球拍边上多了一截闪着绿光的机械臂。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-entry"}],["ruibao","丁丁！你背后长东西了！","talk",null,{"direction":"声音从天上传来","speaker":"瑞宝","cg":"cg-entry"}],["dingding","……这是球记得的样子。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-entry"}],["dingding","球不记得我长什么样，只记得我打它的时候在想什么。（看着机械臂）我在想……够不着。","think",null,{"direction":"","speaker":"丁丁","cg":"cg-entry"}],["nar","头像下方的能量条：每打一拍 +3，完美击球再 +2，救起低球或接杀再 +3；丢一分 +13，赢一分 +4。","lesson",null,{"title":"教学·能量","cg":"cg-entry"}],["nar","两个技能键共用这一条能量，够技能的消耗就能放。","lesson",null,{"title":"教学·能量","cg":"cg-entry"}],["nar","按住技能键拖动，选一个角度伸出长拍，拍头会自动拦截扣杀之类的重球。","lesson",null,{"title":"教学·伸缩长拍（能量 25）","cg":"cg-entry"}],["nar","拍子伸出去以后再按一次同一个键，扫击回收。","lesson",null,{"title":"教学·伸缩长拍（能量 25）","cg":"cg-entry"}],["nar","拖到 × 或拖得太远就是取消；只点一下按默认方向释放。","lesson",null,{"title":"教学·伸缩长拍（能量 25）","cg":"cg-entry"}],["nar","双头拍绕着身体转圈迎球；再按住拖动，选方向定向扫回，打中之后再按一次快速收回。","lesson",null,{"title":"教学·双头旋拍（能量 25）","cg":"cg-entry"}],["nar","拖动抛出接球器，飞出、停留或空手返回时最多接住一次来球。接住后自动带回拍前垫高，由你按高远、吊球或扣杀打出下一拍。","lesson",null,{"title":"教学·悠悠球拍","cg":"cg-entry"}],["nar","没接到时再按可提前收回；手柄可以正常击球。收招时再按快速回收，返还6能量。","lesson",null,{"title":"教学·悠悠球拍","cg":"cg-entry"}],["nar","装置打中球后过载 3 秒，扫击范围更大。收招之后再按一次，立刻回收，返还 6 能量。","lesson",null,{"title":"教学·被动「机械回收」","cg":"cg-entry"}],["nar","被动不用按，一直生效。比赛前你可以从三个主动技能里带两个上场。","lesson",null,{"title":"教学·被动「机械回收」","cg":"cg-entry"}]],"when":null,"uid":"0-4:2"},{"t":"match","as":"dingding","opp":"xiaohong","field":"memory","level":"normal","target":3,"cap":5,"allowLoss":true,"stars":[],"training":true,"intentSide":0,"intents":["冉冉在看","冉冉在看","冉冉还在看"],"venue":"memorycourt","uid":"0-4:3"},{"t":"dialog","scene":"memory-river","lines":[["dingding","……够着了。","talk",null,{"direction":"救起一个怎么都够不着的球","speaker":"丁丁","cg":"cg-entry"}],["nar","打完最后一拍，记忆显影完成。这时候，丁丁头顶浮起一行字。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-entry"}],["nar","冉冉在看","intent",null,{"title":"球记得的念头","cg":"cg-entry"}],["nar","冉冉在看","intent",null,{"title":"球记得的念头","cg":"cg-entry"}],["nar","冉冉还在看","intent",null,{"title":"球记得的念头","cg":"cg-entry"}],["ruibao","哈——哈哈哈哈——","smile",null,{"direction":"天上的声音停了三秒，然后爆笑","speaker":"瑞宝","cg":"cg-entry"}]],"when":null,"uid":"0-4:4"},{"t":"dialog","scene":"backroom","lines":[["nar","丁丁一把扯下头环。画面猛地切回后屋，蒸笼冒着白气。瑞宝笑得从凳子上滑下去。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-thought"}],["dingding","……这个是 bug。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["ruibao","这不是 bug，这是你。","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-thought"}],["dingding","关掉，我去改代码。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["ruibao","改什么？早知道了。全镇都知道。（停顿）除了她。","sad",null,{"direction":"擦眼泪","speaker":"瑞宝","cg":"cg-thought"}],["nar","安静。蒸笼的竹缝里还漏着一点白光。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false,"cg":"cg-thought"}],["ruibao","那只呢？","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-thought"}],["dingding","哪只。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["ruibao","你兜里那只。","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-thought"}],["nar","丁丁慢慢把冉冉那只球掏出来，放在工作台上，看了很久。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-thought"}],["ruibao","读不读？","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-thought"}],["dingding","……不读。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["ruibao","为啥？","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-thought"}],["dingding","刚才被读的人是我。挺……挺不好受的。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["dingding","那是她的球。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["nar","丁丁撕下一截胶带，写上“冉冉 6.26 不读”，贴在球上，放进抽屉，关上。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-thought"}],["ruibao","你这人。","talk",null,{"direction":"看了他一会儿","speaker":"瑞宝","cg":"cg-thought"}],["dingding","怎么了。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["ruibao","没怎么。挺好的。","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-thought"}],["nar","瑞宝的手机“叮”一声，他扫了一眼，笑容慢慢收起来，把屏幕转向丁丁。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-thought"}],["nar","【鹅湾新闻】南岸体育冠名“鹅湾杯”：全国首个“羽场联赛”试点落户鹅湾，赛事期间全镇免费供球。","stage",null,{"cg":"cg-thought"}],["nar","配图是发布会现场。台上站着一个穿白衬衫的年轻男人，背挺得很直，正对镜头微笑。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-thought"}],["ruibao","丁丁，这是……","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-thought"}],["dingding","……师兄。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-thought"}],["nar","丁丁食指上那道旧疤，在台灯下发白。黑屏。“嗒。”","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-thought"}]],"when":null,"uid":"0-4:5"}],"rewards":{"cards":[],"chars":["dingding"],"gear":[]},"feather":null}]},{"id":"ch1","title":"第一章 · 移动城墙","date":"6.28—7.5","scene":"bakery","blurb":"包子、七个老粉和一张垫蒸笼的纸。我们心里的墙，长什么样？","venue":"homecourt","act":"听见","stages":[{"id":"1-1","title":"早高峰","scene":"bakery","date":"6 月 28 日 清晨 · 王记包子铺","desc":"三张小订单 · 菜包、肉包、加急单","knowledge":["v3_06"],"kind":"minigame","steps":[{"t":"cinema","scene":"bakery","title":"早高峰","caption":"6 月 28 日 清晨 · 王记包子铺","transition":"ink","intro":true,"uid":"1-1:0"},{"t":"dialog","scene":"bakery","lines":[["nar","早上六点，蒸笼一摞一摞冒着白汽。排队的人从店里排到穿线铺门口。瑞妈一个人在灶台前，额头全是汗。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruima","丁丁！来得正好，帮姨接包子！","talk",null,{"direction":"","speaker":"瑞妈"}],["dingding","接？","talk",null,{"direction":"","speaker":"丁丁"}],["ruima","老王腰闪了，在楼上躺着刷手机呢。我一个人装不过来，蒸笼出锅我扔，你接了装袋！","talk",null,{"direction":"","speaker":"瑞妈"}],["ruibao","妈，你不能这么对待一个准大学生。","talk",null,{"direction":"","speaker":"瑞宝"}],["ruima","准大学生更要锻炼！","talk",null,{"direction":"","speaker":"瑞妈"}],["nar","瑞妈每次扔包子前都会喊一声“接！”。喊声出来的那一瞬间，轻轻点一下「起跳」，做一个小跳，落地后马上移动，起步会快很多。","lesson",null,{"title":"教学·启动步"}],["nar","这个小跳就是启动步（垫步）。打球的时候，对手出手那一刻做它。","lesson",null,{"title":"教学·启动步"}]],"when":null,"uid":"1-1:1"},{"t":"minigame","game":"baozi","title":"接！先垫一步","goal":9,"uid":"1-1:2"},{"t":"dialog","scene":"bakery","lines":[["nar","丁丁靠在门框上喘气。蒸笼有一条腿短一截，底下垫着一张折了好几折的纸。丁丁顺手想把它抽出来垫平。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","垫蒸笼的！别动！","talk",null,{"direction":"一把按住，抢回去塞回原处","speaker":"瑞宝"}],["dingding","……我就想帮你垫平。","think",null,{"direction":"","speaker":"丁丁"}],["ruibao","它就喜欢斜着。","talk",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"1-1:3"},{"t":"card","card":"v3_06","uid":"1-1:4"},{"t":"dialog","scene":"bakery","lines":[["ruibao","对了，你那蒸笼能不能让两个人一起进去打？不读旧球，就……现打。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","空场？理论上可以。没有记忆，只开一块场地。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","那我想看看，我在球心里长什么样。","think",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"1-1:5"}],"rewards":{"cards":["v3_06"],"chars":[],"gear":[]},"feather":null},{"id":"1-2","title":"墙","scene":"emptyfield","date":"6 月 28 日 夜 · 听球机空场","desc":"★地板开球得分 1 次 ★回锅再炒收回后再打得分 1 次","knowledge":["v3_07"],"kind":"match","steps":[{"t":"cinema","scene":"emptyfield","title":"墙","caption":"6 月 28 日 夜 · 听球机空场","transition":"ink","intro":true,"uid":"1-2:0"},{"t":"dialog","scene":"emptyfield","lines":[["nar","空场是一片没有天花板的木地板球场，四周是漂浮的蒸汽。瑞宝出现时，身后升起一扇灰白色的砖墙，头顶悬着一口巨大的蒸笼盖。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","……我这么高大的吗？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","你心里就是这么想的。","think",null,{"direction":"","speaker":"丁丁"}],["ruibao","那我心里挺自信啊。","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","地板开球打过网、回锅再炒收回后再打、肉包成功释放，每次 +6 能量，每分最多 18。","lesson",null,{"title":"教学·被动「越折腾，越来劲」"}],["nar","肉包和地板开球配在一起，会变成蒸汽地板。","lesson",null,{"title":"教学·被动「越折腾，越来劲」"}],["nar","拖动选方向，把球往地上砸。你身后和头顶会临时立起两面墙；球在地板、两面墙上各弹一次，每弹一次加速一次，冒一股蒸汽。","lesson",null,{"title":"教学·地板开球（能量 25）"}],["nar","球砸地时还会震住对手一下。","lesson",null,{"title":"教学·地板开球（能量 25）"}],["nar","（对面看到的提示：看蒸汽，站在中场等它出来。）","lesson",null,{"title":"教学·地板开球（能量 25）"}],["ruibao","我就说嘛，包子铺后厨那两面墙，我从小对着打。","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","给自己打出去的球加一层回旋。对手碰到球之前再按一次，球会沿着弧线收回你这边。","lesson",null,{"title":"教学·回锅再炒（能量 25，可再按）"}],["nar","收回来以后，你得自己再打一拍。","lesson",null,{"title":"教学·回锅再炒（能量 25，可再按）"}],["nar","（对手最好的办法：主动上前截击，逼你早点决定收不收。）","lesson",null,{"title":"教学·回锅再炒（能量 25，可再按）"}],["nar","拖动扔出一个大肉包，球撞进去会被吸掉力道；等你亲手回一拍以后再按，肉包里的压力会放出来，让球突然加速。","lesson",null,{"title":"教学·超大肉包球（能量 25，可再按）"}],["nar","方向不安全时肉包会先留着，可以接蒸汽地板或者回锅。","lesson",null,{"title":"教学·超大肉包球（能量 25，可再按）"}],["ruibao","肉包为什么能吸力道？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","你说呢。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","……因为我实诚。","talk",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"1-2:1"},{"t":"card","card":"v3_07","uid":"1-2:2"},{"t":"match","as":"ruibao","opp":"dingding","field":"empty","level":"easy","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"1-2:3"},{"t":"dialog","scene":"emptyfield","lines":[["nar","比赛中，瑞宝第一次用地板开球，墙立起来的那一刻，墙上的灰缝里闪过两个字，转眼就没了：别进。只有丁丁看见了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","瑞宝，你墙上写的什么？","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","写的“别进”啊，说球的。球别进我墙里。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","……空场里不该有字。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","那就是你那蒸笼有 bug。快打。","talk",null,{"direction":"","speaker":"瑞宝"}],["ruibao","我在球心里是一面墙。","talk",null,{"direction":"摘下头环","speaker":"瑞宝"}],["dingding","一面挺好看的墙。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","……你这人突然说好话，我害怕。","talk",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"1-2:4"}],"rewards":{"cards":["v3_07"],"chars":["ruibao"],"gear":["sh_light"]},"feather":"ruibao"},{"id":"1-3","title":"七个老粉","scene":"streamroom","date":"6 月 30 日 下午 · 飞鹅网吧二楼，猴子的“直播间”","desc":"★触发三连胜播报 ★毫毛小猴拦截成功 1 次","knowledge":["v3_08"],"kind":"match","steps":[{"t":"cinema","scene":"streamroom","title":"七个老粉","caption":"6 月 30 日 下午 · 飞鹅网吧二楼，猴子的“直播间”","transition":"ink","intro":true,"uid":"1-3:0"},{"t":"dialog","scene":"streamroom","lines":[["nar","网吧二楼的角落，一台电脑、一个补光灯、一张印着“猴哥直播”的海报。屏幕右上角：在线 7 人。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["houzi","家人们！今天给大家整个新活——真·羽毛球，带技能的！","talk",null,{"direction":"","speaker":"猴子"}],["dingding","你能不能小点声，楼下有人打 Dota。","talk",null,{"direction":"","speaker":"丁丁"}],["houzi","楼下就是我。上一把还没结束呢，我挂着。","talk",null,{"direction":"","speaker":"猴子"}],["dingding","……你挂机来直播？","talk",null,{"direction":"","speaker":"丁丁"}],["houzi","问题不大。","talk",null,{"direction":"","speaker":"猴子"}],["nar","弹幕飘过：","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","kkk：来了","stage",null,{}],["nar","鹅湾第一深情：猴哥今天几点下播","stage",null,{}],["nar","老王包子：稳住","stage",null,{}],["houzi","“老王包子”大哥又来了！每次都刷“稳住”，我都不知道他是谁，反正是真爱粉。","talk",null,{"direction":"","speaker":"猴子"}],["ruibao","……打你的球吧。","talk",null,{"direction":"停了一下","speaker":"瑞宝"}]],"when":null,"uid":"1-3:1"},{"t":"dialog","scene":"emptyfield","lines":[["nar","进入空场。猴子脚下浮出一朵圆滚滚的金色云，背后垂下几根绿藤，肩膀上蹲着一只巴掌大的小猴子，冲所有人做鬼脸。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","连续得分从两连胜开始额外获得 +3 / +5 / +8 能量。","lesson",null,{"title":"教学·被动「连杀播报」"}],["nar","但连胜被终结时，对手 +10 能量。","lesson",null,{"title":"教学·被动「连杀播报」"}],["houzi","Double kill！你看，我就是我自己的解说。","talk",null,{"direction":"","speaker":"猴子"}],["nar","驾云直接飞到来球的最高点悬停，这一拍更重，可以空中暴扣。","lesson",null,{"title":"教学·筋斗云（能量 30）"}],["nar","云只停 1.4 秒，要在这段时间里出手。","lesson",null,{"title":"教学·筋斗云（能量 30）"}],["nar","（对手的应对：打低平快球，或者放网。）","lesson",null,{"title":"教学·筋斗云（能量 30）"}],["nar","拖动选方向荡出去，再拖放一次决定从哪个方向松手飞出；空中还能微调，可以接筋斗云或强化回击。","lesson",null,{"title":"教学·荡藤飞跃（能量 25，可再按）"}],["nar","（对手的应对：看你松手的方向，往另一边打。）","lesson",null,{"title":"教学·荡藤飞跃（能量 25，可再按）"}],["nar","召唤小猴守场 7 秒，能替你拦一次球；它准备好以后会来回巡逻，顺手丢一块香蕉皮。","lesson",null,{"title":"教学·毫毛小猴（能量 30）"}],["nar","高球可以从小猴头顶绕过去。","lesson",null,{"title":"教学·毫毛小猴（能量 30）"}]],"when":null,"uid":"1-3:2"},{"t":"card","card":"v3_08","uid":"1-3:3"},{"t":"match","as":"houzi","opp":"ruibao","field":"empty","level":"easy","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"stream":true,"uid":"1-3:4"},{"t":"dialog","scene":"emptyfield","lines":[["houzi","家人们，赢了！谢谢“老王包子”大哥的“稳住”！","talk",null,{"direction":"","speaker":"猴子"}],["nar","弹幕：","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","老王包子：瑞宝也打得好","stage",null,{}],["ruibao","我下楼买瓶水。","think",null,{"direction":"看着屏幕，没说话，起身","speaker":"瑞宝"}],["houzi","咦，这大哥认识瑞宝？","talk",null,{"direction":"","speaker":"猴子"}],["dingding","……瑞宝在镇上谁不认识。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","只有玩家能看到：屏幕的角落，猴子空场记录里有一帧，他头顶闪过一行字，又被他自己的连杀播报盖住了。只停了不到一秒：都别走。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"1-3:5"}],"rewards":{"cards":["v3_08"],"chars":["houzi"],"gear":[]},"feather":"houzi"},{"id":"1-4","title":"采石场","scene":"quarry","date":"7 月 2 日 下午 · 江边废采石场","desc":"★找到 3 块化石 ★和波波聊完所有话题","knowledge":["v3_09"],"kind":"inspect","steps":[{"t":"cinema","scene":"quarry","title":"采石场","caption":"7 月 2 日 下午 · 江边废采石场","transition":"ink","intro":true,"uid":"1-4:0"},{"t":"dialog","scene":"quarry","lines":[["nar","烈日下的灰白石壁，一个戴草帽的男生蹲在碎石里，拿毛刷一点一点扫着什么。旁边插着一块纸牌：“施工中，请勿踩我的寒武纪”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["houzi","波波！出来玩！","talk",null,{"direction":"","speaker":"猴子"}],["bobo","我在玩。","talk",null,{"direction":"头也不回","speaker":"波波"}],["xiaohong","他从六月十号开始就住在这儿了。","talk",null,{"direction":"","speaker":"小红"}],["bobo","六月九号下午。（举起一块石头）你们看。","talk",null,{"direction":"","speaker":"波波"}],["ruibao","……一块石头。","talk",null,{"direction":"","speaker":"瑞宝"}],["bobo","一片蕨叶。三亿年前的。它那天被埋进泥里，泥变成了石头，它就一直记着自己长什么样。","talk",null,{"direction":"","speaker":"波波"}],["dingding","……记着。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"1-4:1"},{"t":"inspect","scene":"quarry","title":"请勿踩我的寒武纪","items":[{"id":"fishfossil","label":"鱼骨","text":"波波：鱼是最早有脊椎的一批。你打球用的脊椎，是从它们那儿借来的。","clue":"fishfossil","x":0.17,"y":0.28},{"id":"shellfossil","label":"贝壳","text":"波波：这里以前是海。鹅湾是一个海底。","clue":"shellfossil","x":0.48,"y":0.28},{"id":"leaffossil","label":"像羽毛的印痕","text":"波波：这个……我希望是羽毛，其实应该是叶子。不过没关系，我天天希望一下。","clue":"leaffossil","x":0.79,"y":0.28}],"uid":"1-4:2"},{"t":"dialog","scene":"quarry","lines":[["nar","化石 1 · 鱼骨：“鱼是最早有脊椎的一批。你打球用的脊椎，是从它们那儿借来的。”","stage",null,{}],["nar","化石 2 · 贝壳：“这里以前是海。鹅湾是一个海底。”","stage",null,{}],["nar","化石 3 · 一片模糊的印痕：“这个……我希望是羽毛，其实应该是叶子。不过没关系，我天天希望一下。”","stage",null,{}],["bobo","你们知道吗，鸟是恐龙的后代。1996 年，辽宁发现了中华龙鸟，第一只被确认长着羽毛的恐龙。可它不会飞。","talk",null,{"direction":"","speaker":"波波"}],["ruibao","长羽毛不会飞，那长着干嘛？","talk",null,{"direction":"","speaker":"瑞宝"}],["bobo","保暖，好看，求偶。羽毛最早不是为了飞的。 飞，是后来的事。","talk",null,{"direction":"","speaker":"波波"}],["dingding","……后来的事。","talk",null,{"direction":"","speaker":"丁丁"}],["bobo","你那个蒸笼，听说能读球？","talk",null,{"direction":"","speaker":"波波"}],["dingding","你怎么知道？","talk",null,{"direction":"","speaker":"丁丁"}],["bobo","猴子直播了。七个人都知道了。","talk",null,{"direction":"","speaker":"波波"}],["houzi","问题不大。","talk",null,{"direction":"","speaker":"猴子"}],["bobo","能读多老的球？","talk",null,{"direction":"","speaker":"波波"}],["dingding","放久了毛片会回弹，记忆就淡了。一两年的球，基本读不清。","talk",null,{"direction":"","speaker":"丁丁"}],["bobo","除非密封。琥珀里的蚊子，一亿年还是蚊子。","think",null,{"direction":"想了想","speaker":"波波"}]],"when":null,"uid":"1-4:3"},{"t":"card","card":"v3_09","uid":"1-4:4"},{"t":"dialog","scene":"quarry","lines":[["nar","回去的路上，波波一个人走在最后，把那块“希望是羽毛”的石头放进口袋，小心地拍了拍。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"1-4:5"}],"rewards":{"cards":["v3_09"],"chars":["bobo"],"gear":[]},"feather":"bobo"},{"id":"1-5","title":"报名","scene":"townsquare","date":"7 月 5 日 · 镇广场，鹅湾杯报名点 → 听球机空场","desc":"★完美击球 5 次 ★不被筋斗云扣杀得分","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"townsquare","title":"报名","caption":"7 月 5 日 · 镇广场，鹅湾杯报名点 → 听球机空场","transition":"ink","intro":true,"uid":"1-5:0"},{"t":"dialog","scene":"townsquare","lines":[["nar","广场上搭起一排蓝色帐篷，横幅：“南岸体育·鹅湾杯·让每一个球都被看见”。工作人员正在发免费的球，每人一筒。帐篷旁边立着一排崭新的蓝色回收桶：“用过的球请投进来，南岸帮你环保处理”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","发财了。","talk",null,{"direction":"抱着三筒免费球","speaker":"瑞宝"}],["xiaohong","免费的东西最贵。这是经济学。","talk",null,{"direction":"","speaker":"小红"}],["ruibao","你吃我家免费的包子吃了三年，怎么没见你说贵。","talk",null,{"direction":"","speaker":"瑞宝"}],["xiaohong","……那个是例外。","talk",null,{"direction":"","speaker":"小红"}],["nar","广场另一头，一个大块头立起一块手写白板：“果然健身·鹅湾杯竞猜”。下面写着“押注单位：包子”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["guoge","来来来！冠军竞猜！一包子起押！小伙子，你押谁？","talk",null,{"direction":"","speaker":"果哥"}],["dingding","……我还没报名。","talk",null,{"direction":"","speaker":"丁丁"}],["guoge","那你押别人。分散投资，懂吗？","talk",null,{"direction":"","speaker":"果哥"}],["nar","丁丁站在报名表前，笔停在半空。表格最上面印着赞助商一行小字：“本次赛事数据由南岸读羽系统提供”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","写啊。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","……我写了，就得一直打下去。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","那就一直打下去。","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","丁丁写下名字。猴子、小红、星星、冉冉也凑过来写。瑞宝最后一个写，写完愣了一下，又把“所在学校”那一栏涂黑了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["houzi","报完名，来热身！我给家人们直播！","talk",null,{"direction":"","speaker":"猴子"}]],"when":null,"uid":"1-5:1"},{"t":"match","as":"dingding","opp":"houzi","field":"empty","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"uid":"1-5:2"},{"t":"dialog","scene":"townsquare","lines":[["nar","大家打完把用过的球随手扔进蓝色回收桶。桶口亮了一下蓝光，很轻，很快。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","……他们连用过的球都要？","talk",null,{"direction":"","speaker":"小红"}],["ruibao","环保嘛。","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","丁丁（看着桶口，没说话）","stage",null,{}]],"when":null,"uid":"1-5:3"}],"rewards":{"cards":[],"chars":[],"gear":["r_tide"]},"feather":null}]},{"id":"ch2","title":"第二章 · 蝴蝶结","date":"7.6—7.10","scene":"nightmarket","blurb":"有些球会擦网。擦网过去的，也算数。","venue":"homecourt","act":"听见","stages":[{"id":"2-1","title":"夜市","scene":"nightmarket","date":"7 月 6 日 夜 · 鹅湾夜市","desc":"★和夜市上所有朋友说上话 ★走到冉冉的摊位前没有转身离开（转身三次会被瑞宝推回来）","knowledge":[],"kind":"inspect","steps":[{"t":"cinema","scene":"nightmarket","title":"夜市","caption":"7 月 6 日 夜 · 鹅湾夜市","transition":"ink","intro":true,"uid":"2-1:0"},{"t":"dialog","scene":"nightmarket","lines":[["nar","江边夜市，串灯，烤鱼的烟。冉冉的小摊铺着一块白布，上面摆满手工蝴蝶结发夹，每个都别着一张手写卡片。星星蹲在摊位旁边帮忙招呼。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","去。","talk",null,{"direction":"推着丁丁往前","speaker":"瑞宝"}],["dingding","我就路过。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","你从夜市这头路过到那头，路过了四趟。","talk",null,{"direction":"","speaker":"瑞宝"}],["houzi","家人们，现在是情感专区——","talk",null,{"direction":"耳机里，开着直播","speaker":"猴子"}],["dingding","关掉！","talk",null,{"direction":"","speaker":"丁丁"}],["nar","丁丁终于站到摊位前。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","丁丁！要买一个吗？给你打折。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","我……不戴蝴蝶结。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","可以送人啊。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","你还记得吗？高一那年我拿拍子去你家穿线，取的时候我在拍柄上系了一个。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","二十二磅，BG65，白色。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","你记的是线。","surprise",null,{"direction":"愣了一下，笑出声","speaker":"冉冉"}],["dingding","那天你扎的是红色的头绳。","thought",null,{"title":"心里话"}],["ranran","那个蝴蝶结后来还在吗？","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……还在。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","在哪？","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","在……一个地方。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"2-1:1"},{"t":"inspect","scene":"nightmarket","title":"走到她的摊位前","items":[{"id":"market-bow","label":"蝴蝶结摊位","text":"冉冉：那个蝴蝶结后来还在吗？丁丁：……还在。","clue":"market-bow","x":0.17,"y":0.28},{"id":"market-corn","label":"长椅上的烤玉米","text":"星星：如果有一个人要去很远的地方……小红已经开始在心里计算了。","clue":"market-corn","x":0.48,"y":0.28},{"id":"market-stream","label":"耳机里的猴子","text":"猴子：家人们，现在是情感专区—— 丁丁：关掉！","clue":"market-stream","x":0.79,"y":0.28}],"uid":"2-1:2"},{"t":"pick","key":"bow","q":"你要买一个蝴蝶结吗？","o":[{"label":"买一个白色蝴蝶结","value":"white","reply":"white","note":"冉冉笑着把它别在拍柄上。","ok":true},{"label":"这次什么都不买","value":"wait","reply":"wait","note":"冉冉：那下次再来。","ok":true}],"exp":"没有标准答案。这句话会留在羽毛册里。","uid":"2-1:3"},{"t":"dialog","scene":"nightmarket","lines":[["ranran","送谁的？","smile"],["dingding","……挂拍子上。","shy"]],"when":{"choice":"bow","value":"white"},"uid":"2-1:4"},{"t":"dialog","scene":"nightmarket","lines":[["ranran","那下次再来。","smile"],["dingding","……嗯。","shy"]],"when":{"choice":"bow","value":"wait"},"uid":"2-1:5"},{"t":"dialog","scene":"nightmarket","lines":[["nar","另一边，星星和小红坐在长椅上分一串烤玉米。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xingxing","小红，我问你，如果有一个人要去很远的地方……","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","多远？","talk",null,{"direction":"","speaker":"小红"}],["xingxing","……算了，你肯定要算。","think",null,{"direction":"","speaker":"星星"}],["xiaohong","我不算。","think",null,{"direction":"","speaker":"小红"}],["xingxing","你已经在算了，你嘴在动。","think",null,{"direction":"","speaker":"星星"}]],"when":null,"uid":"2-1:6"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"2-2","title":"网前","scene":"emptyfield","date":"7 月 7 日 · 听球机空场","desc":"★用蝴蝶结托起擦网球 1 次 ★红丝牵球后甩出得分 1 次","knowledge":["v3_10","v3_11"],"kind":"match","steps":[{"t":"cinema","scene":"emptyfield","title":"网前","caption":"7 月 7 日 · 听球机空场","transition":"ink","intro":true,"uid":"2-2:0"},{"t":"dialog","scene":"emptyfield","lines":[["nar","星星把冉冉拉来看“蒸笼”。冉冉戴上头环，空场的球网上挂满了粉色丝带，网带上停着两只发光的蝴蝶结，像两只要飞走的蝴蝶。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false}],["ranran","哇……我心里是这个样子吗？","talk",null,{"direction":"","speaker":"冉冉"}],["xingxing","你心里好甜。","talk",null,{"direction":"","speaker":"星星"}],["ranran","可能是今天下午吃了三个糖葫芦。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","你打出的网前球过网后，会在网带上留下一个蝴蝶结（最多 2 个）。下一只擦网的球会被蝴蝶结托起来，然后再落下。","lesson",null,{"title":"教学·被动「蝴蝶结」"}]],"when":null,"uid":"2-2:1"},{"t":"card","card":"v3_10","uid":"2-2:2"},{"t":"dialog","scene":"emptyfield","lines":[["ranran","所以擦网过去也算数？","think",null,{"direction":"","speaker":"冉冉"}],["dingding","算数。只要过去了，就算数。","think",null,{"direction":"","speaker":"丁丁"}],["nar","6 秒内，第一只经过网带的球会粘在网上，1 秒后滑向对面。","lesson",null,{"title":"教学·糖球挂网（能量 25）"}],["nar","放技能时往后拖，球就滑回你自己这边。","lesson",null,{"title":"教学·糖球挂网（能量 25）"}],["nar","对手会看到一个箭头，提示球从哪边滑落。","lesson",null,{"title":"教学·糖球挂网（能量 25）"}],["nar","拖动选方向，射出一条红丝带，缠住来球拉到你拍前；再拖动一次选方向和力度，随拍甩出。只点一下就自动甩向空当。","lesson",null,{"title":"教学·红丝牵球（能量 25，可再按）"}],["nar","丝带不能过网。","lesson",null,{"title":"教学·红丝牵球（能量 25，可再按）"}],["nar","接下来 6 秒，网归你：你的贴网球被网弹下去压低，对手的贴网球被弹高。","lesson",null,{"title":"教学·把网借我一下（能量 25）"}],["nar","正挂在糖网上、或者被红丝带缠着的球，会立刻弹射出去。","lesson",null,{"title":"教学·把网借我一下（能量 25）"}]],"when":null,"uid":"2-2:3"},{"t":"card","card":"v3_11","uid":"2-2:4"},{"t":"match","as":"ranran","opp":"dingding","field":"empty","level":"easy","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"2-2:5"},{"t":"dialog","scene":"emptyfield","lines":[["ranran","丁丁，你这个东西好厉害。我能再进去吗？","talk",null,{"direction":"摘下头环，眼睛亮亮的","speaker":"冉冉"}],["dingding","随时。","talk",null,{"direction":"","speaker":"丁丁"}],["dingding","随时。一辈子都行。","thought",null,{"title":"心里话"}],["ranran","对了，你刚才在里面……一直往我这边扑。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","那是在接球。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","哦。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","冉冉低头笑了一下。丁丁没看见，瑞宝看见了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"2-2:6"}],"rewards":{"cards":["v3_10","v3_11"],"chars":["ranran"],"gear":["r_silk"]},"feather":"ranran"},{"id":"2-3","title":"十二点钟方向","scene":"classroom","date":"7 月 8 日 · 镇一中教室 → 听球机空场","desc":"固定落区反射 · 两次校准回球","knowledge":["v3_12"],"kind":"match","steps":[{"t":"cinema","scene":"classroom","title":"十二点钟方向","caption":"7 月 8 日 · 镇一中教室 → 听球机空场","transition":"ink","intro":true,"uid":"2-3:0"},{"t":"dialog","scene":"classroom","lines":[["nar","暑假的空教室。小红在黑板上画满了球场俯视图和三角形。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","首先，球场是一个矩形——","talk",null,{"direction":"","speaker":"小红"}],["houzi","我们知道。","talk",null,{"direction":"","speaker":"猴子"}],["xiaohong","斜线比直线长，所以斜线球给对手的反应时间更多；直线短，但更容易被拦——","talk",null,{"direction":"","speaker":"小红"}],["ruibao","你暑假把我们叫来，是给我们补课？","talk",null,{"direction":"","speaker":"瑞宝"}],["xiaohong","是给你们讲我的技能。（停顿）还有，我需要一点……别的帮助。","talk",null,{"direction":"","speaker":"小红"}],["dingding","什么帮助？","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","8 月 12 日的计划。我需要几个人帮忙。","talk",null,{"direction":"把那本厚笔记本放在讲台上，像放下一块砖","speaker":"小红"}],["dingding","……什么计划？","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","告白。","talk",null,{"direction":"","speaker":"小红"}],["houzi","几页？","talk",null,{"direction":"","speaker":"猴子"}],["xiaohong","目前三十一页。","talk",null,{"direction":"","speaker":"小红"}],["ruibao","……你是打算告白还是答辩？","think",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"2-3:1"},{"t":"card","card":"v3_12","uid":"2-3:2"},{"t":"dialog","scene":"emptyfield","lines":[["nar","空场里，小红周围浮着一圈橙色量角器刻度。他伸手一划，空中出现一块半透明的反射板。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","场上会画出角度参考线。你每次完美的亲手回球，都会获得一次校准：下一块手动反射板能多弹一次。每分最多获得两次。","lesson",null,{"title":"教学·被动「角度标尺」"}],["nar","消耗25能量。拖动放置后0.45秒生效，持续10秒、拦截一次；消耗校准标记时可拦截两次。最多三块按编号接力。","lesson",null,{"title":"教学·几何反射板"}],["nar","每块板朝固定落区出球，落区在放置时标在地面上。可拦截过网后的对方来球、自己的自抛球和板间接力球；己方发球与普通出球直接穿过。","lesson",null,{"title":"教学·几何反射板"}],["nar","把拍前的来球垫起来，自己再扣。拖动选垫球的角度和力度，可以垫向反射板；只点一下就垫到头顶。","lesson",null,{"title":"教学·自抛自扣（能量 25）"}],["nar","注意：第二拍要是失手，就白送对方一分。","lesson",null,{"title":"教学·自抛自扣（能量 25）"}],["nar","消耗20能量，在8秒内辅助两次手动回球：击球时机判定放宽20%，击球质量至少82%。由你选择高远、吊球或扣杀。","lesson",null,{"title":"教学·辅助线"}],["nar","正常球路按原样打出，预计下网或出界时尝试修正到同类安全落区。需要自己走位、够球和挥拍；挥空不消耗次数。","lesson",null,{"title":"教学·辅助线"}]],"when":null,"uid":"2-3:3"},{"t":"match","as":"xiaohong","opp":"ruibao","field":"empty","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"2-3:4"},{"t":"dialog","scene":"emptyfield","lines":[["xiaohong","你看，一切都可以计算。","think",null,{"direction":"","speaker":"小红"}],["dingding","那你算出来她会答应吗？","think",null,{"direction":"","speaker":"丁丁"}],["xiaohong","……这部分在附录。","talk",null,{"direction":"推了推眼镜","speaker":"小红"}],["dingding","附录写了什么？","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","附录还没写。","talk",null,{"direction":"","speaker":"小红"}]],"when":null,"uid":"2-3:5"}],"rewards":{"cards":["v3_12"],"chars":["xiaohong"],"gear":[]},"feather":"xiaohong"},{"id":"2-4","title":"天台","scene":"rooftop","date":"7 月 9 日 夜 · 废弃气象站天台 → 听球机空场","desc":"★月亮转满两圈后甩出得分 ★星门出球后得分","knowledge":["v3_13"],"kind":"match","steps":[{"t":"cinema","scene":"rooftop","title":"天台","caption":"7 月 9 日 夜 · 废弃气象站天台 → 听球机空场","transition":"ink","intro":true,"uid":"2-4:0"},{"t":"dialog","scene":"rooftop","lines":[["nar","天台的铁栏杆生了锈，中间架着一台旧望远镜。星星仰头看着天，冉冉靠在她旁边。远处，鹅湾的灯一盏一盏灭掉。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","你还没跟他说？","talk",null,{"direction":"","speaker":"冉冉"}],["xingxing","说什么？","talk",null,{"direction":"","speaker":"星星"}],["ranran","说你要去的地方。","talk",null,{"direction":"","speaker":"冉冉"}],["xingxing","……两千三百公里。","talk",null,{"direction":"","speaker":"星星"}],["ranran","他会算出来的。","think",null,{"direction":"","speaker":"冉冉"}],["xingxing","所以我才不敢说啊。他算出来以后，就会开始算别的。算我们见一面要多久，算要花多少钱，算……值不值得。（停顿）我怕他算完了，就不说了。","think",null,{"direction":"","speaker":"星星"}],["ranran","你怎么知道他要说？","talk",null,{"direction":"","speaker":"冉冉"}],["xingxing","他那个本子，有一次落在我桌上。我只看了第一页。第一页写着我的名字，后面跟着一个冒号。","smile",null,{"direction":"笑了，眼睛弯成月牙","speaker":"星星"}],["ranran","然后呢？","talk",null,{"direction":"","speaker":"冉冉"}],["xingxing","然后我就合上了。我想听他自己说。","think",null,{"direction":"","speaker":"星星"}]],"when":null,"uid":"2-4:1"},{"t":"card","card":"v3_13","uid":"2-4:2"},{"t":"dialog","scene":"emptyfield","lines":[["nar","空场里，天是深蓝色的，一轮淡金色的月亮挂在星星身边，场地边缘有两道紫色的星门遥遥相对。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","每亲手回球两次，+6 能量，每分最多 18。发球、自抛和装置替你回的球不算。","lesson",null,{"title":"教学·被动「夜空记事」"}],["nar","拖动放置月亮。来球会被月亮抓住、绕着它转圈；再按一次，球沿切线方向甩出去，转的圈越多，甩得越快。","lesson",null,{"title":"教学·月亮抓住了球（能量 30，可再按）"}],["nar","球还在你这边时，你还可以再补一拍。","lesson",null,{"title":"教学·月亮抓住了球（能量 30，可再按）"}],["nar","甩出界、下网、或者落回自己场内，都算你丢分。","lesson",null,{"title":"教学·月亮抓住了球（能量 30，可再按）"}],["nar","拖动选择出口在前场还是后场。下一拍，或者从月亮里甩出来的球，会穿过星门，在出口停 0.35 秒再飞出来。","lesson",null,{"title":"教学·星门对望（能量 30）"}],["nar","开启时花 10 能量，之后每秒再花 6，最长 1.5 秒；关掉以后稳定 1 秒。","lesson",null,{"title":"教学·重力换班（能量 10 开启，可再按）"}],["nar","开着的时候，球会往上飘，月亮的捕获圈也会变大。","lesson",null,{"title":"教学·重力换班（能量 10 开启，可再按）"}]],"when":null,"uid":"2-4:3"},{"t":"match","as":"xingxing","opp":"houzi","field":"empty","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"2-4:4"},{"t":"dialog","scene":"emptyfield","lines":[["houzi","星星，你这个月亮也太犯规了，我的筋斗云都被你抓了。","talk",null,{"direction":"","speaker":"猴子"}],["xingxing","月亮又不是故意的，它就是……喜欢东西绕着它转。","talk",null,{"direction":"","speaker":"星星"}]],"when":null,"uid":"2-4:5"}],"rewards":{"cards":["v3_13"],"chars":["xingxing"],"gear":["sh_butterfly"]},"feather":"xingxing"},{"id":"2-5","title":"黑色的车","scene":"emptyfield","date":"7 月 10 日 · 听球机空场 → 穿线铺门口","desc":"★用两个不同技能各得分 1 次 ★赢下比赛","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"emptyfield","title":"黑色的车","caption":"7 月 10 日 · 听球机空场 → 穿线铺门口","transition":"ink","intro":true,"uid":"2-5:0"},{"t":"dialog","scene":"emptyfield","lines":[["nar","两个女生在空场里打得有来有回，一个人的月亮抓住了另一个人的红丝带。场边的男生们站成一排。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["houzi","我押星星。","talk",null,{"direction":"","speaker":"猴子"}],["ruibao","我押冉冉。","talk",null,{"direction":"","speaker":"瑞宝"}],["xiaohong","我……我不押。","talk",null,{"direction":"","speaker":"小红"}],["dingding","我也不押。","talk",null,{"direction":"","speaker":"丁丁"}],["houzi","你俩是不押，还是不敢押？","talk",null,{"direction":"","speaker":"猴子"}]],"when":null,"uid":"2-5:1"},{"t":"match","as":"choose","opp":"other","field":"empty","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"players":["ranran","xingxing"],"uid":"2-5:2"},{"t":"dialog","scene":"emptyfield","lines":[["nar","打完出来已经是深夜。大家在穿线铺门口分包子，有说有笑。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"2-5:3"},{"t":"dialog","scene":"stringing-night","lines":[["nar","一辆黑色轿车悄无声息地停在路边，车灯没关，照亮了满地鹅毛。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"2-5:4"},{"t":"dialog","scene":"stringing-night","lines":[["nar","车门打开，下来一个穿白衬衫的年轻男人。他抬头看了一眼“丁记穿线铺”的招牌，像在确认什么。然后他看向丁丁。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-return"}],["tianchu","师弟。","talk",null,{"direction":"","speaker":"田楚","cg":"cg-return"}],["nar","所有人都安静了。丁丁手里的包子掉在了地上。一只鹅走过来，叼走了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-return"}],["tianchu","听说你又开始打球了。","smile",null,{"direction":"微笑","speaker":"田楚","cg":"cg-return"}]],"when":null,"uid":"2-5:5"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]},{"id":"ch3","title":"第三章 · 师兄","date":"7.12—7.16","scene":"auditorium","blurb":"二十六磅。白衬衫。观众席第三排。师兄回来了。","venue":"homecourt","act":"被听见","stages":[{"id":"3-1","title":"二十六磅","scene":"stringing","date":"7 月 12 日 上午 · 丁记穿线铺","desc":"★磅数正好二十六 ★田楚不再挑剔（不出现“重来”）","knowledge":[],"kind":"minigame","steps":[{"t":"cinema","scene":"stringing","title":"二十六磅","caption":"7 月 12 日 上午 · 丁记穿线铺","transition":"ink","intro":true,"uid":"3-1:0"},{"t":"dialog","scene":"stringing","lines":[["nar","田楚坐在铺子里唯一一张木椅上，翘着腿，环视墙上的球拍，像在参观一座博物馆。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","还是老样子。刘姨的拍子，还是二十四磅？","talk",null,{"direction":"","speaker":"田楚"}],["dingding","……嗯。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","她扣杀还是那么狠？","talk",null,{"direction":"","speaker":"田楚"}],["dingding","比瑞宝狠。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","帮我穿一支。二十六磅。","smile",null,{"direction":"笑了一下","speaker":"田楚"}]],"when":null,"uid":"3-1:1"},{"t":"minigame","game":"stringing","title":"师兄的二十六磅","tension":26,"pressure":true,"uid":"3-1:2"},{"t":"dialog","scene":"stringing","lines":[["tianchu","竖线第三根，偏了半磅。","talk",null,{"direction":"","speaker":"田楚"}],["tianchu","夹头再往里一点。你小时候也总是夹太外面。","talk",null,{"direction":"","speaker":"田楚"}],["tianchu","……可以。比四年前好多了。","talk",null,{"direction":"","speaker":"田楚"}],["nar","丁丁穿完，把拍子递过去。田楚握了握拍面，听了一下弦音，点头。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","听说你把“听球”修好了。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","……你怎么知道？","talk",null,{"direction":"手一僵","speaker":"丁丁"}],["tianchu","鹅湾的事，我都知道。（站起来）来南岸吧。做工程师。你那口蒸笼，我们出钱给你换成不锈钢的。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","不去。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","不急着回答。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","不去。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","……那鹅湾杯见。","talk",null,{"direction":"停了一下，像是第一次认真看他","speaker":"田楚"}],["nar","田楚走出门。他打开后备箱放拍子，丁丁的视线越过他的肩膀，看见后备箱角落里有一支用旧毛巾包着的拍子，毛巾滑开一角，露出几根卷曲的断线。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","后备箱关上。丁丁站在门口，下意识摸了摸食指上的疤。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","他走了？","talk",null,{"direction":"从对面包子铺探出头","speaker":"瑞宝"}],["dingding","走了。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","他给钱了吗？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","……没有。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","那他就没走。","talk",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"3-1:3"}],"rewards":{"cards":[],"chars":[],"gear":["r_heavy","r_light"]},"feather":null},{"id":"3-2","title":"周六课","scene":"oldgym","date":"7 月 13 日 上午 · 镇一中老体育馆","desc":"★米字步全部踩准 ★用标志桶让对手跳一次","knowledge":["v3_14","v3_15"],"kind":"footwork","steps":[{"t":"cinema","scene":"oldgym","title":"周六课","caption":"7 月 13 日 上午 · 镇一中老体育馆","transition":"ink","intro":true,"uid":"3-2:0"},{"t":"dialog","scene":"oldgym","lines":[["nar","老体育馆的木地板磨得发亮，窗户很高，阳光斜着打进来，浮尘在光里慢慢转。十几个小孩在场上排队，最前面的男孩膝盖上贴满了创可贴，正在原地蹦。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","都站好。今天谁带了保温杯？","talk",null,{"direction":"吹一声哨","speaker":"朱老师"}],["lingfeng","朱老师，我不需要保温杯，我需要扣杀！","talk",null,{"direction":"","speaker":"凌风"}],["zhu","你先需要米字步。（看见门口的丁丁，愣了一下，然后慢慢笑开）……丁丁。","surprise",null,{"direction":"","speaker":"朱老师"}],["dingding","朱老师。","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","四年了。站那儿干嘛，进来。正好给小孩们示范一下步法。","talk",null,{"direction":"","speaker":"朱老师"}],["nar","以场地中心为起点，向前、后、左前、右前、左后、右后六个方向跨步，每踩一个点马上回中心。","lesson",null,{"title":"教学·米字步"}],["nar","地上出现光圈时踩上去；跳起来的光圈要起跳，挥拍的光圈要挥拍。","lesson",null,{"title":"教学·米字步"}]],"when":null,"uid":"3-2:1"},{"t":"footwork","as":"dingding","def":{"name":"朱老师的米字步","need":6,"total":12,"life":3.2,"minLife":2.2},"stars":[],"uid":"3-2:2"},{"t":"card","card":"v3_14","uid":"3-2:3"},{"t":"dialog","scene":"oldgym","lines":[["lingfeng","你就是丁丁？田楚的师弟？他真的回来了吗？我能找他签名吗？","talk",null,{"direction":"凑到丁丁身边","speaker":"凌风"}],["dingding","……你认识他？","talk",null,{"direction":"","speaker":"丁丁"}],["lingfeng","我床头也贴着这个！","talk",null,{"direction":"指着体育馆墙上一张褪色的海报：“鹅湾骄傲·田楚·省青年赛亚军”","speaker":"凌风"}]],"when":null,"uid":"3-2:4"},{"t":"dialog","scene":"emptyfield","lines":[["nar","朱老师进入空场给孩子们做示范，丁丁在场边帮忙操作听球机。朱老师身边浮起淡绿色的节拍器、一排橙色标志桶，胸前挂着一只亮闪闪的哨子。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","哦——我在球心里是这个样子啊。挺好，挺像个老师的。","talk",null,{"direction":"","speaker":"朱老师"}],["nar","对手第一次放某个技能时，屏幕上会出现这个技能的应对提示（例：“三只里只有一只真：等到最后一刻再扑”）。","lesson",null,{"title":"教学·被动「三十年，看得懂」"}],["nar","每分你第一次亲手接好一个技能球以后，下一拍的质量更稳定。","lesson",null,{"title":"教学·被动「三十年，看得懂」"}],["nar","【系统】从这一关开始，所有对手的技能第一次出现时都会给出应对提示。可以在设置里关掉。","lesson",null,{"title":"教学·被动「三十年，看得懂」"}],["zhu","打球的时候，看不懂没关系。看得懂了，就不怕了。","talk",null,{"direction":"","speaker":"朱老师"}],["nar","接下来 10 秒，前两拍有辅助、更稳定（球路还是你自己选），第三拍精确打向空当。","lesson",null,{"title":"教学·一、二、一（能量 25）"}],["nar","在对手身前摆标志桶 4.5 秒（往后拖就摆在身后）。对手在地上跑不过去，只能跳过去。","lesson",null,{"title":"教学·标志桶（能量 25）"}],["nar","把近身的来球停在拍面上 1 秒，这段时间你可以走位观察；然后再按击球键，精准出手。","lesson",null,{"title":"教学·停一下，看站位（能量 25）"}],["nar","停球期间，对手也能看见落点。","lesson",null,{"title":"教学·停一下，看站位（能量 25）"}]],"when":null,"uid":"3-2:5"},{"t":"match","as":"zhu","opp":"lingfeng","field":"empty","level":"easy","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"enableTips":true,"uid":"3-2:6"},{"t":"dialog","scene":"emptyfield","lines":[["nar","凌风一个球擦网，晃晃悠悠掉进朱老师这边，朱老师没接到。一分后，朱老师自己的球擦网落进凌风那边。凌风扑过去没够到。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","对不起。","talk",null,{"direction":"立刻举起左手","speaker":"朱老师"}],["lingfeng","朱老师，擦网也算你的分啊，你道什么歉？","think",null,{"direction":"","speaker":"凌风"}],["zhu","分是算的。歉也是要道的。","think",null,{"direction":"","speaker":"朱老师"}]],"when":null,"uid":"3-2:7"},{"t":"card","card":"v3_15","uid":"3-2:8"},{"t":"dialog","scene":"emptyfield","lines":[["nar","下课后，丁丁帮忙收拾器材，走进朱老师的办公室还球筐。桌上摆着一个保温杯、一摞物理作业，还有一个相框面朝下扣着。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","朱老师，这个……","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","老照片，没什么好看的。（拿起保温杯）枸杞要不要？","talk",null,{"direction":"很自然地把相框收进抽屉","speaker":"朱老师"}],["dingding","……不用了。","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","丁丁。（停顿）你师兄回来了，你知道吧？","talk",null,{"direction":"","speaker":"朱老师"}],["dingding","他让我去南岸。","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","你去吗？","talk",null,{"direction":"","speaker":"朱老师"}],["dingding","不去。","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","他走的时候，也没跟我说再见。（转回来，笑了笑）有些球，得自己捡。","smile",null,{"direction":"点点头，看着窗外","speaker":"朱老师"}]],"when":null,"uid":"3-2:9"}],"rewards":{"cards":["v3_14","v3_15"],"chars":["zhu"],"gear":["sh_stable","s_crisp"]},"feather":"zhu"},{"id":"3-3","title":"说明会","scene":"auditorium","date":"7 月 15 日 晚 · 镇文化礼堂","desc":"★和礼堂里所有人说上话 ★看完大屏演示","knowledge":[],"kind":"inspect","steps":[{"t":"cinema","scene":"auditorium","title":"说明会","caption":"7 月 15 日 晚 · 镇文化礼堂","transition":"ink","intro":true,"uid":"3-3:0"},{"t":"dialog","scene":"auditorium","lines":[["nar","礼堂里坐满了人。舞台上竖着一块巨大的屏幕，旁边是一排银白色的蛋形舱，舱门上印着蓝色的“南岸”二字。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","屏幕亮起，播放一段宣传片。画面里，一个头发花白、穿深色夹克的男人背对镜头站在空球场中央，没有露脸，只有画外音，声音低沉，句子很短。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","三十年前，我输了一个球。（停顿）一个没人看见的球。","talk",null,{"direction":"画外音","speaker":"老南"}],["nan","从那天起，我只做一件事。","talk",null,{"direction":"画外音","speaker":"老南"}],["nan","让每一个球，都被看见。","talk",null,{"direction":"画外音","speaker":"老南"}],["nar","宣传片结束。田楚走上台，白衬衫，没有讲稿。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","大家好，我是南岸青训的田楚。很多叔叔阿姨可能还记得我，我是鹅湾人。","talk",null,{"direction":"","speaker":"田楚"}],["nar","台下有人鼓掌，凌风拍得最响。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","今年夏天，鹅湾杯会在南岸羽场舱里进行。你们在羽场里看到的技能，都是你们心里真实的样子。南岸会为每一位选手建立档案，在每一场比赛前给出胜率预测。","talk",null,{"direction":"","speaker":"田楚"}],["nar","南岸联赛的每场比赛前，大屏都会显示双方的预测胜率。","lesson",null,{"title":"教学·胜率大屏"}],["nar","胜率低的一方赢了，屏幕上会出现“预测被打破”，并额外获得一颗星。","lesson",null,{"title":"教学·胜率大屏"}]],"when":null,"uid":"3-3:1"},{"t":"inspect","scene":"auditorium","title":"让每一个球被看见","items":[{"id":"auditorium-pods","label":"南岸羽场舱","text":"选手进入共享羽场，想法会化成技能。这里与现实球场不同。","clue":"auditorium-pods","x":0.17,"y":0.28},{"id":"auditorium-model","label":"胜率演示","text":"路先森：模型准确率 94.7%。丁丁：剩下那 5.3% 呢？路先森：那是噪音。","clue":"auditorium-model","x":0.48,"y":0.28},{"id":"auditorium-letter","label":"招生宣传册","text":"冉冉停在“青训学院招生”这一页。选择要由她自己说。","clue":"auditorium-letter","x":0.79,"y":0.28}],"uid":"3-3:2"},{"t":"dialog","scene":"auditorium","lines":[["guoge","“南岸！我投了！这公司要赢的！”","talk",null,{"direction":"坐在第一排，举着手机拍照","speaker":"果哥"}],["nar","南岸展位：两个大学生模样的实习生在发传单。胖的那个戴着眼镜，格子衫：","stage",null,{}],["lu","“同学你好，了解一下南岸读羽系统吗？我们的胜率模型准确率 94.7%。”","talk",null,{"direction":"","speaker":"路先森"}],["dingding","“剩下那 5.3% 呢？”","talk",null,{"direction":"","speaker":"丁丁"}],["lu","“那是噪音。”（停顿）“……就像我讲的笑话，大部分人听不懂。”","smile",null,{"direction":"","speaker":"路先森"}],["nar","瘦的那个推了推他：老陈：“别讲了，人家都走了。”","stage",null,{}],["nar","冉冉和星星：冉冉手里多了一张南岸的宣传册，翻到“青训学院招生”那一页。","stage",null,{}],["lingfeng","“田楚哥！能给我签个名吗！”","talk",null,{"direction":"散场后冲到后台","speaker":"凌风"}],["tianchu","“你扑救很漂亮。来南岸试训吧，下周三。”","talk",null,{"direction":"蹲下来，在他的球拍套上签名","speaker":"田楚"}],["lingfeng","“……真的？！”","surprise",null,{"direction":"像被雷劈中一样定在原地","speaker":"凌风"}],["nar","散场时，丁丁回头看了一眼那排蛋形舱。舱门上的蓝光一明一灭，像在呼吸。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"3-3:3"}],"rewards":{"cards":[],"chars":[],"gear":["s_ctrl"]},"feather":null},{"id":"3-4","title":"镜花水月","scene":"league","date":"7 月 16 日 · 镇体育中心，南岸羽场舱（鹅湾杯表演赛）","desc":"得 3 分即可推进剧情。★得 5 分 ★识破每一种骗术各一次（不被镜像假球、假拍、水中月、残影各骗到一次）","knowledge":["v3_16"],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"镜花水月","caption":"7 月 16 日 · 镇体育中心，南岸羽场舱（鹅湾杯表演赛）","transition":"ink","intro":true,"uid":"3-4:0"},{"t":"dialog","scene":"league","lines":[["nar","这是丁丁第一次躺进南岸的羽场舱。舱盖合上，一片黑暗，然后是比蒸笼清晰十倍的球场：雪白的地板，看不见边际的观众席，头顶一块巨大的蓝色胜率屏。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","对面站着田楚。他身后有一个和他一模一样的影子，颜色很淡，像水面上的倒影。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","表演赛，别紧张。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","我没紧张。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","你的拍子在抖。","talk",null,{"direction":"","speaker":"田楚"}],["nar","观众席第三排：冉冉、星星、瑞宝、猴子、小红、波波。朱老师坐在最后一排，保温杯放在膝盖上。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","丁丁，别看他的拍子。看球。","talk",null,{"direction":"声音通过场边通讯传进来，很轻","speaker":"朱老师"}],["nar","田楚急停或转身时，身后会留下一个继续往前跑的残影。不要追着残影判断他的站位。","lesson",null,{"title":"教学·被动「影子慢半拍」（对手）"}],["nar","田楚击球后，球会一分为三，三只一模一样，拖尾和落点圈都一样。只有一只是真的，假的两只落地前会碎成水花。","lesson",null,{"title":"教学·镜花水月（对手）"}],["nar","应对：等到最后一刻再扑。","lesson",null,{"title":"教学·镜花水月（对手）"}],["nar","田楚会虚挥一拍：一只假球飞向你，真球其实垫在他身前，他还要再挥一拍才打过来。","lesson",null,{"title":"教学·这一拍，没打（对手）"}],["nar","应对：第一只是假的，盯住他拍前那只。","lesson",null,{"title":"教学·这一拍，没打（对手）"}],["nar","球过网后泛起水纹，田楚再按一次，球会突然变轨：要么收到网前，要么送到后场。原来的落点会留下一个虚影。","lesson",null,{"title":"教学·水中月（对手）"}],["nar","应对：看到水纹先别动，等它拐弯。","lesson",null,{"title":"教学·水中月（对手）"}]],"when":null,"uid":"3-4:1"},{"t":"match","as":"dingding","opp":"tianchu","field":"league","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"prediction":4,"progressScore":3,"uid":"3-4:2"},{"t":"dialog","scene":"league","lines":[["tianchu","三只球，你扑了最近的那只。","talk",null,{"direction":"第一次镜花水月后","speaker":"田楚"}],["tianchu","人总是先相信离自己最近的东西。","talk",null,{"direction":"","speaker":"田楚"}],["tianchu","你看到的，是你想看的。","think",null,{"direction":"","speaker":"田楚"}],["tianchu","你想它是真的，所以它就是真的。","think",null,{"direction":"","speaker":"田楚"}],["tianchu","……这一只是真的。你不信了，对吧。","talk",null,{"direction":"","speaker":"田楚"}]],"when":null,"uid":"3-4:3"},{"t":"card","card":"v3_16","uid":"3-4:4"},{"t":"dialog","scene":"league","lines":[["nar","得到 3 分以后，剧情推进。","stage",null,{}]],"when":null,"uid":"3-4:5"},{"t":"dialog","scene":"league","lines":[["nar","胜率屏闪了一下：“预测被打破”。全场安静了两秒。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","……运气。","smile",null,{"direction":"看着屏幕，很久，没有笑","speaker":"田楚"}],["dingding","你以前说，羽毛球没有运气。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","我以前说的话很多。","talk",null,{"direction":"","speaker":"田楚"}]],"when":{"outcome":true},"uid":"3-4:6"},{"t":"dialog","scene":"league","lines":[["tianchu","七比三。比我预测的多了两分。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","……你预测了？","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","南岸预测了。（停顿）我只是看。","talk",null,{"direction":"","speaker":"田楚"}]],"when":{"outcome":false},"uid":"3-4:7"}],"rewards":{"cards":["v3_16"],"chars":[],"gear":[]},"feather":null},{"id":"3-5","title":"第三排","scene":"locker","date":"7 月 16 日 · 体育中心更衣室","desc":"二十六磅。白衬衫。观众席第三排。师兄回来了。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"locker","title":"第三排","caption":"7 月 16 日 · 体育中心更衣室","transition":"ink","intro":true,"uid":"3-5:0"},{"t":"dialog","scene":"locker","lines":[["nar","空荡荡的更衣室，日光灯嗡嗡响。丁丁坐在长椅上缠手胶，缠了又拆，拆了又缠。田楚走进来，在他对面的柜子前换鞋。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","你打得比我想的好。","think",null,{"direction":"","speaker":"田楚"}],["dingding","……谢谢。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","但你每一拍，都往观众席第三排看。","talk",null,{"direction":"","speaker":"田楚"}],["nar","丁丁的手停住了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","左边数第四个座位。扎红头绳的那个。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","……你读了我的球。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","报名那天，你们热身打的那筒球。（系好鞋带，站起来）免费的球，你不也用了？","talk",null,{"direction":"","speaker":"田楚"}],["dingding","那是……","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","那是什么？“只有我能读，别人不能读”？（走到门口，回头）师弟。你造的东西，不是只有你一个人会用。","talk",null,{"direction":"","speaker":"田楚"}],["nar","门关上。日光灯闪了一下。丁丁低头，发现手胶缠歪了，缠出一个蝴蝶结的形状。他把它扯掉了。","stage","door",{"silent":false,"cue":"door","white":false,"black":false}]],"when":null,"uid":"3-5:1"}],"rewards":{"cards":[],"chars":[],"gear":["sh_cruise"]},"feather":null}]},{"id":"ch4","title":"第四章 · 渡口","date":"7.18—7.26","scene":"ferry","blurb":"有些话，过了那个渡口，就不用说了。","venue":"homecourt","act":"被听见","stages":[{"id":"4-1","title":"渡船","scene":"ferry","date":"7 月 18 日 傍晚 · 鹅湾渡口 → 江心洲","desc":"★在渡船上和沧澜说完所有话题 ★在江心洲找到那块旧球场","knowledge":[],"kind":"inspect","steps":[{"t":"cinema","scene":"ferry","title":"渡船","caption":"7 月 18 日 傍晚 · 鹅湾渡口 → 江心洲","transition":"feather","intro":true,"uid":"4-1:0"},{"t":"dialog","scene":"ferry","lines":[["nar","夕阳把江水染成橘红色。一条木头渡船慢慢靠岸，撑船的是个扎马尾的年轻女人，手臂晒得黝黑，船头挂着一只装满羽毛球的网兜。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["canglan","上船。一块钱。……哎，你是小穿线的？","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","……沧澜姐。","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","长这么高了。（收了钱，撑船离岸）你去洲上干嘛？","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","我想问问我师兄的事。","think",null,{"direction":"","speaker":"丁丁"}],["canglan","……他回来了，我知道。他的车在码头停了一个礼拜了。没过江。","talk",null,{"direction":"撑篙的手停了一拍，又继续","speaker":"沧澜"}],["nar","船到江心，四下只有水声。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["canglan","我们俩在省青年队打了四年混双。我在前面，他在后面。他说我网前封得好，他后场就敢放开杀。","talk",null,{"direction":"","speaker":"沧澜"}],["canglan","他走的那天，没跟我说再见。（停顿）我也没问他为什么。","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","为什么不问？","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","怕他说出来的，比不说更难听。（笑了一下）后来我就想，算了，等他想说的时候吧。结果他就再没回来过。","smile",null,{"direction":"","speaker":"沧澜"}],["canglan","我们俩谁都没说。后来，就不用说了。","talk",null,{"direction":"","speaker":"沧澜"}],["nar","沧澜转头看着丁丁。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["canglan","小穿线的，你是不是也有一句话，一直没说？","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","……没有。","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","嗯。我当年也说没有。","talk",null,{"direction":"","speaker":"沧澜"}]],"when":null,"uid":"4-1:1"},{"t":"inspect","scene":"ferry","title":"一块钱，过江","items":[{"id":"ferry-car","label":"岸边的黑车","text":"车在码头停了一星期，田楚一直没有过江。","clue":"ferry-car","x":0.17,"y":0.28},{"id":"ferry-net","label":"船头的网兜","text":"沧澜接过了家里的渡船，也给洲上的小孩教球。","clue":"ferry-net","x":0.48,"y":0.28},{"id":"ferry-court","label":"江心洲旧球场","text":"围栏上的字已经褪色：江心洲青少年训练点。","clue":"ferry-court","x":0.79,"y":0.28}],"uid":"4-1:2"},{"t":"dialog","scene":"ferry","lines":[["nar","江心洲上有一块水泥球场，球网早就破了，围栏上挂着一块褪色的牌子：“江心洲青少年训练点”。沧澜从船舱里拿出一个铁盒子，里面整整齐齐放着几只用密封袋装好的旧球。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["canglan","听说你那个蒸笼能读球。","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","……能。","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","这只是我们最后一次在洲上加练。他那天一句话都没说，打完就走了。我想知道……他那天在想什么。","think",null,{"direction":"挑出一只，袋子上写着“2021.10.3 洲上 加练”","speaker":"沧澜"}],["dingding","你确定吗？","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","我确定。这是我的球，我让你读的。","talk",null,{"direction":"","speaker":"沧澜"}]],"when":null,"uid":"4-1:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"4-2","title":"潮水","scene":"island-memory","date":"7 月 18 日 夜 · 读球：2021 年 10 月 3 日，江心洲","desc":"★用潮来托起球 1 次 ★用回潮放下浪涌球得分 1 次","knowledge":["v3_17"],"kind":"match","steps":[{"t":"cinema","scene":"island-memory","title":"潮水","caption":"7 月 18 日 夜 · 读球：2021 年 10 月 3 日，江心洲","transition":"feather","intro":true,"uid":"4-2:0"},{"t":"dialog","scene":"island-memory","lines":[["nar","羽场里，江心洲的旧球场是新的，球网完整，围栏上的牌子红得发亮。对面，十七岁的田楚穿着省青年队的旧队服，头发比现在长，正在原地压腿。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"4-2:1"},{"t":"dialog","scene":"island-memory","lines":[["nar","他身后没有影子。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-no-shadow"}],["ruibao","这……是田楚？","talk",null,{"direction":"天上的声音","speaker":"瑞宝","cg":"cg-no-shadow"}],["dingding","那时候他还没有影子。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-no-shadow"}],["nar","沧澜站在场地这边，脚下慢慢漫开一层浅浅的蓝色积水，身后的地上落着三颗发光的水滴。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-no-shadow"}],["nar","你每回一次球，身后就留下一颗水滴（最多 3 颗）。跑回去踩到水滴，吸收 +12 体力。","lesson",null,{"title":"教学·被动「滴水回澜」","cg":"cg-no-shadow"}],["nar","你的半场积水 8 秒，最多托两次球：来球第一次落进水里会弹起来；同一只球第二次落水，照常算你失分。","lesson",null,{"title":"教学·潮来（能量 30）","cg":"cg-no-shadow"}],["nar","（对手看到的提示：第一次落水的球会弹起来，别以为打死了。）","lesson",null,{"title":"教学·潮来（能量 30）","cg":"cg-no-shadow"}],["nar","你的体力比对手低时，把差值的 40%（最多 25 点）从对手那边转过来；体力不比对手低时，接下来 5 秒扣杀更省力。","lesson",null,{"title":"教学·同饮一潮（能量 20）","cg":"cg-no-shadow"}],["nar","来球会沿着原路倒流回对面；再按一次，球就地松手往下坠。","lesson",null,{"title":"教学·回潮（能量 35，可再按）","cg":"cg-no-shadow"}],["nar","从积水里弹起来的球倒流得更快，放下时会变成更重的浪涌球。","lesson",null,{"title":"教学·回潮（能量 35，可再按）","cg":"cg-no-shadow"}],["nar","注意：球还没过网就松手，会落在你自己场内。","lesson",null,{"title":"教学·回潮（能量 35，可再按）","cg":"cg-no-shadow"}]],"when":null,"uid":"4-2:2"},{"t":"match","as":"canglan","opp":"tianchu","field":"memory","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"oppSkills":false,"age":[19,17],"intents":["她今天累了","让她多跑两步回来喝水","……明天的事，明天再说","要是能一直在洲上打就好了"],"intentSide":1,"venue":"islandcourt","uid":"4-2:3"},{"t":"dialog","scene":"island-memory","lines":[["nar","她今天累了","intent",null,{"title":"球记得的念头","cg":"cg-no-shadow"}],["nar","让她多跑两步回来喝水","intent",null,{"title":"球记得的念头","cg":"cg-no-shadow"}],["nar","……明天的事，明天再说","intent",null,{"title":"球记得的念头","cg":"cg-no-shadow"}],["nar","最后一拍。田楚打了一个又高又远、特别好接的球，像故意送给她的。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-no-shadow"}],["nar","要是能一直在洲上打就好了","intent",null,{"title":"球记得的念头","cg":"cg-no-shadow"}],["nar","记忆显影完成，场景定格。沧澜站在羽场里很久，没有摘头环。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-no-shadow"}],["canglan","……第二天，省队通知他去集训。他早就知道了。","talk",null,{"direction":"声音很轻","speaker":"沧澜","cg":"cg-no-shadow"}],["canglan","他打那个球的时候，就知道了。","talk",null,{"direction":"","speaker":"沧澜","cg":"cg-no-shadow"}]],"when":null,"uid":"4-2:4"},{"t":"card","card":"v3_17","uid":"4-2:5"}],"rewards":{"cards":["v3_17"],"chars":["canglan"],"gear":["r_prism"]},"feather":"canglan"},{"id":"4-3","title":"低价值","scene":"ferry","date":"7 月 23 日 · 渡口 → 听球机空场","desc":"★踩到脚印回能量 1 次 ★鱼跃救起球后得分 1 次","knowledge":["v3_18"],"kind":"match","steps":[{"t":"cinema","scene":"ferry","title":"低价值","caption":"7 月 23 日 · 渡口 → 听球机空场","transition":"feather","intro":true,"uid":"4-3:0"},{"t":"dialog","scene":"ferry","lines":[["nar","渡口的台阶上，凌风抱着膝盖坐着，球拍包扔在一边，拍套上田楚的签名被他用指甲刮花了一半。沧澜站在旁边，朝刚下船的丁丁招手。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["canglan","试训回来就坐在这儿，坐了一下午。","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","……怎么了？","talk",null,{"direction":"","speaker":"丁丁"}],["nar","【南岸青训·意图画像】凌风，15 岁。评估：无效扑救次数过多，球路选择情绪化。综合价值：低。建议：不予录取。","stage",null,{}],["lingfeng","他说我扑救漂亮的。他自己说的。","talk",null,{"direction":"","speaker":"凌风"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["lingfeng","我是不是根本就不该扑？是不是那些球本来就接不到，我扑过去就是浪费？","talk",null,{"direction":"","speaker":"凌风"}],["nar","丁丁看着他，像在看一面镜子。镜子里是十四岁的自己，站在一个输掉的球场边上。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","走，跟我去个地方。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"4-3:1"},{"t":"dialog","scene":"emptyfield","lines":[["nar","空场里，凌风脚下拖着一串发光的脚印，身边刮着细细的风。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lingfeng","……这是什么？","talk",null,{"direction":"","speaker":"凌风"}],["dingding","你扑空的地方。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","你没够到球丢了分，扑空的地方会留下一个脚印；下一分踩到它，+15 能量。","lesson",null,{"title":"教学·被动「差一点，也算一步」"}],["nar","亲手做出极限救球时，每分第一次额外 +5。","lesson",null,{"title":"教学·被动「差一点，也算一步」"}],["dingding","扑空了也没白扑。它会留在那儿，等你下次踩上去。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","按住移动方向再按技能，朝那边贴地飞扑救球，卷起一阵旋风。救起来的球过网后会急坠，接下来全场顺风 4 秒。","lesson",null,{"title":"教学·鱼跃追球（能量 25）"}],["nar","扑空的话，你会趴在地上起不来一会儿。","lesson",null,{"title":"教学·鱼跃追球（能量 25）"}],["nar","在空中再跳一次：按住移动方向就斜着横移，不按就直着冲得更高。之后的这一拍带着疾风，更快，接球的人会被击退。","lesson",null,{"title":"教学·空中踏风（能量 20）"}],["nar","拖动布置一条局部风道 6 秒。你从风道里经过时，起步和移动更快；风道只会改变一只球的方向，吹完球以后仍然可以借它助跑。","lesson",null,{"title":"教学·风口急转（能量 20）"}]],"when":null,"uid":"4-3:2"},{"t":"card","card":"v3_18","uid":"4-3:3"},{"t":"match","as":"lingfeng","opp":"dingding","field":"empty","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"4-3:4"},{"t":"dialog","scene":"emptyfield","lines":[["lingfeng","……丁丁哥，你以前也扑吗？","talk",null,{"direction":"躺在地上喘气，满场都是他的脚印","speaker":"凌风"}],["dingding","扑。比你还难看。","talk",null,{"direction":"","speaker":"丁丁"}],["lingfeng","那你后来为什么不打了？","talk",null,{"direction":"","speaker":"凌风"}],["dingding","……因为我以为，有些球接不住，是我的错。","talk",null,{"direction":"沉默了很久","speaker":"丁丁"}],["lingfeng","那是吗？","talk",null,{"direction":"","speaker":"凌风"}],["dingding","我不知道。（站起来，伸手把他拉起来）周六课你还去吗？","talk",null,{"direction":"","speaker":"丁丁"}],["lingfeng","去！","talk",null,{"direction":"","speaker":"凌风"}],["dingding","那我也去。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"4-3:5"}],"rewards":{"cards":["v3_18"],"chars":["lingfeng"],"gear":["sh_moon"]},"feather":"lingfeng"},{"id":"4-4","title":"两只不读的球","scene":"ferry","date":"7 月 24 日 夜 · 渡口 → 穿线铺后屋","desc":"有些话，过了那个渡口，就不用说了。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"ferry","title":"两只不读的球","caption":"7 月 24 日 夜 · 渡口 → 穿线铺后屋","transition":"feather","intro":true,"uid":"4-4:0"},{"t":"dialog","scene":"ferry","lines":[["nar","凌风回家了。沧澜和丁丁坐在船头，脚垂在水面上。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["canglan","小穿线的。","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","嗯。","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","那天，球场没人收拾。我把它捡回来了。四年了，我一直没敢看。","talk",null,{"direction":"从怀里掏出一个密封袋，里面是一只旧球，袋子上的字已经有点褪色：“2022.12.18 省青年赛决赛 最后一球”","speaker":"沧澜"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","那天的拍子，是你穿的吧？","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","……是我穿的。但他说，他早上自己又调过。","sad",null,{"direction":"声音发紧","speaker":"丁丁"}],["canglan","嗯，他是这么说的。（把袋子放到丁丁手里）你是穿拍子的人，你比我更有资格先看。","talk",null,{"direction":"","speaker":"沧澜"}],["dingding","我……","talk",null,{"direction":"","speaker":"丁丁"}],["canglan","不用现在看。等你想知道的时候再看。（站起来，拿起长篙）我等了四年，不差你这几天。","think",null,{"direction":"","speaker":"沧澜"}]],"when":null,"uid":"4-4:1"},{"t":"dialog","scene":"backroom","lines":[["nar","穿线铺后屋。丁丁拉开抽屉。里面躺着一只贴着“冉冉 6.26 不读”的球。他把沧澜的那只放在旁边。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"4-4:2"},{"t":"dialog","scene":"backroom","lines":[["nar","两只球并排躺着。一只是他不能读的，一只是他不敢读的。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-drawer"}],["nar","丁丁关上抽屉，关了灯，在黑暗里坐了很久。","stage",null,{"silent":true,"cue":null,"white":false,"black":false,"cg":"cg-drawer"}]],"when":null,"uid":"4-4:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"4-5","title":"百分之九","scene":"league","date":"7 月 26 日 · 体育中心，南岸羽场舱（鹅湾杯资格赛）","desc":"★赢下比赛（打破预测）★靠脚印回能量 3 次","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"百分之九","caption":"7 月 26 日 · 体育中心，南岸羽场舱（鹅湾杯资格赛）","transition":"feather","intro":true,"uid":"4-5:0"},{"t":"dialog","scene":"league","lines":[["nar","凌风站在羽场里，膝盖上的创可贴贴得整整齐齐。对面是南岸的正式学员，穿着蓝白队服，表情平静得像在做题。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lingfeng","百分之九。","talk",null,{"direction":"小声","speaker":"凌风"}],["dingding","百分之九，也是九。","talk",null,{"direction":"场边通讯","speaker":"丁丁"}],["lingfeng","……这句话好土。","talk",null,{"direction":"","speaker":"凌风"}],["dingding","朱老师说的。","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","我没说过。","talk",null,{"direction":"通讯里","speaker":"朱老师"}],["dingding","现在您说过了。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"4-5:1"},{"t":"match","as":"lingfeng","opp":"academy","field":"league","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"prediction":9,"uid":"4-5:2"},{"t":"dialog","scene":"league","lines":[["nar","大屏：预测被打破。场边，南岸控制台后面，胖胖的实习生看着屏幕，嘴里念叨着“不可能，样本量不对”，嘴角却翘了起来。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lingfeng","我赢了！我扑的那些都不是白扑的！","cheer",null,{"direction":"在羽场里跳起来","speaker":"凌风"}],["dingding","嗯。都不是白扑的。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":{"outcome":true},"uid":"4-5:3"},{"t":"dialog","scene":"league","lines":[["lingfeng","……差一点。","talk",null,{"direction":"","speaker":"凌风"}],["dingding","差一点，也算一步。","think",null,{"direction":"","speaker":"丁丁"}],["lingfeng","（擦了擦眼睛）这句话就不土。","talk",null,{"direction":"","speaker":"凌风"}]],"when":{"outcome":false},"uid":"4-5:4"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]},{"id":"ch5","title":"第五章 · 蓝色回收桶","date":"7.28","scene":"warehouse","blurb":"免费的球，原来记得所有人的名字。","venue":"homecourt","act":"被听见","stages":[{"id":"5-1","title":"回收车","scene":"warehouse","date":"7 月 28 日 深夜 · 镇上街道 → 城郊仓库","desc":"★不被手电筒照到 ★找到仓库的后门","knowledge":[],"kind":"minigame","steps":[{"t":"cinema","scene":"warehouse","title":"回收车","caption":"7 月 28 日 深夜 · 镇上街道 → 城郊仓库","transition":"feather","intro":true,"uid":"5-1:0"},{"t":"dialog","scene":"warehouse","lines":[["nar","凌晨一点。一辆蓝色货车沿着镇上的街道一个一个收回收桶。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","我统计了。镇上一共四十二个回收桶，这辆车每晚收一次，从来不去垃圾站，直接开出镇子。","talk",null,{"direction":"","speaker":"小红"}],["ruibao","你大半夜不睡觉统计这个？","talk",null,{"direction":"","speaker":"瑞宝"}],["xiaohong","失眠。","talk",null,{"direction":"","speaker":"小红"}],["xingxing","为什么失眠？","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","……数学原因。","talk",null,{"direction":"","speaker":"小红"}],["houzi","家人们，今天带大家整个刺激的——","talk",null,{"direction":"举着手机","speaker":"猴子"}],["nar","全员：关掉！","stage",null,{}],["houzi","好好好。（关了）（又偷偷开了）","talk",null,{"direction":"","speaker":"猴子"}]],"when":null,"uid":"5-1:1"},{"t":"minigame","game":"stealth","title":"跟着蓝色回收车","goal":4,"uid":"5-1:2"},{"t":"dialog","scene":"warehouse","lines":[["nar","货车开进城郊一个仓库。仓库里一排排货架，架子上放着成千上万个透明密封袋，每个袋子里装着一只旧球，贴着标签。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["bobo","“王瑞 #0311。”","talk",null,{"direction":"拿起一个，借着月光看标签","speaker":"波波"}],["ruibao","……我？","talk",null,{"direction":"","speaker":"瑞宝"}],["ranran","“冉冉 #0207。”","talk",null,{"direction":"另一个","speaker":"冉冉"}],["lingfeng","“凌风 #0412”……还盖了个章，“低价值”。","talk",null,{"direction":"","speaker":"凌风"}],["nar","货架尽头，两个人正在灯下分拣球。一个胖，一个瘦。胖的那个一边贴标签一边自言自语讲笑话，瘦的那个一边填表一边说“不好笑”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lu","一只羽毛球走进酒吧——","talk",null,{"direction":"","speaker":"路先森"}],["laochen","不好笑。","smile",null,{"direction":"","speaker":"老陈"}],["lu","我还没讲完。","talk",null,{"direction":"","speaker":"路先森"}],["laochen","我知道结局，它被打了。","talk",null,{"direction":"","speaker":"老陈"}],["nar","猴子的手机突然弹出一条弹幕提示音：“叮！老王包子：稳住”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","两个实习生同时抬起头。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"5-1:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"5-2","title":"用球说话","scene":"warehouse","date":"7 月 28 日 深夜 · 仓库里的南岸测试舱","desc":"★打中真球而不是脏数据球 3 次 ★在复制体存在期间得分 1 次","knowledge":["v3_19"],"kind":"match","steps":[{"t":"cinema","scene":"warehouse","title":"用球说话","caption":"7 月 28 日 深夜 · 仓库里的南岸测试舱","transition":"feather","intro":true,"uid":"5-2:0"},{"t":"dialog","scene":"warehouse","lines":[["lu","你们……这是闯进来了？","talk",null,{"direction":"","speaker":"路先森"}],["dingding","你们在读全镇人的球。","talk",null,{"direction":"","speaker":"丁丁"}],["lu","严格来说，是在“环保处理”。","talk",null,{"direction":"","speaker":"路先森"}],["laochen","……这句话连我都不信。","talk",null,{"direction":"","speaker":"老陈"}],["lu","这样，按你们打球的人的规矩，用球说话。你赢了，我回答你三个问题。","talk",null,{"direction":"推了推眼镜","speaker":"路先森"}],["ruibao","我们输了呢？","talk",null,{"direction":"","speaker":"瑞宝"}],["lu","你们输了，我也回答三个问题。我就是想打一局。（停顿）这仓库里一个能陪我打球的都没有。","think",null,{"direction":"","speaker":"路先森"}],["laochen","我呢？","talk",null,{"direction":"","speaker":"老陈"}],["lu","你只会记分。","talk",null,{"direction":"","speaker":"路先森"}]],"when":null,"uid":"5-2:1"},{"t":"dialog","scene":"emptyfield","lines":[["nar","测试舱里，路先森身边浮着一个和他一模一样、半透明的复制体，复制体头顶写着“Ctrl+C”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","路先森每次挥空，都会记下原因；成功处理两类来球或纠正一条日志后，获得编译标记，下一拍更强。每分最多两次。","lesson",null,{"title":"教学·被动「错误日志」（对手）"}],["nar","他会在原地留下一个复制体，存在 8 秒，同步他的起跳、挥拍和技能。复制体打出去的球如果落在他自己这边，可以弹起一次。复制体不会走动。","lesson",null,{"title":"教学·复制体（对手）"}],["nar","应对：把球打到本体和复制体都够不着的空当。","lesson",null,{"title":"教学·复制体（对手）"}],["nar","球到本体或复制体身边时，会被垫给另一个：往上拖是高传，平着拖是快传；然后他再按一次出手。没有复制体时他会自己垫一下。","lesson",null,{"title":"教学·接力协议（对手）"}],["nar","应对：盯住接力的落点，准备接扣杀。","lesson",null,{"title":"教学·接力协议（对手）"}],["nar","他会发出一只看起来和真球一模一样的脏数据球。它可以被击打（会白白浪费你一次挥拍），落地后会乱弹回另一边，被打或弹回 5 次后消失。复制体也会发一只。","lesson",null,{"title":"教学·脏数据（对手）"}],["nar","应对：场上真球只有一只。它落地会乱弹，真球不会。","lesson",null,{"title":"教学·脏数据（对手）"}]],"when":null,"uid":"5-2:2"},{"t":"card","card":"v3_19","uid":"5-2:3"},{"t":"match","as":"dingding","opp":"lu","field":"empty","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"5-2:4"},{"t":"dialog","scene":"emptyfield","lines":[["lu","好。三个问题。","talk",null,{"direction":"瘫在舱里","speaker":"路先森"}],["dingding","第一，这些球拿去干什么？","talk",null,{"direction":"","speaker":"丁丁"}],["lu","读。建档案。每个人一份“意图画像”，用来做胜率预测，也用来给青训选人。","talk",null,{"direction":"","speaker":"路先森"}],["dingding","第二，谁让你们读的？","talk",null,{"direction":"","speaker":"丁丁"}],["lu","南岸。具体负责人……田楚。","talk",null,{"direction":"","speaker":"路先森"}],["dingding","第三——","talk",null,{"direction":"","speaker":"丁丁"}],["laochen","你别问了。我直接给你们看。","talk",null,{"direction":"打断他","speaker":"老陈"}]],"when":null,"uid":"5-2:5"}],"rewards":{"cards":["v3_19"],"chars":["lu"],"gear":[]},"feather":"lu"},{"id":"5-3","title":"签到表","scene":"warehouse","date":"7 月 28 日 深夜 · 仓库办公室 → 测试舱","desc":"★查找替换成功替换一次扣杀 ★预约投影替你接球 2 次","knowledge":["v3_20"],"kind":"match","steps":[{"t":"cinema","scene":"warehouse","title":"签到表","caption":"7 月 28 日 深夜 · 仓库办公室 → 测试舱","transition":"feather","intro":true,"uid":"5-3:0"},{"t":"dialog","scene":"warehouse","lines":[["nar","老陈打开电脑，屏幕上是一张长长的表格。“鹅湾杯·意图画像签到表”。每一行一个名字，后面一栏是系统自动生成的标签。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","王瑞｜守型｜无攻击意图","stage",null,{}],["nar","猴子｜高点型｜注意力分散","stage",null,{}],["nar","小红｜计算型｜对计划外事件反应差","stage",null,{}],["nar","星星｜感性型｜离开倾向：高","stage",null,{}],["nar","冉冉｜网前型｜综合价值：高（青训重点）","stage",null,{}],["nar","凌风｜扑救型｜综合价值：低","stage",null,{}],["nar","丁丁｜机械型｜情绪干扰源：冉冉","stage",null,{}],["nar","所有人都安静了。星星看着“离开倾向：高”那一栏，悄悄拉了拉衣角。小红看着她。冉冉看着丁丁那一行，丁丁看着地面。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["laochen","我每天填这张表。填了一个月。（声音有点抖）一开始我觉得挺好玩的，就像给大家起外号。","talk",null,{"direction":"","speaker":"老陈"}],["laochen","后来我填到凌风那一行。十五岁。“低价值”。（停顿）我第一次觉得，我在干一件特别恶心的事。","talk",null,{"direction":"","speaker":"老陈"}],["lu","老陈……","talk",null,{"direction":"","speaker":"路先森"}],["laochen","你也觉得恶心，对吧？你每次看到预测被打破，都在偷着笑。我看见了。","smile",null,{"direction":"","speaker":"老陈"}],["lu","……我笑是因为我模型有 bug。","smile",null,{"direction":"","speaker":"路先森"}],["laochen","你笑是因为你高兴。","smile",null,{"direction":"","speaker":"老陈"}],["laochen","（转向大家）我一直觉得我就只配坐在场边记数据。（站起来）今天我想上场打一次。路先森，陪我打。","think",null,{"direction":"","speaker":"老陈"}],["lu","……你会打吗？","talk",null,{"direction":"","speaker":"路先森"}],["laochen","我记了你一个月的数据。","talk",null,{"direction":"","speaker":"老陈"}]],"when":null,"uid":"5-3:1"},{"t":"dialog","scene":"emptyfield","lines":[["nar","测试舱里，老陈身边飘着一张半透明的表格，表格的格子一个个亮起来。他头顶悬着一个小小的“Ctrl+H”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","自动记录对手最近三次出手的位置；同一个区域重复两次，就形成习惯区。习惯区里，预约投影赶过去更快，冰窗也稍大一些。","lesson",null,{"title":"教学·被动「签到表」"}],["nar","在对手头上挂一个 Ctrl+H，准备 0.3 秒后，把对手的下一记进攻（扣杀、平抽）替换成软球。7 秒内有效，触发后返还 3 能量。","lesson",null,{"title":"教学·查找替换（能量 25）"}],["nar","预约你的半场 8 秒（往前拖是网前，否则是后场）。对手的球落进这片区域，投影会替你接。","lesson",null,{"title":"教学·预约击球（能量 25）"}],["nar","投影只守半个场。","lesson",null,{"title":"教学·预约击球（能量 25）"}],["nar","拖动布置一块冰窗，准备 0.25 秒后，捕获第一只经过的球冻结 1.2 秒；再按一次，提前 0.16 秒预告后解冻。","lesson",null,{"title":"教学·冻结窗格（能量 25，可再按）"}],["nar","被冻住的球解冻后，会按原来的方向继续飞。","lesson",null,{"title":"教学·冻结窗格（能量 25，可再按）"}]],"when":null,"uid":"5-3:2"},{"t":"card","card":"v3_20","uid":"5-3:3"},{"t":"match","as":"laochen","opp":"lu","field":"empty","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"5-3:4"},{"t":"dialog","scene":"emptyfield","lines":[["lu","……你什么时候学会的？","talk",null,{"direction":"","speaker":"路先森"}],["laochen","我说了，我记了你一个月的数据。你每次输都往左后场跑。","talk",null,{"direction":"","speaker":"老陈"}],["lu","我的模型都没算出来这个。","surprise",null,{"direction":"愣了很久，然后笑出声","speaker":"路先森"}]],"when":null,"uid":"5-3:5"}],"rewards":{"cards":["v3_20"],"chars":["laochen"],"gear":[]},"feather":"laochen"},{"id":"5-4","title":"样本 #0001","scene":"warehouse","date":"7 月 28 日 凌晨 · 仓库档案室 → 读球：2018 年 5 月，镇一中老体育馆","desc":"★打满 20 拍 ★接住田楚的最后一个球","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"warehouse","title":"样本 #0001","caption":"7 月 28 日 凌晨 · 仓库档案室 → 读球：2018 年 5 月，镇一中老体育馆","transition":"feather","intro":true,"uid":"5-4:0"},{"t":"dialog","scene":"warehouse","lines":[["nar","路先森从档案柜最深处抽出一个文件夹，封面印着“南岸读羽系统·核心专利”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lu","你们想知道这个东西是从哪儿来的吗？","think",null,{"direction":"","speaker":"路先森"}],["nar","文件夹第一页，是一张被扫描进去的蜡笔画：一个像蒸笼一样的机器，旁边写着“听球”。角落里，有一行歪歪扭扭的小字：“丁丁造”。和丁丁后屋墙上那张一模一样，只是颜色更鲜。这一张是原件；丁丁墙上那张，是他后来凭记忆重画的。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","丁丁盯着那张画，一动不动。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lu","南岸读羽系统的原型，是两个小孩做的玩具。专利是三年前田楚申请的。发明人一栏……（翻到最后一页）写着两个名字。","talk",null,{"direction":"","speaker":"路先森"}],["nar","发明人：田楚、丁丁","stage",null,{}],["ruibao","……你？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","我不知道。我从来不知道。","talk",null,{"direction":"声音发干","speaker":"丁丁"}],["lu","样本库里编号第一的那只球，就是那个玩具第一次真正“响”的时候读出来的。田楚亲手放进去的。","talk",null,{"direction":"","speaker":"路先森"}],["laochen","#0001。要读吗？","talk",null,{"direction":"","speaker":"老陈"}],["dingding","……读。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"5-4:1"},{"t":"dialog","scene":"younggym","lines":[["nar","羽场里，是八年前的老体育馆。阳光比现在亮，木地板比现在新。场上站着一个特别小的男孩，戴着一副大眼镜，拍子几乎和他一样高。对面是一个瘦瘦的少年，在笑。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","……你那时候好小。","talk",null,{"direction":"天上的声音，轻轻的","speaker":"瑞宝"}],["nar","十四岁的田楚，没有影子，没有镜子，没有水纹。只有一个少年和一个小孩，在一块干干净净的球场上打球。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"5-4:2"},{"t":"match","as":"dingding","opp":"tianchu","field":"memory","level":"normal","target":1,"cap":1,"allowLoss":true,"stars":[],"oppSkills":false,"skills":false,"age":[10,14],"gentle":true,"rallyGoal":20,"intentSide":1,"intents":["这小孩真能跑","别让他输得太难看","以后他会比我强","……那我就得更强"],"venue":"youngcourt","uid":"5-4:3"},{"t":"dialog","scene":"younggym","lines":[["nar","这小孩真能跑","intent",null,{"title":"球记得的念头"}],["nar","别让他输得太难看","intent",null,{"title":"球记得的念头"}],["nar","以后他会比我强","intent",null,{"title":"球记得的念头"}],["nar","……那我就得更强","intent",null,{"title":"球记得的念头"}]],"when":null,"uid":"5-4:4"},{"t":"dialog","scene":"younggym","lines":[["nar","最后一拍。小丁丁扑过去，摔了个跟头，却把球挑了起来。少年田楚哈哈大笑，跑过来把他拉起来，揉乱他的头发。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-hand"}],["tianchu","师弟！你接住了！","talk",null,{"direction":"","speaker":"少年田楚","cg":"cg-hand"}],["nar","记忆显影完成。丁丁摘下头环。仓库里很安静。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-hand"}],["lu","老板办公室旁边有个罐子屋。所有重要样本的原件都在那儿，一只球一个玻璃罐。（停顿）听说最老的一罐，连老板自己都没开过。","talk",null,{"direction":"","speaker":"路先森","cg":"cg-hand"}],["bobo","玻璃罐？密封的？","talk",null,{"direction":"突然抬起头","speaker":"波波","cg":"cg-hand"}],["lu","真空的。","talk",null,{"direction":"","speaker":"路先森","cg":"cg-hand"}],["bobo","……琥珀。","talk",null,{"direction":"小声","speaker":"波波","cg":"cg-hand"}]],"when":null,"uid":"5-4:5"}],"rewards":{"cards":[],"chars":["mage"],"gear":[]},"feather":"mage"},{"id":"5-5","title":"脏数据","scene":"warehouse","date":"7 月 28 日 凌晨 · 仓库","desc":"免费的球，原来记得所有人的名字。","knowledge":[],"kind":"pick","steps":[{"t":"cinema","scene":"warehouse","title":"脏数据","caption":"7 月 28 日 凌晨 · 仓库","transition":"feather","intro":true,"uid":"5-5:0"},{"t":"dialog","scene":"warehouse","lines":[["laochen","我们手上能调出所有人的画像。包括……田楚的。","talk",null,{"direction":"","speaker":"老陈"}]],"when":null,"uid":"5-5:1"},{"t":"pick","key":"profile","q":"要看田楚的意图画像吗？","o":[{"label":"看画像","value":"read","reply":"read","note":"你记住的是：疲劳，极高。","ok":true},{"label":"不看，听他自己说","value":"wait","reply":"wait","note":"丁丁：那是他的。我想听他自己说。","ok":true}],"exp":"没有标准答案。这句话会留在羽毛册里。","uid":"5-5:2"},{"t":"dialog","scene":"warehouse","lines":[["nar","田楚｜欺骗型｜情绪：恨（对象：丁丁）｜疲劳：极高","stage"],["dingding","……他累了。","sad"]],"when":{"choice":"profile","value":"read"},"uid":"5-5:3"},{"t":"dialog","scene":"warehouse","lines":[["dingding","不看。那是他的。我想听他自己说。","think"]],"when":{"choice":"profile","value":"wait"},"uid":"5-5:4"},{"t":"dialog","scene":"warehouse","lines":[["nar","路先森打开笔记本电脑，手指在键盘上飞快地敲。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lu","从今天起，南岸的模型会吃到一点……脏东西。","talk",null,{"direction":"","speaker":"路先森"}],["laochen","脏数据。","talk",null,{"direction":"","speaker":"老陈"}],["lu","一点点。不会被发现。只是让它……别那么确定。","talk",null,{"direction":"","speaker":"路先森"}],["laochen","我也改了签到表。凌风那一栏，我改成了“待观察”。","talk",null,{"direction":"","speaker":"老陈"}],["dingding","你们会被开除的。","talk",null,{"direction":"","speaker":"丁丁"}],["lu","我们是实习生。（停顿）实习生被开除，叫“提前结束实习”。","talk",null,{"direction":"","speaker":"路先森"}],["laochen","不好笑。","smile",null,{"direction":"","speaker":"老陈"}],["lu","这次是真的不好笑。（合上电脑）但我觉得值。","smile",null,{"direction":"","speaker":"路先森"}]],"when":null,"uid":"5-5:5"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]},{"id":"ch6","title":"第六章 · 押谁赢","date":"8.2—8.8","scene":"goosefarm","blurb":"大概率的事，赚不到大钱。","venue":"homecourt","act":"被听见","stages":[{"id":"6-1","title":"果然健身","scene":"fitness","date":"8 月 2 日 · 果然健身房","desc":"大概率的事，赚不到大钱。","knowledge":["v3_21"],"kind":"special","steps":[{"t":"cinema","scene":"fitness","title":"果然健身","caption":"8 月 2 日 · 果然健身房","transition":"ink","intro":true,"uid":"6-1:0"},{"t":"dialog","scene":"fitness","lines":[["nar","健身房里震耳欲聋的音乐。果哥躺在卧推凳上，旁边的白板上写满了“鹅湾杯竞猜”的赔率，单位是“包”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","田楚 1 赔 1.02 包｜苗苗（南岸）1 赔 1.1 包｜冉冉 1 赔 4 包｜丁丁 1 赔 30 包｜猴子 1 赔 200 包","stage",null,{}],["houzi","我两百倍？！","surprise",null,{"direction":"","speaker":"猴子"}],["guoge","小伙子，你这个价位很有投资价值，买的人少，一旦涨起来——","talk",null,{"direction":"","speaker":"果哥"}],["houzi","会涨吗？","talk",null,{"direction":"","speaker":"猴子"}],["guoge","不会。（坐起来）但你要相信。","talk",null,{"direction":"","speaker":"果哥"}],["dingding","果哥，你押的谁？","talk",null,{"direction":"","speaker":"丁丁"}],["guoge","我？我分散投资。田楚押一百包，苗苗押五十包，你们几个每人押一包，图个吉利。","talk",null,{"direction":"","speaker":"果哥"}],["ruibao","你押一百包田楚，你哪来的一百包？","talk",null,{"direction":"","speaker":"瑞宝"}],["guoge","赊的。你家的。","talk",null,{"direction":"","speaker":"果哥"}],["ruibao","……","talk",null,{"direction":"","speaker":"瑞宝"}],["guoge","我跟你们说，人这辈子，就要站在要赢的那一边。我从小到大都这么干——（举起一支球拍）你看这支，头重的，扣杀狠，但挥拍慢；这支头轻，防守快，但杀不动。我两支都买。分散投资！","talk",null,{"direction":"","speaker":"果哥"}]],"when":null,"uid":"6-1:1"},{"t":"card","card":"v3_21","uid":"6-1:2"},{"t":"dialog","scene":"fitness","lines":[["dingding","那你从小到大，赚到过大的吗？","talk",null,{"direction":"","speaker":"丁丁"}],["guoge","……没有。（又躺了回去）但也没亏过大的。","surprise",null,{"direction":"愣了一下","speaker":"果哥"}]],"when":null,"uid":"6-1:3"}],"rewards":{"cards":["v3_21"],"chars":[],"gear":[]},"feather":null},{"id":"6-2","title":"一掷千金","scene":"emptyfield","date":"8 月 2 日 · 健身房里的南岸体验舱（果哥买的）","desc":"★押这一分并赢下 ★升级到“量子实验室”装备档","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"emptyfield","title":"一掷千金","caption":"8 月 2 日 · 健身房里的南岸体验舱（果哥买的）","transition":"ink","intro":true,"uid":"6-2:0"},{"t":"dialog","scene":"emptyfield","lines":[["guoge","我买了一台南岸体验舱，花了我半年的会员费。今天开张，你们是第一批客户。","talk",null,{"direction":"","speaker":"果哥"}],["ruibao","多少钱一次？","talk",null,{"direction":"","speaker":"瑞宝"}],["guoge","三个包子。","talk",null,{"direction":"","speaker":"果哥"}],["nar","羽场里，果哥穿着一身破旧的运动服，手里是一支合金拍。他头顶悬着一行金色数字：500。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","你开局有 500 金币。亲手回球 +15，完美回球再 +15；赢一分 +100，丢一分 −120。","lesson",null,{"title":"教学·被动「装备交易所」"}],["nar","金币到 600 / 900 / 1200 / 1600 时，装备自动升档：科技 → 纳米 → 量子 → 火箭。降档时有 60 金币缓冲。金币 ≤0 就会负债。","lesson",null,{"title":"教学·被动「装备交易所」"}],["nar","到达火箭档后，三次完美回球能蓄满一次推进。","lesson",null,{"title":"教学·被动「装备交易所」"}],["guoge","看见没，我就是靠这个活着的。","talk",null,{"direction":"","speaker":"果哥"}],["nar","花 100 金币押这一分。发球前押，赢了返 3 倍；回合中押，返 2 倍。","lesson",null,{"title":"教学·押这一分（能量 20）"}],["nar","押注和金砖同一分结算，最多 350。","lesson",null,{"title":"教学·押这一分（能量 20）"}],["nar","（对手的应对：稳住别失误，拖长回合让他着急。）","lesson",null,{"title":"教学·押这一分（能量 20）"}],["nar","花 60 金币，往对手半场撒 3 个红包，持续 5 秒。对手在地上踩到就会弯腰捡钱，原地停 0.4 秒。起跳能躲开。","lesson",null,{"title":"教学·红包雨（能量 25）"}],["nar","花 50 金币，让你的下一拍变成金砖：压低对手的回球，接到的人会被震退。直接得分奖励 200，同一分技能结算最多 350。","lesson",null,{"title":"教学·一掷千金（能量 25）"}]],"when":null,"uid":"6-2:1"},{"t":"match","as":"guoge","opp":"ruibao","field":"empty","level":"normal","target":7,"cap":11,"allowLoss":true,"stars":[],"training":true,"uid":"6-2:2"},{"t":"dialog","scene":"emptyfield","lines":[["guoge","看见没！这就是投资！","cheer",null,{"direction":"升到火箭档，浑身冒火，兴奋得大喊","speaker":"果哥"}],["ruibao","果哥，你知道你刚刚花了多少金币吗？","talk",null,{"direction":"","speaker":"瑞宝"}],["guoge","不知道。","talk",null,{"direction":"","speaker":"果哥"}],["ruibao","一千二。","talk",null,{"direction":"","speaker":"瑞宝"}],["guoge","……那赚了多少？","talk",null,{"direction":"","speaker":"果哥"}],["ruibao","一千一。","talk",null,{"direction":"","speaker":"瑞宝"}],["guoge","……下次我分散投资。","talk",null,{"direction":"沉默了一会儿","speaker":"果哥"}]],"when":null,"uid":"6-2:3"}],"rewards":{"cards":[],"chars":["guoge"],"gear":["r_shield"]},"feather":"guoge"},{"id":"6-3","title":"大将军","scene":"goosefarm","date":"8 月 4 日 · 江边鹅场","desc":"八组抽检 · 凑齐同侧十六根羽毛","knowledge":["v3_22"],"kind":"minigame","steps":[{"t":"cinema","scene":"goosefarm","title":"大将军","caption":"8 月 4 日 · 江边鹅场","transition":"ink","intro":true,"uid":"6-3:0"},{"t":"dialog","scene":"goosefarm","lines":[["nar","江边一大片绿草地，几百只大白鹅，一个木头鹅棚。棚边挂着一块牌子：“刘家鹅场·正宗鹅湾正手毛”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","一只特别大的鹅从棚里冲出来，脖子伸得笔直，对着波波一路追。波波抱着他的化石包拼命跑。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["bobo","救命——！它是食肉的！","talk",null,{"direction":"","speaker":"波波"}],["houzi","鹅是吃草的！","talk",null,{"direction":"","speaker":"猴子"}],["bobo","它的祖先不是！","talk",null,{"direction":"","speaker":"波波"}],["nar","一个高个子女孩从棚里走出来。肩膀很宽，手臂结实，一只胳膊下面夹着一只鹅。她伸出另一只手，一把拎住那只大鹅的脖子，大鹅瞬间安静了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["miaomiao","大将军。不许追人。","talk",null,{"direction":"","speaker":"苗苗"}],["goose","嘎。","talk",null,{"direction":"","speaker":"大将军"}],["miaomiao","……对不起。它不喜欢背包。","think",null,{"direction":"看着瘫在地上的波波","speaker":"苗苗"}],["bobo","……你养的是恐龙。","talk",null,{"direction":"爬起来，眼睛发亮","speaker":"波波"}],["miaomiao","……什么？","talk",null,{"direction":"","speaker":"苗苗"}],["bobo","鹅是恐龙。大将军，是兽脚类恐龙的后代。你看它的脚，三个脚趾朝前——","talk",null,{"direction":"","speaker":"波波"}],["nar","苗苗愣愣地看着他，然后，很轻很轻地笑了一下。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","你好，我想买一点羽毛。做一只球。","think",null,{"direction":"","speaker":"丁丁"}],["miaomiao","……做球？","talk",null,{"direction":"","speaker":"苗苗"}],["dingding","手工做。十六根羽毛，一只球。","talk",null,{"direction":"","speaker":"丁丁"}],["grandma","小伙子，现在会手工做球的年轻人可不多了。来，奶奶教你挑毛。","talk",null,{"direction":"从棚里走出来，满头白发","speaker":"苗苗外婆"}]],"when":null,"uid":"6-3:1"},{"t":"minigame","game":"sorting","title":"挑齐十六根羽毛","goal":16,"uid":"6-3:2"},{"t":"dialog","scene":"goosefarm","lines":[["nar","一只球的十六根羽毛，必须来自鹅的同一侧翅膀，弯曲方向一致，飞起来旋转才稳定。","lesson",null,{"title":"教学·分拣小游戏"}],["nar","拖动羽毛：左翅膀的毛放左边，右翅膀的毛放右边，残缺或弯曲不够的放进废料筐。","lesson",null,{"title":"教学·分拣小游戏"}]],"when":null,"uid":"6-3:3"},{"t":"card","card":"v3_22","uid":"6-3:4"},{"t":"dialog","scene":"goosefarm","lines":[["grandma","一只鹅身上，每边翅膀只有六七根合格的毛。一只球，就要好几只鹅。","talk",null,{"direction":"","speaker":"外婆"}],["dingding","……那十六根，就是十六只鹅身上最好的那根。","talk",null,{"direction":"","speaker":"丁丁"}],["grandma","对咯。","talk",null,{"direction":"","speaker":"外婆"}],["nar","苗苗在旁边帮着挑，手特别快，一根都没挑错。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","你也会做？","talk",null,{"direction":"","speaker":"丁丁"}],["miaomiao","从小就会。（停顿）我小时候想当做球的人。","think",null,{"direction":"","speaker":"苗苗"}],["dingding","后来呢？","talk",null,{"direction":"","speaker":"丁丁"}],["miaomiao","……送你。","talk",null,{"direction":"没回答，把挑好的十六根羽毛扎成一小束，递给他","speaker":"苗苗"}],["nar","第二天，鹅湾杯签到处。丁丁抱着一筐球走过去，一抬头，看见苗苗站在南岸队伍最前面，穿着蓝白色的正式队服。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","南岸工作人员：南岸王牌，苗苗！两年零七个月比赛零失误！","stage",null,{}],["nar","波波手里的化石“啪”地掉在地上。","stage","snap",{"silent":false,"cue":"snap","white":false,"black":false}]],"when":null,"uid":"6-3:5"}],"rewards":{"cards":["v3_22"],"chars":[],"gear":["s_rep","sh_cushion"]},"feather":null},{"id":"6-4","title":"开幕","scene":"league","date":"8 月 6 日 · 镇体育中心，鹅湾杯正赛首轮","desc":"★打破预测 ★带两个不同技能上场并各用一次","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"开幕","caption":"8 月 6 日 · 镇体育中心，鹅湾杯正赛首轮","transition":"ink","intro":true,"uid":"6-4:0"},{"t":"dialog","scene":"league","lines":[["nar","体育中心座无虚席。全镇的人都来了，瑞妈带着包子，果哥举着“果然健身”的应援牌，朱老师坐在老位置，膝盖上放着保温杯。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","开赛前可以进入器械库配装：选择球拍（重量 U 数、平衡点、中杆软硬）、球线、磅数、球鞋。不同装备会改变力量、控球、网前、甜区、防守、移动和体力。","lesson",null,{"title":"教学·器械库"}],["nar","选择这一场要带的两个主动技能。被动始终生效。","lesson",null,{"title":"教学·器械库"}]],"when":null,"uid":"6-4:1"},{"t":"match","as":"choose","opp":"academy","field":"league","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"prediction":22,"gear":true,"uid":"6-4:2"},{"t":"dialog","scene":"league","lines":[["nar","大屏：预测被打破。全场欢呼。果哥偷偷把白板上的赔率擦掉重写。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["guoge","分散投资！分散投资是对的！","talk",null,{"direction":"","speaker":"果哥"}]],"when":{"outcome":true},"uid":"6-4:3"},{"t":"dialog","scene":"league","lines":[["zhu","输了一场，不是输了一个夏天。","talk",null,{"direction":"场边","speaker":"朱老师"}]],"when":{"outcome":false},"uid":"6-4:4"},{"t":"dialog","scene":"league","lines":[["nar","首轮采用积分制。输了一场，你仍然晋级了。","stage"]],"when":{"outcome":false},"uid":"6-4:5"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"6-5","title":"两年零七个月","scene":"league","date":"8 月 8 日 · 鹅湾杯 R2","desc":"让苗苗失误一次即可推进。★得 4 分 ★让苗苗失误 2 次","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"两年零七个月","caption":"8 月 8 日 · 鹅湾杯 R2","transition":"ink","intro":true,"uid":"6-5:0"},{"t":"dialog","scene":"league","lines":[["nar","苗苗站在羽场里，脚下的地板像铁一样纹丝不动。她身后，一只发光的大白鹅昂着脖子来回巡视。凌风站在对面，深吸一口气，把膝盖上的创可贴又按了按。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["lingfeng","苗苗姐，我会扑的。很难看的那种。","talk",null,{"direction":"","speaker":"凌风"}],["miaomiao","……嗯。","talk",null,{"direction":"","speaker":"苗苗"}]],"when":null,"uid":"6-5:1"},{"t":"match","as":"lingfeng","opp":"miaomiao","field":"league","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"prediction":3,"stable":true,"errorGoal":1,"uid":"6-5:2"},{"t":"dialog","scene":"league","lines":[["lu","凌风选手第十七次鱼跃……没够到。第十八次……没够到。第十九次——","talk",null,{"direction":"","speaker":"解说（路先森，实习生临时客串）"}],["nar","第十九次，凌风扑到了。 球歪歪扭扭地飞起来，擦着网带滚过去。苗苗伸拍去够，球从她拍框边缘擦过，落地。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","全场安静。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","大屏右下角，一个计数器跳了一下：“苗苗 连续零失误：两年七个月零三天 → 0”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","苗苗站在原地，看着那只球，看了很久。然后，她笑了。不是很轻的那种笑，是真的笑出声了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["miaomiao","……你扑得真难看。","talk",null,{"direction":"","speaker":"苗苗"}],["lingfeng","谢谢？","talk",null,{"direction":"趴在地上","speaker":"凌风"}],["miaomiao","也真好看。","talk",null,{"direction":"","speaker":"苗苗"}],["nar","下场时，苗苗经过观众席。波波站起来冲她挥手，手里还攥着那块“希望是羽毛”的石头。苗苗犹豫了一下，也挥了挥手。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"6-5:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]},{"id":"ch7","title":"第七章 · 英仙座","date":"8.10—8.13","scene":"rooftop-rain","blurb":"三十七页计划，和一行不用等流星的话。","venue":"homecourt","act":"被听见","stages":[{"id":"7-1","title":"第三十七页","scene":"backroom","date":"8 月 10 日 · 穿线铺后屋","desc":"三十七页计划，和一行不用等流星的话。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"backroom","title":"第三十七页","caption":"8 月 10 日 · 穿线铺后屋","transition":"feather","intro":true,"uid":"7-1:0"},{"t":"dialog","scene":"backroom","lines":[["nar","小红把那本厚笔记本摊在工作台上。封面写着：“8/12 行动方案 v4.3”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","一共三十七页。第一部分，地点：天台，坐标精确到栏杆第七根。第二部分，时间：英仙座极大时刻前后，我计算了第三颗流星出现的概率窗口——","think",null,{"direction":"","speaker":"小红"}],["ruibao","你要在第三颗流星的时候开口？","talk",null,{"direction":"","speaker":"瑞宝"}],["xiaohong","第一颗太早，她还在找方向；第二颗她会许愿；第三颗，她会转头看我。","talk",null,{"direction":"","speaker":"小红"}],["houzi","要是第三颗没来呢？","talk",null,{"direction":"","speaker":"猴子"}],["xiaohong","附录 B，备选方案。","talk",null,{"direction":"","speaker":"小红"}],["dingding","第三十七页写的什么？","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","“如果她拒绝”。","talk",null,{"direction":"沉默了一下，翻到最后一页。上面只有一个标题，下面一片空白","speaker":"小红"}],["xiaohong","……这一页我写不出来。","talk",null,{"direction":"","speaker":"小红"}],["nar","大家都没说话。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","你呢？","talk",null,{"direction":"合上本子，看向丁丁","speaker":"小红"}],["dingding","我什么？","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","你打算什么时候说？","think",null,{"direction":"","speaker":"小红"}],["dingding","……等一个合适的时候。","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","你等了三年了。你知道三年是多少天吗？一千零九十五天，你一天都没觉得合适？","talk",null,{"direction":"","speaker":"小红"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","我算过了。在你等的这一千多天里，她可能会喜欢上别人，可能会离开，可能会觉得你根本不在乎。（停顿）概率不低。","think",null,{"direction":"","speaker":"小红"}],["dingding","你也会算错。","think",null,{"direction":"","speaker":"丁丁"}],["xiaohong","我算错了还能重算。你一直不算，就永远是零。","think",null,{"direction":"","speaker":"小红"}],["nar","另一边，天台上。星星在一张便签纸上写字，写了一行，看了很久，折好，放进口袋。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"7-1:1"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"7-2","title":"八月十二日，阴","scene":"rooftop-rain","date":"8 月 12 日 夜 · 气象站天台","desc":"三十七页计划，和一行不用等流星的话。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"rooftop-rain","title":"八月十二日，阴","caption":"8 月 12 日 夜 · 气象站天台","transition":"feather","intro":true,"uid":"7-2:0"},{"t":"dialog","scene":"rooftop-rain","lines":[["nar","九点。天台上，望远镜架好，野餐垫铺好，小红的蓝牙音箱里放着精心挑选的歌单（附录 C）。星星坐在垫子上抬头看天。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","天上一颗星星都没有。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","……云量百分之九十五。","talk",null,{"direction":"看手机","speaker":"小红"}],["xingxing","嗯。","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","天气预报说是晴。","talk",null,{"direction":"","speaker":"小红"}],["xingxing","天气预报也会错。","talk",null,{"direction":"","speaker":"星星"}],["nar","十点。还是阴天。小红翻到附录 B，又翻到附录 C，手在抖。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","十点半。一滴雨落在望远镜上。然后是第二滴、第三滴。","stage","rain",{"silent":false,"cue":"rain","white":false,"black":false}],["nar","大雨倾盆。所有人抱着东西冲进楼梯间。小红的笔记本被雨淋湿了，墨水晕成一片。他蹲在楼梯拐角，看着那本湿透的计划书，一句话都不说。","stage","rain",{"silent":false,"cue":"rain","white":false,"black":false}],["nar","其他人都悄悄下楼了。只剩星星。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xingxing","小红。","talk",null,{"direction":"在他身边蹲下","speaker":"星星"}],["xiaohong","……全没了。三十七页，全没了。","talk",null,{"direction":"","speaker":"小红"}],["xingxing","流星雨又不是只有今年。","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","可是你九月就走了。","talk",null,{"direction":"","speaker":"小红"}],["nar","星星愣住了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","两千三百公里。我知道。你考上的那天我就查了。（声音很低）我算了一个暑假，算我们一年能见几次，算高铁要多久，算要攒多少钱。我算了好多好多东西，就是……没算出来该怎么开口。","think",null,{"direction":"","speaker":"小红"}]],"when":null,"uid":"7-2:1"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"7-3","title":"星星不落","scene":"backroom","date":"8 月 12 日 深夜 · 穿线铺后屋 → 读球：2023 年 9 月，镇一中操场","desc":"★小红的反射板把球弹进星星的月亮 1 次 ★打满整段记忆","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"backroom","title":"星星不落","caption":"8 月 12 日 深夜 · 穿线铺后屋 → 读球：2023 年 9 月，镇一中操场","transition":"feather","intro":true,"uid":"7-3:0"},{"t":"dialog","scene":"backroom","lines":[["nar","两个人湿淋淋地来到穿线铺。丁丁什么都没问，递过去两条毛巾。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","你还留着你们第一次打球的那只球吗？","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","……留着。（从书包内袋里掏出一个密封袋，袋子里是一只很旧的球）高一开学第一周。她把球打到我头上了。","talk",null,{"direction":"","speaker":"小红"}],["xingxing","……你还留着这个？","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","留着。","talk",null,{"direction":"","speaker":"小红"}],["dingding","读吗？","talk",null,{"direction":"","speaker":"丁丁"}],["xingxing","读。（看着小红）我想看。","think",null,{"direction":"","speaker":"星星"}]],"when":null,"uid":"7-3:1"},{"t":"dialog","scene":"memory-stars","lines":[["nar","羽场里，是三年前九月的操场。天是晴的，夜空中星星满天。十五岁的小红和十五岁的星星在操场边上打球，都很笨拙。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xingxing","……今天看不见的星星，在这里都看得见。","talk",null,{"direction":"羽场里，仰头","speaker":"星星"}]],"when":null,"uid":"7-3:2"},{"t":"match","as":"xiaohong","opp":"xingxing","field":"memory","level":"normal","target":2,"cap":3,"allowLoss":true,"stars":[],"gentle":true,"age":[15,15],"intentSide":1,"intents":["这个人好认真，好好笑","她笑起来眼睛是弯的","……要怎么算才能让她多笑一下"],"venue":"starcourt","uid":"7-3:3"},{"t":"dialog","scene":"memory-stars","lines":[["nar","（高一的星星）这个人好认真，好好笑","intent",null,{"title":"球记得的念头"}],["nar","（高一的小红）她笑起来眼睛是弯的","intent",null,{"title":"球记得的念头"}],["nar","（高一的小红）……要怎么算才能让她多笑一下","intent",null,{"title":"球记得的念头"}]],"when":null,"uid":"7-3:4"},{"t":"match","as":"xingxing","opp":"xiaohong","field":"memory","level":"normal","target":2,"cap":3,"allowLoss":true,"stars":[],"gentle":true,"age":[15,15],"intentSide":0,"intents":["明天还想跟他打","后天也想"],"venue":"starcourt","switching":true,"uid":"7-3:5"},{"t":"dialog","scene":"memory-stars","lines":[["nar","中途切换：画面翻转，玩家改为操控星星。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","（高一的星星）明天还想跟他打","intent",null,{"title":"球记得的念头"}],["nar","（高一的星星）后天也想","intent",null,{"title":"球记得的念头"}]],"when":null,"uid":"7-3:6"},{"t":"dialog","scene":"memory-stars","lines":[["nar","最后一拍。小红把球打到反射板上，星星的月亮接住了它，绕了三圈，甩向夜空，划出一道长长的光，像一颗流星。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-meteor"}]],"when":null,"uid":"7-3:7"},{"t":"dialog","scene":"backroom","lines":[["nar","记忆显影完成。两个人摘下头环，坐在后屋的地板上，头发还在滴水。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xingxing","我也写了一个计划。","talk",null,{"direction":"从湿透的口袋里掏出那张便签，已经皱成一团，展开","speaker":"星星"}],["xiaohong","……多少页？","talk",null,{"direction":"","speaker":"小红"}],["xingxing","一行。（念出来）“如果下雨，就算了，直接说。”","think",null,{"direction":"","speaker":"星星"}],["xiaohong","……","talk",null,{"direction":"","speaker":"小红"}],["xingxing","小红，我喜欢你。从高一你被球砸到头、还要跟我解释抛物线那天开始。","shy",null,{"direction":"","speaker":"星星"}],["nar","小红张了张嘴，没说出话。他看着星星，眼眶慢慢红了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","……我也是。我本来要在第三颗流星的时候说的。","talk",null,{"direction":"","speaker":"小红"}],["xingxing","那你现在说。","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","我喜欢你。（停顿）我们一年能见四到六次。","shy",null,{"direction":"","speaker":"小红"}],["xingxing","你还是算了。","smile",null,{"direction":"笑出声","speaker":"星星"}],["xiaohong","按高铁，十一个小时。","talk",null,{"direction":"","speaker":"小红"}],["xingxing","你算这个干嘛？","think",null,{"direction":"","speaker":"星星"}],["xiaohong","算我多久能到。","think",null,{"direction":"","speaker":"小红"}],["nar","门外，丁丁靠在墙上，听着屋里的声音，慢慢笑了一下，笑完又低下了头。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"7-3:8"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"7-4","title":"墙后面","scene":"bakery-night","date":"8 月 13 日 凌晨三点 · 王记包子铺","desc":"三十七页计划，和一行不用等流星的话。","knowledge":[],"kind":"inspect","steps":[{"t":"cinema","scene":"bakery-night","title":"墙后面","caption":"8 月 13 日 凌晨三点 · 王记包子铺","transition":"feather","intro":true,"uid":"7-4:0"},{"t":"dialog","scene":"bakery-night","lines":[["nar","丁丁睡不着，出门透气。整条街都是黑的，只有对面包子铺的后厨亮着灯，蒸汽从门缝里漏出来。","stage",null,{"silent":true,"cue":null,"white":false,"black":false}]],"when":null,"uid":"7-4:1"},{"t":"inspect","scene":"bakery-night","title":"凌晨三点，只有揉面的声音","items":[{"id":"bakery-form","label":"垫蒸笼的纸","text":"2026 年普通高校招生志愿确认单·王瑞。确认截止：7 月 5 日。签名栏是空的。","clue":"bakery-form","x":0.17,"y":0.28},{"id":"bakery-dough","label":"没有音乐的后厨","text":"瑞宝独自揉面。父亲要手术，母亲一个人撑不起店。","clue":"bakery-dough","x":0.48,"y":0.28},{"id":"bakery-fan","label":"老王包子","text":"躺在楼上的王爸，每次看直播都刷“稳住”。他只是想看看儿子打球。","clue":"bakery-fan","x":0.79,"y":0.28}],"uid":"7-4:2"},{"t":"dialog","scene":"bakery-night","lines":[["nar","丁丁走过去，把那张纸抽了出来。瑞宝看见了，没有抢。","stage",null,{"silent":true,"cue":null,"white":false,"black":false}],["nar","纸展开。“2026 年普通高校招生志愿确认单·王瑞”。确认截止日期：7 月 5 日。签名栏是空的。","stage",null,{"silent":true,"cue":null,"white":false,"black":false}],["dingding","……这是什么？","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","垫蒸笼的。","talk",null,{"direction":"继续和面，不抬头","speaker":"瑞宝"}],["dingding","瑞宝。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","……我爸的腰不是闪了。是腰椎间盘突出，压着神经，要做手术，要躺好几个月。我妈一个人撑不起这个店。（手停了下来）所以我没交。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","南京呢？食品工程呢？","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","骗你们的。我说出来了，你们就会一直劝我，一直替我难受。我不想看你们难受。","think",null,{"direction":"","speaker":"瑞宝"}],["nar","丁丁想起猴子直播间里那个每次都刷“稳住”的“老王包子”。","stage",null,{"silent":true,"cue":null,"white":false,"black":false}],["dingding","……老王包子，是你爸。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","他躺着没事干，天天看猴子直播。我跟他说过，别刷了，人家会知道。他说不怕，他就想看看儿子打球。","smile",null,{"direction":"笑了一下，眼睛红了","speaker":"瑞宝"}],["dingding","你为什么不说？","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","你说了吗？","talk",null,{"direction":"突然抬起头，声音大了起来","speaker":"瑞宝"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","你喜欢她三年，你说了吗？你师兄的事憋了四年，你说了吗？你不打球了，你跟我说过一句为什么吗？","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","蒸笼的汽声。两个人隔着一张面案，谁都没说话。","stage",null,{"silent":true,"cue":null,"white":false,"black":false}],["ruibao","……我们俩是一样的，丁丁。从小就一样。什么都憋着，憋到最后，就以为别人看不出来。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","……我看出来了。我早就该看出来的。","talk",null,{"direction":"很久，很轻地","speaker":"丁丁"}],["nar","门口响起一个声音。猴子穿着拖鞋站在那里，手里攥着一张早餐券。","stage",null,{"silent":true,"cue":null,"white":false,"black":false}],["houzi","……那个，我来买早饭的。三点开门吗？","talk",null,{"direction":"","speaker":"猴子"}],["ruibao","……你凌晨三点来买早饭？","talk",null,{"direction":"","speaker":"瑞宝"}],["houzi","我也睡不着。（走进来，坐在门槛上）你们刚才说的我都听见了。","talk",null,{"direction":"","speaker":"猴子"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["houzi","我没什么秘密啊。真的，我连游戏密码都告诉过你们。（停顿）我就是……我就是怕你们都走了。小红去北京，星星去高原，冉冉不知道去哪，丁丁去省城，瑞宝……","talk",null,{"direction":"挠了挠头","speaker":"猴子"}],["houzi","瑞宝原来不走。（笑了一下，笑得很难看）那挺好。那至少还剩一个。","smile",null,{"direction":"","speaker":"猴子"}],["houzi","……完了，说出来好丢人。","talk",null,{"direction":"","speaker":"猴子"}]],"when":null,"uid":"7-4:3"},{"t":"dialog","scene":"bakery-night","lines":[["nar","瑞宝走过去，一把把猴子从门槛上拽起来，抱住。丁丁也走过去。三个大男生在凌晨三点的包子铺后厨，抱成一团，满身面粉。","stage",null,{"silent":true,"cue":null,"white":false,"black":false,"cg":"cg-flour"}]],"when":null,"uid":"7-4:4"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"7-5","title":"一笼包子的时间","scene":"emptyfield","date":"8 月 13 日 清晨 · 听球机空场","desc":"在一笼包子蒸好之前（限时 8 分钟）打完比赛。★赢下比赛 ★打碎瑞宝的墙（地板开球的墙被球击中 6 次）","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"emptyfield","title":"一笼包子的时间","caption":"8 月 13 日 清晨 · 听球机空场","transition":"feather","intro":true,"uid":"7-5:0"},{"t":"dialog","scene":"emptyfield","lines":[["ruibao","最后一笼包子上锅了，八分钟。来一局。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","现在？","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","就现在。别让我等一个合适的时候。","talk",null,{"direction":"","speaker":"瑞宝"}],["nar","空场里，瑞宝身后的墙比上一次更高、更厚，灰缝里那两个字更清楚了：别进。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"7-5:1"},{"t":"match","as":"dingding","opp":"ruibao","field":"empty","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"timeLimit":480,"wallBreak":6,"uid":"7-5:2"},{"t":"dialog","scene":"emptyfield","lines":[["nar","墙后面什么都没有，只有瑞宝。他站在那里，没有墙，没有蒸笼盖，就是一个穿着围裙、满身面粉的大男孩。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","（空场里不该出现文字，但这一刻，碎掉的墙砖上浮出一行字）进来吧","intent",null,{"title":"球记得的念头"}],["ruibao","明年我再考。今年，先把店撑住。","talk",null,{"direction":"摘下头环，满头大汗","speaker":"瑞宝"}],["dingding","你的拍子，我包了。穿一辈子。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","那得多少钱。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","包子抵。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","……你这个价钱，果哥知道了要来投资的。","smile",null,{"direction":"笑了","speaker":"瑞宝"}],["nar","蒸笼“嘶”地冒出一大股白汽。包子熟了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"7-5:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]},{"id":"ch8","title":"第八章 · 别断","date":"8.15—8.19","scene":"winter2022","blurb":"线绷得太紧，是会断的。","venue":"homecourt","act":"说出来","stages":[{"id":"8-1","title":"邀请函","scene":"nightmarket","date":"8 月 15 日 · 夜市收摊后","desc":"线绷得太紧，是会断的。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"nightmarket","title":"邀请函","caption":"8 月 15 日 · 夜市收摊后","transition":"feather","intro":true,"uid":"8-1:0"},{"t":"dialog","scene":"nightmarket","lines":[["nar","夜市快收摊了，串灯一盏一盏熄灭。冉冉坐在摊位后面，手里拿着一个烫金信封。丁丁来帮她收东西。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","田楚今天来找我了。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","南岸省青训学院，全额奖学金，打完鹅湾杯就可以去报到。（把信封递给他）他还给我看了我的画像，说我是“高价值”。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","那挺好的。","talk",null,{"direction":"没接","speaker":"丁丁"}],["ranran","你觉得我该去吗？","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","你想去就去。挺好的。","think",null,{"direction":"","speaker":"丁丁"}],["nar","冉冉看着他。串灯又灭了一盏。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","……我问的不是这个。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","那你问的是什么？","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","你自己想。","think",null,{"direction":"站起来，把信封收进包里","speaker":"冉冉"}],["nar","冉冉走了。走出几步，又回过头。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","丁丁，你知道吗？田楚给我看画像的时候，我其实挺生气的。不是因为他读了我，是因为他说，我想去当职业选手。（停顿）他说的可能是对的。可我想听我自己说，不想听一个机器替我说。","think",null,{"direction":"","speaker":"冉冉"}],["nar","冉冉走远了。瑞宝从对面阴影里走出来，叹了口气。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","……你又来了。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","我说错了吗？","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","你没说错。你是什么都没说。","talk",null,{"direction":"","speaker":"瑞宝"}]],"when":null,"uid":"8-1:1"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"8-2","title":"半决赛·上","scene":"league","date":"8 月 17 日 · 鹅湾杯半决赛","desc":"★赢下比赛 ★用“把网借我一下”压下苗苗的扣杀 2 次","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"半决赛·上","caption":"8 月 17 日 · 鹅湾杯半决赛","transition":"feather","intro":true,"uid":"8-2:0"},{"t":"dialog","scene":"league","lines":[["nar","网前的蝴蝶结对上后场的大鹅。冉冉站在网前，丝带在她身边飘；苗苗站在底线，像一座山。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["miaomiao","……我不想赢你。","think",null,{"direction":"","speaker":"苗苗"}],["ranran","那就别赢。","talk",null,{"direction":"","speaker":"冉冉"}],["miaomiao","可是我停不下来。我一停，就不稳了。","talk",null,{"direction":"","speaker":"苗苗"}],["ranran","不稳又怎么样？","talk",null,{"direction":"","speaker":"冉冉"}]],"when":null,"uid":"8-2:1"},{"t":"match","as":"ranran","opp":"miaomiao","field":"league","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"prediction":6,"stable":true,"uid":"8-2:2"},{"t":"dialog","scene":"league","lines":[["nar","大屏：预测被打破。苗苗站在原地，深吸一口气，然后走到网前，伸出手。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["miaomiao","你的网前……像糖。黏住了就甩不掉。","talk",null,{"direction":"","speaker":"苗苗"}],["ranran","谢谢？","talk",null,{"direction":"","speaker":"冉冉"}],["miaomiao","南岸那边……会把你读成一个数字。我就是。（停顿）我是“失误率 0.3%”。读了六年，我都快忘了我叫什么了。","talk",null,{"direction":"握着她的手，低声","speaker":"苗苗"}]],"when":{"outcome":true},"uid":"8-2:3"},{"t":"dialog","scene":"league","lines":[["nar","苗苗赢了，却没有笑。她走到网前，握住冉冉的手。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["miaomiao","南岸那边……会把你读成一个数字。我就是。（停顿）我是“失误率 0.3%”。","talk",null,{"direction":"低声","speaker":"苗苗"}]],"when":{"outcome":false},"uid":"8-2:4"},{"t":"dialog","scene":"league","lines":[["nar","冉冉回到观众席。丁丁想说什么，嘴张开又闭上了。冉冉看了他一眼，坐到了星星旁边。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"8-2:5"}],"rewards":{"cards":[],"chars":["miaomiao"],"gear":[]},"feather":"miaomiao"},{"id":"8-3","title":"半决赛·下","scene":"league","date":"8 月 17 日 · 鹅湾杯半决赛","desc":"★赢下比赛 ★让果哥破产一次（金币 ≤0）","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"半决赛·下","caption":"8 月 17 日 · 鹅湾杯半决赛","transition":"feather","intro":true,"uid":"8-3:0"},{"t":"dialog","scene":"league","lines":[["nar","果哥穿着一身南岸的蓝白队服走进羽场，队服紧得像要爆开。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","果哥，你怎么……","talk",null,{"direction":"","speaker":"丁丁"}],["guoge","南岸给的外援合同！一场三百包——不是，三百块！（压低声音）我跟你说，我两边都押了。我押我自己赢一百包，押你赢一百包。分散投资。","shy",null,{"direction":"","speaker":"果哥"}],["dingding","那你到底想不想赢？","think",null,{"direction":"","speaker":"丁丁"}],["guoge","……这个问题，我从来没想过。","think",null,{"direction":"","speaker":"果哥"}]],"when":null,"uid":"8-3:1"},{"t":"match","as":"dingding","opp":"guoge","field":"league","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"prediction":29,"uid":"8-3:2"},{"t":"dialog","scene":"league","lines":[["guoge","这是投资！","talk",null,{"direction":"第一次红包雨后","speaker":"果哥"}],["guoge","这是……短期波动！","talk",null,{"direction":"被丁丁打到降档后","speaker":"果哥"}],["guoge","这是……这是人生。","talk",null,{"direction":"破产时","speaker":"果哥"}]],"when":null,"uid":"8-3:3"},{"t":"dialog","scene":"league","lines":[["guoge","我输了，但我押你那一百包赢了。","talk",null,{"direction":"躺在地上，金币归零，装备变回旧木拍和拖鞋","speaker":"果哥"}],["dingding","所以你到底是赚了还是亏了？","talk",null,{"direction":"","speaker":"丁丁"}],["guoge","……持平。（坐起来，看着天花板）我这辈子，就一直持平。","think",null,{"direction":"","speaker":"果哥"}]],"when":{"outcome":true},"uid":"8-3:4"},{"t":"dialog","scene":"league","lines":[["lu","经核实，南岸外援合同不符合本地选手条款。本场成绩作废，丁丁递补进入决赛。","talk"],["guoge","……持平。","think"]],"when":{"outcome":false},"uid":"8-3:5"},{"t":"dialog","scene":"league","lines":[["guoge","我赢了，但我押你那一百包亏了。……持平。我这辈子就一直持平。","talk",null,{"direction":"","speaker":"果哥"}]],"when":{"outcome":false},"uid":"8-3:6"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"8-4","title":"别断","scene":"backroom","date":"8 月 18 日 夜 · 穿线铺后屋 → 读球：2022 年 12 月 18 日，省体育馆","desc":"★断线前领先过对手 ★不用一次扣杀打到 6:6","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"backroom","title":"别断","caption":"8 月 18 日 夜 · 穿线铺后屋 → 读球：2022 年 12 月 18 日，省体育馆","transition":"feather","intro":true,"uid":"8-4:0"},{"t":"dialog","scene":"backroom","lines":[["nar","后屋。丁丁坐在工作台前，抽屉开着。两只球并排躺着。他拿起沧澜给的那只。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-drawer"}],["ruibao","……你确定？明天就是决赛了。","talk",null,{"direction":"","speaker":"瑞宝","cg":"cg-drawer"}],["dingding","就是因为明天是决赛。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-drawer"}],["nar","球放进蒸笼。白光。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false,"cg":"cg-drawer"}]],"when":null,"uid":"8-4:1"},{"t":"dialog","scene":"winter2022","lines":[["nar","羽场里，2022 年冬天的省体育馆。很冷，看台上的观众都裹着棉衣，呼出的气是白的。十八岁的田楚站在场上，手里握着一支拍子。拍子的拍柄上，用记号笔歪歪扭扭写着：“师兄必胜”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","……那是你写的。","talk",null,{"direction":"天上的声音","speaker":"瑞宝"}],["dingding","……是我写的。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","先放一段赛前回忆。体育馆走廊，十四岁的丁丁捧着拍子跑过来，脸冻得通红，眼睛亮晶晶的。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","师兄！拍子我穿好了！我给你拉了三十磅！比你平时紧，职业选手都这么拉！","talk",null,{"direction":"","speaker":"小丁丁"}],["nar","少年田楚（接过拍子，捏了捏拍面，手指停在拍颈附近一根线上。那根线上有一道很浅的压痕，是穿线机夹头夹得太紧留下的。他的眉头皱了一下。）","stage",null,{}],["nar","三十磅……太紧了","intent",null,{"title":"球记得的念头"}],["nar","这根线有伤","intent",null,{"title":"球记得的念头"}],["nar","他低头看着小丁丁。小丁丁的右手食指上缠着一圈创可贴，渗着血。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","手怎么了？","talk",null,{"direction":"","speaker":"少年田楚"}],["dingding","拉线的时候线弹回来了！没事！不疼！","talk",null,{"direction":"","speaker":"小丁丁"}],["nar","他拉了一早上","intent",null,{"title":"球记得的念头"}],["nar","少年田楚看着他，很久。然后笑了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","……好。谢谢师弟。","talk",null,{"direction":"","speaker":"少年田楚"}]],"when":null,"uid":"8-4:2"},{"t":"match","as":"tianchu","opp":"provincial","field":"memory","level":"normal","target":7,"cap":7,"allowLoss":true,"stars":[],"skills":false,"age":[18,18],"durability":true,"startScore":[4,4],"intentSide":0,"intents":["别断","别断","别杀了，吊","别断，他那么高兴","……就这一拍"],"venue":"wintercourt","uid":"8-4:3"},{"t":"dialog","scene":"winter2022","lines":[["nar","比赛开始。 玩家操控十八岁的田楚。每一次扣杀，拍线都发出细微的“吱”声，耐久条往下掉一截。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","别断","intent",null,{"title":"球记得的念头"}],["nar","别断","intent",null,{"title":"球记得的念头"}],["nar","别杀了，吊","intent",null,{"title":"球记得的念头"}],["nar","别断，他那么高兴","intent",null,{"title":"球记得的念头"}],["nar","田楚起跳，这是他今晚第一次全力扣杀。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","……就这一拍","intent",null,{"title":"球记得的念头"}],["nar","“啪——”","stage","snap",{"silent":false,"cue":"snap","white":false,"black":false}]],"when":null,"uid":"8-4:4"},{"t":"dialog","scene":"winter2022","lines":[["nar","一根线断了，接着整片拍面像花一样炸开。球软软地飞出去，落在网前，没过网。","stage","snap",{"silent":true,"cue":"snap","white":false,"black":false,"cg":"cg-break"}],["nar","全场寂静。","stage",null,{"silent":true,"cue":null,"white":false,"black":false,"cg":"cg-break"}],["nar","赛后。更衣室门口，十四岁的丁丁哭得喘不上气。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-break"}],["dingding","师兄……是不是、是不是我拉坏的……","talk",null,{"direction":"","speaker":"小丁丁","cg":"cg-break"}],["nar","少年田楚蹲下来，看着他。很久。他把那支炸开的拍子用毛巾包好，夹在胳膊下面。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-break"}],["tianchu","不是。","talk",null,{"direction":"","speaker":"少年田楚","cg":"cg-break"}],["tianchu","我早上自己又调过。是我的问题。","talk",null,{"direction":"","speaker":"少年田楚","cg":"cg-break"}],["dingding","……真的吗？","talk",null,{"direction":"抽泣","speaker":"小丁丁","cg":"cg-break"}],["tianchu","真的。别哭了。","sad",null,{"direction":"","speaker":"少年田楚","cg":"cg-break"}],["nar","小丁丁擦干眼泪，点点头，被大人领走了。少年田楚一个人站在走廊里。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-break"}],["nar","……","intent",null,{"title":"球记得的念头","cg":"cg-break"}],["nar","那一行意图，是空的。一个字都没有。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-break"}],["nar","记忆显影完成。丁丁摘下头环，坐在黑暗里，一动不动。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-break"}],["ruibao","……丁丁。","talk",null,{"direction":"很轻","speaker":"瑞宝","cg":"cg-break"}],["dingding","这道疤……我说是小时候穿线勒的。","think",null,{"direction":"看着自己的食指","speaker":"丁丁","cg":"cg-break"}],["dingding","就是那天早上。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-break"}],["nar","丁丁趴在工作台上，肩膀开始发抖。没有声音。瑞宝坐在他旁边，什么都没说，把手放在他背上。蒸笼里的白光一点一点暗下去。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false,"cg":"cg-break"}]],"when":null,"uid":"8-4:5"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"8-5","title":"河边","scene":"ferry-night","date":"8 月 19 日 凌晨 · 江边码头","desc":"线绷得太紧，是会断的。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"ferry-night","title":"河边","caption":"8 月 19 日 凌晨 · 江边码头","transition":"feather","intro":true,"uid":"8-5:0"},{"t":"dialog","scene":"ferry-night","lines":[["nar","田楚的黑色轿车停在码头。他靠着车门抽烟，看着江面。丁丁跑过来，在他面前站住，喘着气。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","……我读了那只球。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","田楚的手停了一下。他没有转身。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","是我拉坏的。三十磅，夹头夹伤了线。你知道。你那天早上就知道。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","……","talk",null,{"direction":"","speaker":"田楚"}],["dingding","你为什么要说是你自己调的？","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","你那天手上在流血。","think",null,{"direction":"终于转过身，看着他。脸上没有表情","speaker":"田楚"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","你捧着那支拍子跑过来，就像捧着全世界最好的东西。我说不出口。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","对不起。师兄，对不起——","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","你哭了一晚上，第二天就好了。","sad",null,{"direction":"打断他","speaker":"田楚"}],["nar","丁丁愣住了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","我呢？","talk",null,{"direction":"","speaker":"田楚"}],["tianchu","省队名额没了。朱老师看我的眼神变了，所有人都觉得我是那种关键时刻掉链子的人。第二年我就走了，因为我在鹅湾待不下去。（声音还是很平静，但手里的烟在抖）而你，你什么都不知道。你就在你家铺子里穿线，穿了四年，以为那只是运气不好。","talk",null,{"direction":"","speaker":"田楚"}],["tianchu","我替你扛了，然后恨了你四年。你知道这有多累吗？","talk",null,{"direction":"","speaker":"田楚"}],["dingding","……专利上，为什么写我的名字？","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","……我不想一个人当坏人。","think",null,{"direction":"沉默了很久，把烟扔进江里","speaker":"田楚"}],["nar","江面上起了雾。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","决赛见。（拉开车门，停了一下）别让我赢得太容易。","talk",null,{"direction":"","speaker":"田楚"}],["nar","车开走了。丁丁一个人站在码头上，天边慢慢亮起来。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"8-5:1"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]},{"id":"ch9","title":"第九章 · 球落地之前","date":"8.20","scene":"league","blurb":"十六根羽毛，十四个记号。最后一分，自己去接。","venue":"homecourt","act":"说出来","stages":[{"id":"9-1","title":"十四根","scene":"stringing","date":"8 月 20 日 清晨 · 穿线铺","desc":"十六根羽毛，十四个记号。最后一分，自己去接。","knowledge":["v3_24"],"kind":"loadout","steps":[{"t":"cinema","scene":"stringing","title":"十四根","caption":"8 月 20 日 清晨 · 穿线铺","transition":"ink","intro":true,"uid":"9-1:0"},{"t":"dialog","scene":"stringing","lines":[["nar","天刚亮。丁丁坐在工作台前，面前摆着苗苗给的那一束羽毛、一个软木球头、一卷细线、一小瓶胶。他已经插好了十六根羽毛，正在一圈一圈地缠线。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","门口的风铃响了。瑞宝第一个进来，手里拿着一支记号笔。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","听说你在做球。","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","……你听谁说的。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","猴子直播了。","talk",null,{"direction":"","speaker":"瑞宝"}],["houzi","七个家人都知道了。","talk",null,{"direction":"跟在后面","speaker":"猴子"}],["nar","一个接一个，所有人都来了。每个人接过记号笔，在一根羽毛的根部画一个小小的记号。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","瑞宝：一个包子","stage",null,{}],["nar","猴子：一个猴头","stage",null,{}],["nar","波波：一只小恐龙","stage",null,{}],["nar","小红：一个直角","stage",null,{}],["nar","星星：一颗星","stage",null,{}],["nar","朱老师：一只哨子","stage",null,{}],["nar","沧澜：一滴水","stage",null,{}],["nar","凌风：一个脚印","stage",null,{}],["nar","路先森：</>","stage",null,{}],["nar","老陈：一个勾 ✓","stage",null,{}],["nar","果哥：一个 ¥（“投资”）","stage",null,{}],["nar","苗苗：一只鹅（大将军在门口叫了一声）","stage",null,{}],["nar","最后进来的是冉冉。她接过笔，在一根羽毛上画了一个小小的蝴蝶结。然后她拿起丁丁放在旁边的球拍，在拍柄上系了一根红色的丝带，打了一个结。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","……高一那次，也是这么系的。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……我知道。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","加油。（停顿）邀请函的事，我还没决定。等你打完再说。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","十三根羽毛有了记号。还剩三根空着。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["xiaohong","还有三根。","talk",null,{"direction":"","speaker":"小红"}],["dingding","……一根是我的。还有两根，留着。","talk",null,{"direction":"","speaker":"丁丁"}],["ruibao","留给谁？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","不知道。等球自己知道吧。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","丁丁拿起做好的球，走到门口，对着江的方向，用标准的测球姿势从下往上大力一击。球高高飞出去，落在街对面包子铺门口的台阶前。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","速度刚好。","think",null,{"direction":"看着落点，点头","speaker":"朱老师"}]],"when":null,"uid":"9-1:1"},{"t":"card","card":"v3_24","uid":"9-1:2"},{"t":"dialog","scene":"stringing","lines":[["nar","决赛前最后一次配装。根据对手选：","lesson",null,{"title":"教学·器械库（完整）"}],["nar","- 田楚擅长骗术，控球和移动比力量更重要；","lesson",null,{"title":"教学·器械库（完整）"}],["nar","- 磅数推荐 24 磅，甜区更大、更宽容；","lesson",null,{"title":"教学·器械库（完整）"}],["nar","- 两个主动技能，建议带伸缩长拍 + 悠悠球拍（长拍直接拦截，悠悠接回后自己选择下一拍）。","lesson",null,{"title":"教学·器械库（完整）"}]],"when":null,"uid":"9-1:3"},{"t":"loadout","as":"dingding","title":"最后一次配装","recommend":["shensuo","youyou"],"uid":"9-1:4"},{"t":"minigame","game":"stringing","title":"别绷得太紧","tension":24,"rounds":2,"uid":"9-1:5"},{"t":"dialog","scene":"stringing","lines":[["dingding","……二十四。","talk",null,{"direction":"给自己的球拍拉线，指针停在 24","speaker":"丁丁"}],["ruibao","不拉高一点？","talk",null,{"direction":"","speaker":"瑞宝"}],["dingding","不了。绷太紧，会断。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"9-1:6"}],"rewards":{"cards":["v3_24"],"chars":[],"gear":["r_star"],"feats":["tension"]},"feather":null},{"id":"9-2","title":"决赛·第一局","scene":"league","date":"8 月 20 日 · 鹅湾杯决赛","desc":"本局输赢都会进入 9-3。★赢下本局 ★识破镜花水月 3 次","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"决赛·第一局","caption":"8 月 20 日 · 鹅湾杯决赛","transition":"ink","intro":true,"uid":"9-2:0"},{"t":"dialog","scene":"league","lines":[["nar","体育中心爆满，过道上都站着人。瑞妈搬着蒸笼来了，王爸也来了，坐着轮椅，腿上盖着毯子，手里举着手机，屏幕上是猴子的直播间。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","老王包子：稳住","stage",null,{}],["nar","南岸的胜率大屏上，两个数字大得刺眼：99% ： 1%。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","羽场里。田楚站在对面，身后的影子比任何一次都浓。他手里握着丁丁上个月给他穿的那支拍子，二十六磅。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","师弟。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","师兄。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","她在第三排。你要看就看。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","……我知道她在哪。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":null,"uid":"9-2:1"},{"t":"match","as":"dingding","opp":"tianchu","field":"league","level":"hard","target":7,"cap":11,"allowLoss":true,"stars":[],"prediction":1,"uid":"9-2:2"},{"t":"dialog","scene":"league","lines":[["tianchu","三只球。你知道哪只是真的吗？","talk",null,{"direction":"局中，镜花水月之后","speaker":"田楚"}],["tianchu","我骗了你四年。你还没习惯？","talk",null,{"direction":"这一拍，没打之后","speaker":"田楚"}],["tianchu","你看到的，是你想看的。","think",null,{"direction":"水中月之后","speaker":"田楚"}]],"when":null,"uid":"9-2:3"},{"t":"dialog","scene":"league","lines":[["nar","大屏数字抖了一下：97% ： 3%。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","……你变了。","talk",null,{"direction":"局间，擦着汗","speaker":"田楚"}]],"when":{"outcome":true},"uid":"9-2:4"},{"t":"dialog","scene":"league","lines":[["nar","大屏：99.6% ： 0.4%。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","还有一局。（停顿）你还可以认输。","talk",null,{"direction":"","speaker":"田楚"}]],"when":{"outcome":false},"uid":"9-2:5"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"9-3","title":"局间","scene":"locker","date":"决赛局间","desc":"十六根羽毛，十四个记号。最后一分，自己去接。","knowledge":["v3_05"],"kind":"special","steps":[{"t":"cinema","scene":"locker","title":"局间","caption":"决赛局间","transition":"ink","intro":true,"uid":"9-3:0"},{"t":"dialog","scene":"locker","lines":[["nar","丁丁坐在场边，满头大汗，手在抖。朱老师从观众席走下来，在他旁边坐下，拧开保温杯，倒了一杯盖的枸杞水给他。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","喝。","talk",null,{"direction":"","speaker":"朱老师"}],["dingding","……朱老师，我看不出来哪只是真的。","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","你一直在看他的拍子。","talk",null,{"direction":"","speaker":"朱老师"}],["dingding","不看拍子看什么？","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","他骗你的不是球，是你的眼睛。你看他的拍子，他就让你看见拍子。（停顿）你别看他的拍子。你看他……想不想赢。","think",null,{"direction":"","speaker":"朱老师"}],["dingding","……什么意思？","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","一个人真想赢的时候，肩膀是松的。他骗你的那几拍，肩膀都是紧的。（喝了一口枸杞水）三十年，我就看懂了这一件事。","think",null,{"direction":"","speaker":"朱老师"}],["nar","朱老师站起来走了。丁丁抬起头，冉冉站在场边围栏外面。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","你刚才往我这边看了好多次。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……对不起。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","别对不起。看就看。（伸手指了指场上）但球在那边。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","丁丁看着她。她的手指着球场，眼睛却在看他。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","打完了，我有话问你。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……什么话？","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","打完了再说。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","场边的南岸控制台。路先森盯着屏幕，屏幕上丁丁的预测曲线乱成一团。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["laochen","你喂脏数据了？","talk",null,{"direction":"","speaker":"老陈"}],["lu","没有。（声音有点发愣）这次不是我。是他自己打得……没有模型。","surprise",null,{"direction":"","speaker":"路先森"}]],"when":null,"uid":"9-3:1"}],"rewards":{"cards":["v3_05"],"chars":[],"gear":[]},"feather":null},{"id":"9-4","title":"决赛·决胜","scene":"league","date":"鹅湾杯决赛第二局（若第一局丁丁赢，则这一局为决胜局）","desc":"★不被残影骗到 ★最后一分用悠悠球拍或伸缩长拍得分","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"league","title":"决赛·决胜","caption":"鹅湾杯决赛第二局（若第一局丁丁赢，则这一局为决胜局）","transition":"ink","intro":true,"uid":"9-4:0"},{"t":"dialog","scene":"league","lines":[["nar","丁丁重新走进羽场。这一次，他没有看田楚的拍子。他看着田楚的肩膀。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"9-4:1"},{"t":"match","as":"dingding","opp":"tianchu","field":"league","level":"nightmare","target":7,"cap":11,"allowLoss":false,"stars":[],"prediction":0.4,"shoulder":true,"uid":"9-4:2"},{"t":"dialog","scene":"league","lines":[["tianchu","……","talk",null,{"direction":"第一次被识破镜花水月","speaker":"田楚"}],["tianchu","谁教你的？","talk",null,{"direction":"第二次","speaker":"田楚"}],["dingding","朱老师。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","……他从来没教过我这个。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","他说他三十年才看懂。你走得太早了。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","比分来到 6:6，决胜分。田楚起跳，用尽全力打出镜花水月，三只球分成三条线。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","丁丁没有看球。他看着田楚的肩膀。左边是紧的，右边是紧的，中间是松的。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","他伸出长拍。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"9-4:3"},{"t":"dialog","scene":"league","lines":[["nar","慢镜头：伸缩长拍伸出去，拍头碰到球，球擦着网带翻过去。拍柄上那根红丝带，在羽场里化成了一只小小的粉色蝴蝶结，停在网带上，轻轻托了球一下。球落下。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-ribbon"}],["nar","落地。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-ribbon"}],["nar","大屏：预测被打破。数字跳成一片乱码，然后熄灭。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-ribbon"}],["nar","全场安静了一秒，然后整个体育馆炸开了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-ribbon"}],["houzi","家人们——！！！","talk",null,{"direction":"直播间，破音","speaker":"猴子","cg":"cg-ribbon"}],["nar","老王包子：稳住了！！！！！","stage",null,{"cg":"cg-ribbon"}],["nar","羽场里，丁丁站在原地，举起了左手。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-ribbon"}],["dingding","……对不起。擦网了。","talk",null,{"direction":"","speaker":"丁丁","cg":"cg-ribbon"}],["nar","田楚愣愣地看着他。然后，他笑了出来，是这一整个夏天第一次真的笑。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-ribbon"}],["tianchu","……你连这个都学。","talk",null,{"direction":"","speaker":"田楚","cg":"cg-ribbon"}]],"when":null,"uid":"9-4:4"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"9-5","title":"二十四磅","scene":"locker","date":"决赛后 · 体育中心选手休息室","desc":"十六根羽毛，十四个记号。最后一分，自己去接。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"locker","title":"二十四磅","caption":"决赛后 · 体育中心选手休息室","transition":"ink","intro":true,"uid":"9-5:0"},{"t":"dialog","scene":"locker","lines":[["nar","休息室里只有田楚一个人。他坐在长椅上，看着自己的手。门开了，丁丁走进来，怀里抱着一个用旧毛巾包着的东西。","stage","door",{"silent":false,"cue":"door","white":false,"black":false}],["tianchu","……来炫耀？","talk",null,{"direction":"","speaker":"田楚"}],["nar","丁丁把毛巾打开。里面是那支 2022 年断掉的旧拍子，拍柄上还写着“师兄必胜”。它重新穿好了线，崭新、整齐。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","……你从哪儿拿的？","think",null,{"direction":"看着那支拍子，很久说不出话","speaker":"田楚"}],["dingding","沧澜姐帮我从你后备箱里拿的。她说你车门从来不锁。","talk",null,{"direction":"","speaker":"丁丁"}],["dingding","师兄。这次是二十四磅。我检查了三遍。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","……我打二十六。","talk",null,{"direction":"接过拍子，捏了捏拍面","speaker":"田楚"}],["dingding","我知道。（停顿）二十四。你今年绷得太紧了。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","田楚低头看着拍子，肩膀抖了一下，像是要笑，又像是别的什么。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","我不是原谅你。","talk",null,{"direction":"","speaker":"田楚"}],["dingding","我知道。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","我只是……（停了很久）不想再恨了。太累。","think",null,{"direction":"","speaker":"田楚"}],["nar","田楚从口袋里掏出一支笔。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","你那只球，还剩几根空的？","talk",null,{"direction":"","speaker":"田楚"}],["dingding","……三根。","talk",null,{"direction":"","speaker":"丁丁"}],["tianchu","给我一根。","talk",null,{"direction":"","speaker":"田楚"}],["nar","丁丁把球递过去。田楚在一根羽毛的根部画了一个很小的符号：一道波纹，波纹下面是一个倒过来的月亮，是水里的月亮。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","第十四根。","talk",null,{"direction":"","speaker":"田楚"}],["nar","门外传来一个声音，低沉，很短。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","？？？：田楚。","stage",null,{}],["nar","田楚的背一下子挺直了。门口站着一个头发花白、穿深色夹克的男人，个子不高，眼神很静。他身后站着苗苗。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","回车上。","talk",null,{"direction":"","speaker":"老南"}],["tianchu","……是。","talk",null,{"direction":"站起来，抱着那支拍子","speaker":"田楚"}],["nar","老南没有看丁丁。他转过身，视线越过走廊，落在走廊尽头。朱老师站在那里，保温杯握在手里。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","两个老人隔着一整条走廊，看着对方。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","朱启明。","talk",null,{"direction":"","speaker":"老南"}],["zhu","……南振。","talk",null,{"direction":"","speaker":"朱老师"}],["nan","三十年。","talk",null,{"direction":"","speaker":"老南"}],["nan","打完它。","talk",null,{"direction":"","speaker":"老南"}]],"when":null,"uid":"9-5:1"}],"rewards":{"cards":[],"chars":["tianchu"],"gear":[]},"feather":"tianchu"}]},{"id":"ch10","title":"第十章 · 没有运气的人","date":"8.22—8.25","scene":"jarroom","blurb":"三十年。他读过所有人的球，唯独没有读过自己的。","venue":"homecourt","act":"说出来","stages":[{"id":"10-1","title":"一九九六","scene":"oldgym","date":"8 月 22 日 · 镇一中老体育馆","desc":"三十年。他读过所有人的球，唯独没有读过自己的。","knowledge":["v3_23"],"kind":"special","steps":[{"t":"cinema","scene":"oldgym","title":"一九九六","caption":"8 月 22 日 · 镇一中老体育馆","transition":"feather","intro":true,"uid":"10-1:0"},{"t":"dialog","scene":"oldgym","lines":[["nar","周六课的时间，但今天没有小孩。朱老师坐在场边的长椅上，大家围着他。他从抽屉里拿出那个扣着的相框，第一次翻过来。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","照片上，三十岁的朱启明举着奖杯，笑得很拘谨。他身后，球网另一边，一个年轻男人低着头，背影很直。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","1996 年，省赛男单决赛。对面那个，叫南振。","talk",null,{"direction":"","speaker":"朱老师"}],["bobo","1996……中华龙鸟也是 1996 年。","talk",null,{"direction":"小声","speaker":"波波"}],["zhu","那时候的规矩跟现在不一样。一局十五分，只有发球的一方能得分。（停顿）决胜局，他一度十三比四领先我。","talk",null,{"direction":"","speaker":"朱老师"}],["lingfeng","十三比四？！那您怎么赢的？","surprise",null,{"direction":"","speaker":"凌风"}],["zhu","我也不知道。他突然就……打得很小心。一分一分，被我追了回来。","talk",null,{"direction":"","speaker":"朱老师"}],["zhu","最后一个球，是我发球。球擦着网带过去，掉进了他的发球区。他没动。","talk",null,{"direction":"","speaker":"朱老师"}],["xiaohong","擦网发球，在羽毛球里是有效的。","talk",null,{"direction":"","speaker":"小红"}],["zhu","有效。裁判判了有效。（停顿）但南振说，我那个发球违例了：拍框高过了握拍的手。","talk",null,{"direction":"","speaker":"朱老师"}],["ranran","……那您违例了吗？","talk",null,{"direction":"","speaker":"冉冉"}],["nar","长久的沉默。体育馆的窗户很高，浮尘在光里慢慢转。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","……我不知道。","talk",null,{"direction":"","speaker":"朱老师"}],["zhu","发球的那一刻，我觉得手好像高了一点点。只有一点点。可裁判没判，球进了，大家都在鼓掌。我就……举起了奖杯。","talk",null,{"direction":"","speaker":"朱老师"}],["zhu","后来他找过我很多次。我每次都说“裁判判了有效”。（看着自己的手）我从来没敢想清楚，那一下到底高没高。","think",null,{"direction":"","speaker":"朱老师"}],["zhu","从那以后，我每次擦网得分，都会举手说对不起。","talk",null,{"direction":"","speaker":"朱老师"}]],"when":null,"uid":"10-1:1"},{"t":"card","card":"v3_23","uid":"10-1:2"},{"t":"dialog","scene":"oldgym","lines":[["dingding","……那只球呢？","talk",null,{"direction":"","speaker":"丁丁"}],["miaomiao","在罐子屋。","talk",null,{"direction":"站在门口，不知道什么时候来的","speaker":"苗苗"}],["nar","所有人回头。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["miaomiao","他留着。三十年了。我小时候问过他，罐子里是什么。他说：“是我输掉的那一分。”（停顿）他一次都没开过。","talk",null,{"direction":"","speaker":"苗苗"}],["bobo","真空密封，三十年……它还能读。像琥珀。","talk",null,{"direction":"站起来，声音有点抖","speaker":"波波"}]],"when":null,"uid":"10-1:3"}],"rewards":{"cards":["v3_23"],"chars":[],"gear":[]},"feather":null},{"id":"10-2","title":"罐子屋","scene":"jarroom","date":"8 月 23 日 夜 · 南岸体育总部","desc":"★找到 1996 年的那一罐 ★找到每个伙伴自己的罐子并看一眼标签","knowledge":[],"kind":"inspect","steps":[{"t":"cinema","scene":"jarroom","title":"罐子屋","caption":"8 月 23 日 夜 · 南岸体育总部","transition":"feather","intro":true,"uid":"10-2:0"},{"t":"dialog","scene":"jarroom","lines":[["nar","南岸大楼顶层。苗苗刷卡，推开一扇厚重的门。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","门后是一个巨大的圆形房间，墙壁从地板到天花板都是架子，架子上整整齐齐摆满了玻璃罐。几千个，也许几万个。每个罐子里装着一只羽毛球，贴着标签。灯光从顶上照下来，像一座玻璃做的森林。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["houzi","……我的天。","talk",null,{"direction":"","speaker":"猴子"}],["bobo","这里是一个化石库。","talk",null,{"direction":"声音很轻","speaker":"波波"}]],"when":null,"uid":"10-2:1"},{"t":"inspect","scene":"jarroom","title":"玻璃做的森林","items":[{"id":"jar-ranran","label":"冉冉 #0207","text":"高价值。冉冉看了一眼，转身走开。","clue":"jar-ranran","x":0.17,"y":0.28},{"id":"jar-lingfeng","label":"凌风 #0412","text":"待观察。凌风：……老陈哥改的。老陈：嗯。","clue":"jar-lingfeng","x":0.48,"y":0.28},{"id":"jar-miaomiao","label":"苗苗 #0001—#3650","text":"整整一面墙。她十二岁到现在的每一场。","clue":"jar-miaomiao","x":0.79,"y":0.28},{"id":"jar-tianchu","label":"田楚 #0002","text":"只有一个罐子。标签手写着：和师弟。","clue":"jar-tianchu","x":0.17,"y":0.5},{"id":"jar-nan","label":"1996.8.25 · 最后一球","text":"灰尘覆盖着底座。真空封条完好，三十年没有被打开。","clue":"jar-nan","x":0.48,"y":0.5}],"uid":"10-2:2"},{"t":"dialog","scene":"jarroom","lines":[["nar","“冉冉 #0207 · 高价值” —— 冉冉看了一眼，转身走开。","stage",null,{}],["nar","“凌风 #0412 · 待观察” —— 凌风：“……老陈哥改的。”老陈：“嗯。”","stage",null,{}],["nar","“苗苗 #0001-#3650” —— 整整一面墙。苗苗站在那面墙前面，很久没动。“……我十二岁到现在的每一场。”","stage",null,{}],["nar","“田楚 #0002” —— 只有一个罐子，里面的球很旧，就是 5-4 里那只。旁边的标签手写着：“和师弟”。","stage",null,{}],["nar","“南振 · 1996.8.25 · 决赛 · 最后一球” —— 房间正中间，单独一个底座，罐子上落了一层灰。罐口的封条完好无损。","stage",null,{}],["nar","丁丁走到底座前。罐子里的球很旧了，羽毛发黄，但每一根都还在。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","别碰它。","talk",null,{"direction":"声音从背后传来","speaker":"老南"}],["nar","所有人转身。老南站在门口，身后是田楚。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"10-2:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"10-3","title":"老南","scene":"jarroom","date":"8 月 23 日 夜 · 罐子屋","desc":"三十年。他读过所有人的球，唯独没有读过自己的。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"jarroom","title":"老南","caption":"8 月 23 日 夜 · 罐子屋","transition":"feather","intro":true,"uid":"10-3:0"},{"t":"dialog","scene":"jarroom","lines":[["nan","苗苗。","talk",null,{"direction":"","speaker":"老南"}],["miaomiao","……是我带他们来的。","talk",null,{"direction":"","speaker":"苗苗"}],["nan","嗯。","talk",null,{"direction":"看了她一眼，没有生气，只是很慢地眨了一下眼睛","speaker":"老南"}],["nar","老南走进房间，经过一排排玻璃罐，像走过自己的一生。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","我这辈子只输过一次。输给一个没有人看见的错误。","talk",null,{"direction":"","speaker":"老南"}],["nan","从那天起我就想，这世上，不该有看不见的东西。","think",null,{"direction":"","speaker":"老南"}],["nan","所以我做了鹰眼，做了读羽，做了画像，做了胜率。现在，球场上再也不会有“没人看见”的球了。","talk",null,{"direction":"","speaker":"老南"}],["dingding","可你看见的，不是球。是人心里想的东西。","think",null,{"direction":"","speaker":"丁丁"}],["nan","有什么区别？","talk",null,{"direction":"","speaker":"老南"}],["dingding","……有区别。（停顿）球是打出去的。心里想的，是人自己的。","think",null,{"direction":"","speaker":"丁丁"}],["nan","你也读过别人的球。","think",null,{"direction":"看着他","speaker":"老南"}],["dingding","读过。都是他们自己给我的。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","老南沉默了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","那你们想怎么样？","think",null,{"direction":"","speaker":"老南"}],["dingding","我们想打开那个罐子。","think",null,{"direction":"","speaker":"丁丁"}],["nar","房间里一下子很安静。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","……打一场。你们赢了，罐子给你们开。南岸以后只读落点，不读人。","talk",null,{"direction":"","speaker":"老南"}],["nan","你们输了，读羽全省推行。（看着丁丁）专利上有你的名字，你签字转让。","think",null,{"direction":"","speaker":"老南"}],["tianchu","老板——","talk",null,{"direction":"在他身后，第一次开口","speaker":"田楚"}],["nan","你们可以一起上。几个人都行。（停顿）我一个人。","talk",null,{"direction":"","speaker":"老南"}],["miaomiao","我也打。","talk",null,{"direction":"往前走了一步，站到了丁丁这一边","speaker":"苗苗"}],["nar","老南看着苗苗。这是他第一次露出类似“疼”的表情，只有一瞬间。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","……好。","talk",null,{"direction":"","speaker":"老南"}]],"when":null,"uid":"10-3:1"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"10-4","title":"十六根羽毛","scene":"oldgym","date":"8 月 25 日（1996 年决赛整整三十年后）· 镇一中老体育馆，南岸临时搭建的羽场舱","desc":"★至少 6 名角色上场并各得 1 分 ★田楚那一分得分","knowledge":[],"kind":"relay","steps":[{"t":"cinema","scene":"oldgym","title":"十六根羽毛","caption":"8 月 25 日（1996 年决赛整整三十年后）· 镇一中老体育馆，南岸临时搭建的羽场舱","transition":"feather","intro":true,"uid":"10-4:0"},{"t":"dialog","scene":"oldgym","lines":[["nar","老体育馆。三十年前，就是在这里，朱启明发出了那个球。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","丁丁走到网前，把手工做的那只球递给裁判（路先森临时客串）。十六根羽毛，十四根有记号，两根空着。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","测球。","talk",null,{"direction":"","speaker":"老南"}],["nar","老南拿起那只球，看了一眼羽毛上的记号，走到底线，用标准的测球姿势打了一下。球飞过去，落在规定的区域里。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","……速度合格。","talk",null,{"direction":"","speaker":"老南"}],["nar","他看了一眼那两根空着的羽毛，没说什么。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","开始吧。","talk",null,{"direction":"","speaker":"老南"}]],"when":null,"uid":"10-4:1"},{"t":"relay","as":"dingding","opp":"nan","field":"league","level":"nightmare","target":7,"cap":11,"prediction":0,"allowLoss":false,"title":"排好棒次，最后一棒是丁丁","uid":"10-4:2"},{"t":"dialog","scene":"oldgym","lines":[["ruibao","“我负责挡着——不是，我负责赢！”","talk",null,{"direction":"","speaker":"瑞宝"}],["houzi","“家人们，最后一场了！”（弹幕：老王包子：稳住）","talk",null,{"direction":"","speaker":"猴子"}],["xiaohong","“我算过了，赢面是零。”（停顿）“所以只能算错了。”","think",null,{"direction":"","speaker":"小红"}],["xingxing","“月亮不怕被看见。”","talk",null,{"direction":"","speaker":"星星"}],["ranran","“网借我一下。”（老南：“……网是公共的。”冉冉：“现在是我的。”）","talk",null,{"direction":"","speaker":"冉冉"}],["canglan","“这一潮，我替大家扛。”","talk",null,{"direction":"","speaker":"沧澜"}],["lingfeng","“扑空了，也算一步！”","think",null,{"direction":"","speaker":"凌风"}],["lu","“模型预测我会输。所以我很开心。”","talk",null,{"direction":"","speaker":"路先森"}],["laochen","“签到表上，你的习惯区是正中间。三十年都是。”","talk",null,{"direction":"","speaker":"老陈"}],["guoge","“全押！小概率！这辈子押一次！”","talk",null,{"direction":"","speaker":"果哥"}],["zhu","（不上场。坐在场边，握着保温杯，一直看着老南的肩膀。）","think",null,{"direction":"","speaker":"朱老师"}],["miaomiao","“……我会失误的。我现在不怕了。”","talk",null,{"direction":"","speaker":"苗苗"}],["nar","当玩家方 5:6 落后时，强制演出。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","田楚从场边站起来，走到丁丁身边。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","让我打一分。","talk",null,{"direction":"","speaker":"田楚"}],["nan","……你？","talk",null,{"direction":"","speaker":"老南"}],["tianchu","您说的，几个人都行。","talk",null,{"direction":"","speaker":"田楚"}],["nar","老南看着他，第一次看不懂一个人。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","操控田楚（这一分）：田楚的三个主动技能全部变灰，只剩普通球路。屏幕提示：“这一分，不用骗。”","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","老南的被动“看得见”自动开启，他提前往假球的位置移动。他在等田楚的镜花水月，三十年来他读了所有人，他读过田楚的每一只球，田楚从不打直球。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","田楚打了一个最普通的直线平高球。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","老南往左边扑，去接那个他“看得见”的假球。真球从右边落地。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","6:6。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","……","think",null,{"direction":"站在原地，看着那个落点","speaker":"老南"}],["tianchu","您看见的，是您想看的。","think",null,{"direction":"","speaker":"田楚"}],["nar","田楚把拍子交给丁丁，走下场。经过丁丁时，他低声说了一句：","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","……最后一分，是你的。","talk",null,{"direction":"","speaker":"田楚"}],["nar","最后一分，丁丁上场。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","胜率大屏：老南 100%。数字没有变。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","这一分很长，非常长。老南复刻了每一个伙伴的技能：月亮、反射板、小猴、冰窗、潮水……一个一个打向丁丁。丁丁一个一个接住。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","拍柄上的红丝带在飘。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","回合进行到第二十七拍时，老南打出“标准答案”，地上亮起丁丁的习惯区。丁丁没有往那里跑。他往冉冉坐的那个方向迈了一步，这是他一整个夏天都在做、却从来不承认的事。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","这一步，不在任何模型里。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","丁丁甩出悠悠球拍，拍头飞出去，又绕回来。拍头接住球，收回拍前。丁丁亲手送出下一拍，球越过网，落在老南够不着的地方。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","落地。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","胜率屏：100% → 99.9% → …… → 黑屏。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","全场寂静。然后，是一声很轻的、像是叹气又像是笑的声音。","stage",null,{"silent":true,"cue":null,"white":false,"black":false}],["nar","是老南。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","……原来是这样。","talk",null,{"direction":"","speaker":"老南"}]],"when":null,"uid":"10-4:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"10-5","title":"最后一球","scene":"oldgym","date":"8 月 25 日 夜 · 老体育馆 → 读球：1996 年 8 月 25 日，省体育馆","desc":"三十年。他读过所有人的球，唯独没有读过自己的。","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"oldgym","title":"最后一球","caption":"8 月 25 日 夜 · 老体育馆 → 读球：1996 年 8 月 25 日，省体育馆","transition":"feather","intro":true,"uid":"10-5:0"},{"t":"dialog","scene":"oldgym","lines":[["nar","老体育馆。场中间放着那个玻璃罐。老南站在罐子前面，朱老师站在他旁边。两个老人，隔着一步的距离。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","你开。","talk",null,{"direction":"","speaker":"老南"}],["zhu","你的罐子。","talk",null,{"direction":"","speaker":"朱老师"}],["nan","……三十年，我不敢开。","talk",null,{"direction":"","speaker":"老南"}],["zhu","我也不敢。","talk",null,{"direction":"","speaker":"朱老师"}]],"when":null,"uid":"10-5:1"},{"t":"dialog","scene":"oldgym","lines":[["nar","两个人对视。然后，两只苍老的手一起拧开了罐子。封条“嘶”地一声裂开，像一口憋了三十年的气。","stage",null,{"silent":true,"cue":null,"white":false,"black":false,"cg":"cg-jar"}],["nar","球放进蒸笼。所有人戴上头环。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false,"cg":"cg-jar"}]],"when":null,"uid":"10-5:2"},{"t":"dialog","scene":"historic1996","lines":[["nar","羽场里，是 1996 年的省体育馆。黄色的灯，木头看台，墙上挂着手写的比分牌：13 : 4。二十八岁的南振站在场上，领先。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","玩家操控二十八岁的南振。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"10-5:3"},{"t":"match","as":"nan","opp":"zhu","field":"memory","level":"normal","target":15,"cap":15,"allowLoss":true,"stars":[],"skills":false,"startScore":[13,4],"oldScoring":true,"fear":true,"gentle":true,"age":[28,30],"intentSide":0,"intents":["还有两分","别输","别输","别杀，杀出界就完了","别输别输别输"],"venue":"historicourt","uid":"10-5:4"},{"t":"dialog","scene":"historic1996","lines":[["nar","还有两分","intent",null,{"title":"球记得的念头"}],["nar","别输","intent",null,{"title":"球记得的念头"}],["nar","别输","intent",null,{"title":"球记得的念头"}],["nar","别杀，杀出界就完了","intent",null,{"title":"球记得的念头"}],["nar","别输别输别输","intent",null,{"title":"球记得的念头"}],["ruibao","……他一直在想“别输”。","think",null,{"direction":"天上的声音，很轻","speaker":"瑞宝"}],["nan","……","talk",null,{"direction":"现实中，戴着头环，声音发哑","speaker":"老南"}],["nar","14 平。按当年的规则，先到 14 分的南振可以选择“加分”，把这一局延长到 17 分。裁判看向他。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","别拖了，早点结束","intent",null,{"title":"球记得的念头"}],["nan","……不加。","talk",null,{"direction":"","speaker":"二十八岁的南振"}],["nar","一球定胜负。朱启明发球。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","慢镜头。 三十岁的朱启明站在发球区，拍子往后引——","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","拍框高过了握拍的手。 清清楚楚，高了一指。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","球擦着网带翻过去，落进南振的发球区。南振没有动。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","（三十岁的朱启明）……手好像高了？","intent",null,{"title":"球记得的念头"}],["nar","（三十岁的朱启明）……裁判没判","intent",null,{"title":"球记得的念头"}],["nar","（三十岁的朱启明）……","intent",null,{"title":"球记得的念头"}],["nar","最后一行意图是空的，和 2022 年那天少年田楚的一模一样。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"10-5:5"},{"t":"dialog","scene":"oldgym","lines":[["nar","记忆显影完成。现实中，体育馆里很安静。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["zhu","南振。","sad",null,{"direction":"摘下头环，声音在抖","speaker":"朱老师"}],["zhu","……是我违例了。对不起。","talk",null,{"direction":"","speaker":"朱老师"}],["zhu","三十年了，对不起。","talk",null,{"direction":"","speaker":"朱老师"}],["nan","……我知道。我一直知道。","sad",null,{"direction":"低着头，很久","speaker":"老南"}],["nar","老南抬起头，看着空荡荡的球场。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","可我刚才，看见了另一件事。","talk",null,{"direction":"","speaker":"老南"}],["nan","从十三比四开始，我就在想“别输”。一拍都没想过“赢”。","think",null,{"direction":"","speaker":"老南"}],["nan","……我不是输在那一个发球上。","talk",null,{"direction":"","speaker":"老南"}],["nar","老南笑了一下，很短，很苦，又好像终于松开了什么。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","三十年，我把整个省的球都读了一遍，就是没读我自己。","talk",null,{"direction":"","speaker":"老南"}],["nar","朱老师看着他。两个老人站在球场中间，谁都没再说话。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nan","……再发一个。","talk",null,{"direction":"弯腰从地上捡起一只球","speaker":"老南"}],["zhu","……现在？","talk",null,{"direction":"","speaker":"朱老师"}],["nan","现在。（走到对面的接发区）这次，手放低一点。","talk",null,{"direction":"","speaker":"老南"}]],"when":null,"uid":"10-5:6"},{"t":"match","as":"zhu","opp":"nan","field":"reality","level":"normal","target":1,"cap":1,"allowLoss":true,"stars":[],"skills":false,"rallyGoal":16,"gentle":true,"freeze":true,"age":[60,58],"venue":"homecourt","uid":"10-5:7"},{"t":"dialog","scene":"oldgym","lines":[["nar","最后一回合，玩家操控六十岁的朱老师。 没有技能，没有意图，没有胜率屏。两个老人在一座老体育馆里打一个回合。孩子们坐在场边。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","朱老师发了一个规规矩矩的球，拍框低于握拍的手。老南回了一个高远。朱老师回了一个吊球。老南扑上网……","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","回合越来越长。两个人都气喘吁吁，都在笑。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","第十六拍。老南起跳，扣杀，这是他三十年来第一次在赢面不确定的时候扣杀。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","球飞向朱老师的反手。朱老师伸出拍子——","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"10-5:8"},{"t":"dialog","scene":"oldgym","lines":[["nar","画面定格。 球停在半空中，离地板还有一指。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-last"}],["nar","白屏。","stage",null,{"silent":false,"cue":null,"white":true,"black":false,"cg":"cg-last"}],["nar","字幕：球落地之前，谁都不知道。","stage",null,{"silent":false,"cue":null,"white":false,"black":false,"cg":"cg-last"}],["nar","黑屏中，传来一声苍老的大笑。是老南。然后是朱老师的笑声。","stage",null,{"silent":false,"cue":null,"white":false,"black":true,"cg":"cg-last"}],["nan","下周三，老地方。","talk",null,{"direction":"声音","speaker":"老南","cg":"cg-last"}],["zhu","……带保温杯。","talk",null,{"direction":"声音","speaker":"朱老师","cg":"cg-last"}]],"when":null,"uid":"10-5:9"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]},{"id":"ch11","title":"终章 · 第十六根羽毛","date":"8.29—8.30","scene":"riverbank","blurb":"有一根空着，它也能飞。","venue":"homecourt","act":"说出来","stages":[{"id":"11-1","title":"八月二十九日","scene":"townsquare","date":"8 月 29 日 · 全镇","desc":"和每个人道别（全部见完解锁 11-2）","knowledge":[],"kind":"inspect","steps":[{"t":"cinema","scene":"townsquare","title":"八月二十九日","caption":"8 月 29 日 · 全镇","transition":"feather","intro":true,"uid":"11-1:0"},{"t":"dialog","scene":"townsquare","lines":[["nar","夏天的最后几天。鹅毛还在晒，鹅还在街上走。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"11-1:1"},{"t":"inspect","scene":"townsquare","title":"和每个人说一声再见","items":[{"id":"farewell-ruibao","label":"王记包子铺","text":"瑞宝：明年六月，我再考一次。反正包子一直都在。王爸：稳住。","clue":"farewell-ruibao","x":0.17,"y":0.28},{"id":"farewell-houzi","label":"网吧二楼","text":"直播间在线 8 人。新来的 ID 叫“师兄”，每次都刷“还行”。","clue":"farewell-houzi","x":0.48,"y":0.28},{"id":"farewell-bobo","label":"采石场","text":"波波还在希望那是羽毛；苗苗决定读运动科学。大将军在吃草。","clue":"farewell-bobo","x":0.79,"y":0.28},{"id":"farewell-stars","label":"气象站天台","text":"第三十七页只有一行星星的字：结论，不用写。","clue":"farewell-stars","x":0.17,"y":0.5},{"id":"farewell-zhu","label":"老体育馆","text":"凌风当助教了。门口站着田楚，拿着那支二十四磅的拍子。","clue":"farewell-zhu","x":0.48,"y":0.5},{"id":"farewell-guoge","label":"果然健身","text":"唯一一次大赚：押丁丁，1 赔 30 包。可是还欠王记一百包。","clue":"farewell-guoge","x":0.79,"y":0.5},{"id":"farewell-lu","label":"实习办公室","text":"模型无法预测十六个人。原因：他们会变。","clue":"farewell-lu","x":0.17,"y":0.72},{"id":"farewell-nan","label":"穿线铺门口","text":"老南在第十五根羽毛上画了打开的罐子。剩下那根，你自己写。","clue":"farewell-nan","x":0.48,"y":0.72}],"uid":"11-1:2"},{"t":"dialog","scene":"townsquare","lines":[["nar","王记包子铺：瑞宝在柜台后面揉面，王爸坐在门口晒太阳，已经能自己站起来走两步了。","stage",null,{}],["ruibao","“明年六月，我再考一次。考得好就去，考不好就再开一年店。”（停顿）“反正包子一直都在。”","talk",null,{"direction":"","speaker":"瑞宝"}],["wangba","“稳住。”","talk",null,{"direction":"举起手机","speaker":"王爸"}],["nar","网吧二楼：猴子的直播间人数变成了 8。","stage",null,{}],["houzi","“多了一个！你猜是谁？”","talk",null,{"direction":"","speaker":"猴子"}],["dingding","“……谁？”","talk",null,{"direction":"","speaker":"丁丁"}],["houzi","“田楚。ID 叫‘师兄’。他每次都刷‘还行’。”","talk",null,{"direction":"","speaker":"猴子"}],["nar","采石场：波波和苗苗蹲在石壁前，大将军在旁边吃草。","stage",null,{}],["bobo","“苗苗说她不回南岸了。”","talk",null,{"direction":"","speaker":"波波"}],["miaomiao","“我想去读运动科学。以后……我想研究怎么让人失误了也不怕。”（停顿）“老南说，我从来不欠他的。”","think",null,{"direction":"","speaker":"苗苗"}],["bobo","“丁丁！这次是真的！是一根羽毛的印子！”","talk",null,{"direction":"举起一块石头，激动地","speaker":"波波"}],["miaomiao","“……是叶子。”","talk",null,{"direction":"看了一眼","speaker":"苗苗"}],["bobo","“……没关系，我明天继续希望。”","talk",null,{"direction":"","speaker":"波波"}],["nar","苗苗笑了。大将军也叫了一声。","stage",null,{}],["nar","气象站天台：小红和星星在收望远镜。","stage",null,{}],["xiaohong","“下一次英仙座，明年八月十二号。我已经订好票了。”","talk",null,{"direction":"","speaker":"小红"}],["xingxing","“那你去年的计划书呢？”","talk",null,{"direction":"","speaker":"星星"}],["xiaohong","“晒干了。第三十七页我写上了。”","talk",null,{"direction":"","speaker":"小红"}],["dingding","“写的什么？”","talk",null,{"direction":"","speaker":"丁丁"}],["xiaohong","“结论：不用写。”","talk",null,{"direction":"翻开，那一页只有一行字，是星星的笔迹","speaker":"小红"}],["nar","镇一中老体育馆：周六课。凌风在教几个更小的孩子扑救。他手里那支旧拍子，拍柄上贴着一条胶布：“丁丁 2018”。","stage",null,{}],["lingfeng","“丁丁哥！我当助教了！”","talk",null,{"direction":"","speaker":"凌风"}],["zhu","“明年开始，周六课有新老师了。”","talk",null,{"direction":"场边","speaker":"朱老师"}],["dingding","“谁？”","talk",null,{"direction":"","speaker":"丁丁"}],["zhu","（笑而不语，看向门口）门口站着田楚，手里拿着那支 24 磅的旧拍子。","smile",null,{"direction":"","speaker":"朱老师"}],["nar","果然健身：白板上的竞猜赔率被擦掉了，换成一行大字：“本店历史上唯一一次大赚：押丁丁，1 赔 30 包”。","stage",null,{}],["guoge","“我这辈子第一次押小概率！赢了三十包！”","talk",null,{"direction":"","speaker":"果哥"}],["ruibao","“你还欠我家一百包。”","talk",null,{"direction":"路过","speaker":"瑞宝"}],["guoge","“……持平。”","talk",null,{"direction":"","speaker":"果哥"}],["nar","南岸实习办公室（已清空）：路先森和老陈在收拾东西。路先森的电脑屏幕上是他模型的 README。","stage",null,{}],["nar","本模型无法预测以下人员： 丁丁、王瑞、猴子、小红、星星、冉冉、波波、苗苗、凌风、沧澜、朱启明、果哥、老陈、田楚、南振、路先森。","stage",null,{}],["nar","原因： 他们会变。","stage",null,{}],["laochen","“你把自己也写进去了。”","talk",null,{"direction":"","speaker":"老陈"}],["lu","“我也会变啊。”（停顿）“比如我现在决定，以后讲的笑话，都要好笑。”","smile",null,{"direction":"","speaker":"路先森"}],["laochen","“……这个预测不会成立。”","talk",null,{"direction":"","speaker":"老陈"}],["nar","穿线铺（最后一站）：老南站在铺子门口，看着墙上的球拍。","stage",null,{}],["nan","“南岸以后只读落点。读人，要本人签字。”","talk",null,{"direction":"","speaker":"老南"}],["dingding","“……谢谢。”","talk",null,{"direction":"","speaker":"丁丁"}],["nan","“你那只球，给我看看。”","talk",null,{"direction":"","speaker":"老南"}],["nar","丁丁把那只手工球递过去。老南看着那两根空着的羽毛，从口袋里掏出一支笔，在其中一根上画了一个很小的符号：一个圆圈，开口朝上，像一个打开的罐子。","stage",null,{}],["nan","“第十五根。”","talk",null,{"direction":"","speaker":"老南"}],["nan","“……剩下那根，你自己写。”","talk",null,{"direction":"","speaker":"老南"}]],"when":null,"uid":"11-1:3"}],"rewards":{"cards":[],"chars":["nan"],"gear":[]},"feather":"nan"},{"id":"11-2","title":"渡口","scene":"ferry","date":"8 月 29 日 傍晚 · 渡船上","desc":"有一根空着，它也能飞。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"ferry","title":"渡口","caption":"8 月 29 日 傍晚 · 渡船上","transition":"feather","intro":true,"uid":"11-2:0"},{"t":"dialog","scene":"ferry","lines":[["nar","夕阳，江面。沧澜撑着船，船上坐着一个乘客。田楚。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["canglan","一块钱。","talk",null,{"direction":"","speaker":"沧澜"}],["tianchu","……四年没坐了。","talk",null,{"direction":"掏出一块钱硬币，放在船头","speaker":"田楚"}],["canglan","车在码头停了快两个月，你一直没过江。","talk",null,{"direction":"","speaker":"沧澜"}],["tianchu","……不知道怎么开口。","talk",null,{"direction":"","speaker":"田楚"}],["nar","船到江心。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","那年我走，没跟你说再见。","talk",null,{"direction":"","speaker":"田楚"}],["canglan","嗯。","talk",null,{"direction":"","speaker":"沧澜"}],["tianchu","……对不起。","talk",null,{"direction":"","speaker":"田楚"}],["canglan","不是这句。","talk",null,{"direction":"","speaker":"沧澜"}],["tianchu","……","talk",null,{"direction":"","speaker":"田楚"}],["canglan","你现在说。","talk",null,{"direction":"","speaker":"沧澜"}],["tianchu","……再见？","talk",null,{"direction":"","speaker":"田楚"}],["canglan","不对。","smile",null,{"direction":"笑了，撑着篙，看着江面","speaker":"沧澜"}],["canglan","是“好久不见”。","talk",null,{"direction":"","speaker":"沧澜"}],["nar","田楚愣了一下，然后低下头，笑出了声。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["tianchu","……好久不见。","talk",null,{"direction":"","speaker":"田楚"}],["canglan","好久不见。","talk",null,{"direction":"","speaker":"沧澜"}]],"when":null,"uid":"11-2:1"},{"t":"dialog","scene":"ferry","lines":[["tianchu","那天在仓库，丁丁看了我的画像吗？","talk",null,{"direction":"","speaker":"田楚"}],["canglan","他说看了。他说他只记住了一个字，“累”。","talk",null,{"direction":"","speaker":"沧澜"}],["tianchu","……","talk",null,{"direction":"","speaker":"田楚"}]],"when":{"choice":"profile","value":"read"},"uid":"11-2:2"},{"t":"dialog","scene":"ferry","lines":[["tianchu","那天在仓库，丁丁看了我的画像吗？","talk",null,{"direction":"","speaker":"田楚"}],["canglan","没有。他说，他想听你自己说。","think",null,{"direction":"","speaker":"沧澜"}],["tianchu","……这小子。","talk",null,{"direction":"很久","speaker":"田楚"}]],"when":{"choice":"profile","value":"wait"},"uid":"11-2:3"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"11-3","title":"两只球","scene":"riverbank-night","date":"8 月 29 日 夜 · 江堤（0-2 的那块空地）","desc":"有一根空着，它也能飞。","knowledge":[],"kind":"special","steps":[{"t":"cinema","scene":"riverbank-night","title":"两只球","caption":"8 月 29 日 夜 · 江堤（0-2 的那块空地）","transition":"feather","intro":true,"uid":"11-3:0"},{"t":"dialog","scene":"riverbank-night","lines":[["nar","江堤下的水泥空地，两根竹竿和一根绳。冉冉坐在台阶上，旁边放着一个行李箱。明天一早她就要走了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","丁丁走过来，手里拿着两只球。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","……你来了。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","嗯。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","邀请函，我没去。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……为什么？","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","我想打球，不想被读。（停顿）我去读大学，学校有羽毛球队。我自己挑的。","think",null,{"direction":"","speaker":"冉冉"}],["dingding","……挺好的。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","你再说一遍“挺好的”试试。","talk",null,{"direction":"瞪他","speaker":"冉冉"}],["dingding","……对不起。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","丁丁把第一只球递给她。球上贴着一截发黄的胶带：“冉冉 6.26 不读”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","这是你的。那天你随手放在台阶上的。我拿走了。（停顿）一直没读。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","冉冉看着那张胶带，看了很久。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","……一次都没读？","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","那是你的球。","talk",null,{"direction":"","speaker":"丁丁"}],["nar","冉冉低下头，把那只球握在手心里。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","丁丁又递过去第二只球。手工做的，十六根羽毛，十五根有记号。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","这个……也给你。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","包子、猴子、恐龙、星星……蝴蝶结，是我的。（停在最后一根上）这根怎么是空的？","talk",null,{"direction":"转着球看，一根一根看那些记号","speaker":"冉冉"}],["dingding","……那根，我想说出来。","think",null,{"direction":"","speaker":"丁丁"}],["ranran","那你现在说。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","丁丁张开嘴。江风吹过来。他说不出来。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","我……我先让你看看。（指着那只球）决赛最后那一分，是这只球打的。你……你拿回去读。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","……你这人。","smile",null,{"direction":"看着他，很久，叹了口气，然后又笑了","speaker":"冉冉"}],["ranran","好。我去读。（站起来）你在外面等着。","talk",null,{"direction":"","speaker":"冉冉"}]],"when":null,"uid":"11-3:1"},{"t":"dialog","scene":"riverbank-night","lines":[["ranran","你真挂上了啊。","talk",null,{"direction":"指着他拍柄上那个白色蝴蝶结","speaker":"冉冉"}],["dingding","……说了挂拍子上。","talk",null,{"direction":"","speaker":"丁丁"}]],"when":{"choice":"bow","value":"white"},"uid":"11-3:2"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"11-4","title":"进羽","scene":"backroom","date":"8 月 29 日 深夜 · 穿线铺后屋 → 读球：8 月 25 日，接力决战最后一分","desc":"有一根空着，它也能飞。","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"backroom","title":"进羽","caption":"8 月 29 日 深夜 · 穿线铺后屋 → 读球：8 月 25 日，接力决战最后一分","transition":"feather","intro":true,"uid":"11-4:0"},{"t":"dialog","scene":"backroom","lines":[["nar","冉冉一个人坐在后屋，戴上头环。丁丁坐在铺子门口的台阶上，背对着门，看着满街的鹅毛。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false}]],"when":null,"uid":"11-4:1"},{"t":"dialog","scene":"oldgym","lines":[["nar","羽场里，是三天前的老体育馆，接力决战最后一分。老南站在对面，复刻着所有人的技能。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"11-4:2"},{"t":"match","as":"dingding","opp":"nan","field":"memory","level":"normal","target":1,"cap":1,"allowLoss":true,"stars":[],"gentle":true,"rallyGoal":12,"intentSide":0,"intents":["冉冉在看","冉冉在看","接住，接住","瑞宝在喊","师兄在看","……她在那边","赢了就说","这次一定说"],"venue":"homecourt","uid":"11-4:3"},{"t":"dialog","scene":"oldgym","lines":[["nar","玩家操控丁丁，重打这一分。 每一拍，丁丁头顶都浮起意图：","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","冉冉在看","intent",null,{"title":"球记得的念头"}],["nar","冉冉在看","intent",null,{"title":"球记得的念头"}],["nar","接住，接住","intent",null,{"title":"球记得的念头"}],["nar","瑞宝在喊","intent",null,{"title":"球记得的念头"}],["nar","师兄在看","intent",null,{"title":"球记得的念头"}],["nar","冉冉在看","intent",null,{"title":"球记得的念头"}],["nar","第二十七拍。“标准答案”亮起。丁丁往冉冉的方向迈了一步。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","……她在那边","intent",null,{"title":"球记得的念头"}],["nar","最后一拍。悠悠球拍飞出去，又绕回来。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","赢了就说","intent",null,{"title":"球记得的念头"}],["nar","球落地。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","这次一定说","intent",null,{"title":"球记得的念头"}],["nar","记忆显影完成。冉冉摘下头环，一个人坐在蒸笼的白光里。她在笑，眼泪掉下来，又笑。","stage","enter",{"silent":false,"cue":"enter","white":false,"black":false}]],"when":null,"uid":"11-4:4"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null},{"id":"11-5","title":"你说","scene":"stringing-night","date":"8 月 29 日 深夜 → 8 月 30 日 清晨 · 穿线铺门口","desc":"有一根空着，它也能飞。","knowledge":[],"kind":"match","steps":[{"t":"cinema","scene":"stringing-night","title":"你说","caption":"8 月 29 日 深夜 → 8 月 30 日 清晨 · 穿线铺门口","transition":"feather","intro":true,"uid":"11-5:0"},{"t":"dialog","scene":"stringing-night","lines":[["nar","门开了。冉冉走出来，在丁丁旁边的台阶上坐下。两个人都没说话。一只鹅从他们面前走过去。","stage","door",{"silent":false,"cue":"door","white":false,"black":false}],["ranran","我看完了。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……嗯。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","你赢了。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","嗯。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","“赢了就说。”","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","那你说啊。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","很长的沉默。江风，鹅毛，路灯。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","冉冉。","talk",null,{"direction":"","speaker":"丁丁"}],["dingding","我喜欢你。","shy",null,{"direction":"","speaker":"丁丁"}],["dingding","从你在拍柄上系蝴蝶结那天开始。三年。一千零九十五天。（停顿）小红帮我算的。","think",null,{"direction":"","speaker":"丁丁"}],["nar","冉冉看着他，没有说话。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","……我知道。","talk",null,{"direction":"","speaker":"冉冉"}],["ranran","球都告诉我了。","talk",null,{"direction":"","speaker":"冉冉"}],["ranran","但我想听你说。","think",null,{"direction":"","speaker":"冉冉"}],["nar","她把那只贴着“不读”胶带的球放回丁丁手里。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ranran","这只，现在你可以读了。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","去读。我在这儿等你。","talk",null,{"direction":"","speaker":"冉冉"}],["nar","最后一次读球。 极短。6 月 26 日，河堤，那个又慢又软的网前小球。这一次，玩家操控冉冉。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"11-5:1"},{"t":"match","as":"ranran","opp":"dingding","field":"memory","level":"normal","target":1,"cap":1,"allowLoss":true,"stars":[],"skills":false,"gentle":true,"rallyGoal":3,"intentSide":0,"intents":["他终于来打球了","四年了","给他一个接得到的","接住啦"],"venue":"memorycourt","uid":"11-5:2"},{"t":"dialog","scene":"stringing-night","lines":[["nar","他终于来打球了","intent",null,{"title":"球记得的念头"}],["nar","四年了","intent",null,{"title":"球记得的念头"}],["nar","给他一个接得到的","intent",null,{"title":"球记得的念头"}],["nar","丁丁在对面往前跑，把球挑了起来。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","接住啦","intent",null,{"title":"球记得的念头"}],["nar","记忆结束。丁丁摘下头环，走出门。冉冉还坐在台阶上，天边已经开始发白。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["dingding","……你等了四年？","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","你在拍子上穿了二十二磅，BG65，白色。我在拍柄上系了个蝴蝶结。（停顿）我以为你会来问。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……对不起。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","别对不起。（站起来，拎起行李箱）我们学校离你们学校，坐地铁四十分钟。我查过了。","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……你也算这个？","think",null,{"direction":"","speaker":"丁丁"}],["ranran","跟小红学的。（转身往码头走，走了几步，回头）丁丁！","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","嗯？","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","那根空着的羽毛——","talk",null,{"direction":"","speaker":"冉冉"}],["dingding","……我已经说出来了。","talk",null,{"direction":"","speaker":"丁丁"}],["ranran","嗯。所以它就一直空着吧。","smile",null,{"direction":"笑了","speaker":"冉冉"}],["nar","冉冉走向码头。沧澜的渡船在晨雾里等着。丁丁站在穿线铺门口，看着她，一直看到船消失在雾里。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}]],"when":null,"uid":"11-5:3"},{"t":"dialog","scene":"bakery","lines":[["nar","九月。清晨。王记包子铺。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","黑屏。“嗒。”停一下，又一声“嗒”。","stage","clamp",{"silent":false,"cue":"clamp","white":false,"black":true}],["nar","画面亮起。九月。清晨。王记包子铺。蒸笼一摞一摞冒着白汽。瑞宝一个人站在灶台前，蒸笼已经垫平了。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","快递员送来一个长条包裹。瑞宝拆开，是一支球拍，拍柄上用记号笔写着：","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","瑞宝专用 · 二十四磅 · 别给我打断了","stage",null,{}],["nar","——丁","stage",null,{}],["nar","瑞宝拿着拍子，在空荡荡的店里挥了一下。蒸笼的汽声，“嘶”。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["ruibao","……挺好的。","talk",null,{"direction":"自言自语","speaker":"瑞宝"}],["nar","这一次，他是真的笑着说的。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","镜头拉远。整条街，晒着的鹅毛，走来走去的鹅，对面已经关门的穿线铺，门上贴着一张纸：“店主上学去了，十一回来。急事找对面包子铺。”","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","字幕：","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","一只羽毛球有十六根羽毛。","stage",null,{}],["nar","少一根，它就会飘。","stage",null,{}],["nar","有一根空着，它也能飞。","stage",null,{}],["nar","字幕之后，还有几只球没有落地。","stage",null,{"silent":false,"cue":null,"white":false,"black":false}],["nar","1. 老体育馆 · 周三傍晚：两个老人在打球。场边放着两个保温杯。老南擦网得了一分。他愣了一下，然后举起左手：“……对不起。”朱老师笑得直不起腰。","stage",null,{}],["nar","2. 采石场 · 某天：波波终于挖出了一块真正的、带羽毛印痕的化石。他转过头想叫苗苗，却发现苗苗和大将军都已经在他身后看着了。（→ 番外一）","stage",null,{}],["nar","3. 省城 · 大学羽毛球馆：冉冉在网前轻轻一放，对面的新队员没接到。她笑着说：“接住啦——哦，没接住。”场边，一个戴眼镜的小个子男生举着一支穿好线的拍子，站在门口。","stage",null,{}],["nar","4. 南岸大楼 · 罐子屋：所有玻璃罐都被打开了，球被一只一只装进纸箱，箱子上写着“归还本人”。最后剩下一个空罐子，标签上写着：“1996.8.25 · 已读”。（→ 番外三）","stage",null,{}]],"when":null,"uid":"11-5:4"}],"rewards":{"cards":[],"chars":[],"gear":[]},"feather":null}]}];Y.SIXTEEN_CARDS=[{"id":"v3_01","num":"01","title":"磅数","cat":"gear","text":"球拍线拉得越紧，磅数越高：控球更准，但甜区变小、对手腕要求更高，也更容易断。新手常用 20—24 磅。线穿好后会慢慢变松，叫“掉磅”。天冷时球线会收紧变脆，所以冬天很多人会把磅数降一两磅。","source":"screenplay"},{"id":"v3_02","num":"02","title":"高远球为什么先快后慢","cat":"tech","text":"羽毛球的裙片像一把小降落伞，空气阻力非常大。高远球刚出手时很快，飞到高处后迅速减速，最后几乎是垂直落下来的。所以接高远球要站在落点稍后，等它掉下来。","source":"screenplay"},{"id":"v3_03","num":"03","title":"握拍","cat":"tech","text":"最常用的是“握手式”：像跟球拍握手一样，虎口对着拍柄窄面。手指放松，击球的瞬间再握紧。反手时拇指可以顶在拍柄宽面上发力。","source":"screenplay"},{"id":"v3_04","num":"04","title":"发球高度","cat":"rule","text":"发球时，击球瞬间整只球必须低于离地 1.15 米（世界羽联 2018 年起试行的固定高度规则）。在这之前的规则是“击球点低于腰部、拍框低于握拍手”。","source":"screenplay"},{"id":"v3_05","num":"05","title":"计分规则","cat":"rule","text":"正式比赛三局两胜，每局 21 分，每球得分；20 平后要领先 2 分，29 平时先到 30 分者胜。一局中领先一方先到 11 分时有 60 秒间歇，局与局之间休息 2 分钟。（游戏为了节奏改成 7 分一局。）","source":"screenplay"},{"id":"v3_06","num":"06","title":"启动步","cat":"tech","text":"对手击球的那一刻，双脚轻轻一跳（垫步），落地的一瞬间朝球的方向蹬出去。看起来是多了一个动作，实际起步会快很多。","source":"screenplay"},{"id":"v3_07","num":"07","title":"防守站位","cat":"tactic","text":"接杀时降低重心，双脚略宽于肩，拍子举在身前。不要站得太靠后，大部分扣杀落在中场附近。","source":"screenplay"},{"id":"v3_08","num":"08","title":"抢高点","cat":"tech","text":"击球点越高，球路越多、下压角度越大、对手反应时间越短。所以高手总在“抢点”：能在头顶打的绝不等到胸口。","source":"screenplay"},{"id":"v3_09","num":"09","title":"一只球的十六根羽毛","cat":"gear","text":"比赛用球由 16 根羽毛插在软木球托上制成，羽毛长 62—70 毫米，整只球重 4.74—5.50 克。少一根或折一根，球就会飞歪。","source":"screenplay"},{"id":"v3_10","num":"10","title":"擦网","cat":"rule","text":"回合中，球擦网后落进对方界内，有效。发球擦网后落进正确的发球区，同样有效。羽毛球没有网球那样的“擦网重发”。","source":"screenplay"},{"id":"v3_11","num":"11","title":"触网与过网击球","cat":"rule","text":"回合进行中，球拍、身体或衣服碰到球网是违例。击球点必须在自己这一侧，但击球后球拍随挥过网是允许的。","source":"screenplay"},{"id":"v3_12","num":"12","title":"直线与斜线","cat":"tactic","text":"斜线（对角线）距离更长，球在空中的时间更久，留给对手的反应时间更多，但能把对手调动得更远；直线距离短、速度快，但更容易被拦截。","source":"screenplay"},{"id":"v3_13","num":"13","title":"英仙座流星雨","cat":"fun","text":"每年 8 月 12—13 日前后极大，是北半球夏季最稳定的流星雨之一，来自斯威夫特—塔特尔彗星留下的尘埃。（和羽毛球没关系，但和小红有关系。）","source":"screenplay"},{"id":"v3_14","num":"14","title":"米字步","cat":"tech","text":"以场地中心为“家”，向前、后、左前、右前、左后、右后六个方向移动击球，每打完一球都回到中心。这是羽毛球步法训练的基础。","source":"screenplay"},{"id":"v3_15","num":"15","title":"擦网要举手","cat":"rule","text":"擦网得分是规则允许的，但很多选手会举手向对方示意“抱歉，运气好”。这不是规则要求，是球场上的礼貌。","source":"screenplay"},{"id":"v3_16","num":"16","title":"假动作","cat":"tech","text":"高手常用同一个引拍动作打出完全不同的球：看起来要杀，实际轻吊；看起来要放网，手腕一抖变成推后场。破解的办法是不要过早启动，看清球离拍的方向再动。","source":"screenplay"},{"id":"v3_17","num":"17","title":"混双站位","cat":"tactic","text":"进攻时常用“前后站位”：一人封网，一人后场进攻；防守时转为“左右站位”，各守半边。传统上女选手在前场封网的情况更多，但现在也有很多灵活的打法。","source":"screenplay"},{"id":"v3_18","num":"18","title":"鱼跃要护住自己","cat":"tech","text":"职业选手的鱼跃救球需要大量专门训练和防护。业余打球时尽量用步法到位，不要在硬地上扑倒，保护好膝盖、手肘和下巴。","source":"screenplay"},{"id":"v3_19","num":"19","title":"连击与持球","cat":"rule","text":"同一方在一次回击中连续击球两次（连击），或者球在拍面上停留、被“托着”送出去（持球），都是违例。（游戏里的接力协议、停一下这类技能，只在羽场里成立。）","source":"screenplay"},{"id":"v3_20","num":"20","title":"习惯区与变线","cat":"tactic","text":"每个人都有自己最习惯的击球路线和站位。比赛中高水平的选手会观察对手的习惯，再通过“变线”打破规律：同样的位置，这次打直线，下次打斜线。","source":"screenplay"},{"id":"v3_21","num":"21","title":"球拍重量与平衡点","cat":"gear","text":"球拍用“U”表示重量：3U 约 85—89 克，4U 约 80—84 克，5U 约 75—79 克。平衡点靠拍头叫“头重”，扣杀更有力；靠拍柄叫“头轻”，挥拍和防守更快。中杆越硬，弹性越小，更适合力量大的人。","source":"screenplay"},{"id":"v3_22","num":"22","title":"正手毛与反手毛","cat":"gear","text":"一只球的 16 根羽毛必须取自鹅（或鸭）同一侧翅膀，弧度一致，飞行时才能稳定旋转。每边翅膀只有六七根羽毛适合做球，所以一只好球要用到好几只鹅的羽毛。","source":"screenplay"},{"id":"v3_23","num":"23","title":"老规则","cat":"rule","text":"2006 年以前，羽毛球采用“发球得分制”：只有发球方赢了回合才得分，接发方赢了只是夺回发球权。男子单打一局 15 分；在 13 平或 14 平时，先到这个分数的一方可以选择“加分”，把这一局延长几分。","source":"screenplay"},{"id":"v3_24","num":"24","title":"测球","cat":"gear","text":"比赛前要测试球速：站在底线，从下往上全力把球击向对面。合格的球应落在对面底线前 530—990 毫米之间。太远说明球太快，太近说明太慢。天热、海拔高时空气稀薄，要选慢一点的球。","source":"screenplay"}];Y.LEGACY_STAGE_ORDER=[];})(typeof GameGlobal!=='undefined'?GameGlobal:typeof window!=='undefined'?window:globalThis);
